# ─── 📢 چنلِ آرشیو (لیست/گزارش/کارنامه‌ی هر بازی) ────────────────
SETTINGS_FILENAME = "bot_settings.json"
_SETTINGS_CACHE = {"data": None}


def load_bot_settings(force=False) -> dict:
    if _SETTINGS_CACHE["data"] is not None and not force:
        return _SETTINGS_CACHE["data"]
    try:
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        r = httpx.get(url, headers=headers)
        if r.status_code == 200:
            content = r.json().get("files", {}).get(SETTINGS_FILENAME, {}).get("content", "{}")
            _SETTINGS_CACHE["data"] = json.loads(content) or {}
        else:
            _SETTINGS_CACHE["data"] = {}
    except Exception as e:
        print("❌ load_bot_settings:", e)
        _SETTINGS_CACHE["data"] = {}
    return _SETTINGS_CACHE["data"]


def save_bot_settings(data: dict):
    _SETTINGS_CACHE["data"] = data
    try:
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        httpx.patch(url, headers=headers, json={"files": {SETTINGS_FILENAME: {
            "content": json.dumps(data, ensure_ascii=False, indent=2)}}})
    except Exception as e:
        print("❌ save_bot_settings:", e)


def get_archive_channel():
    """آیدی/یوزرنیمِ چنلِ آرشیو (یا None اگر تنظیم نشده)."""
    v = (load_bot_settings() or {}).get("archive_channel")
    return v or (os.getenv("ARCHIVE_CHANNEL") or None)


async def _send_chunked(bot, chat_id, text, limit=3500):
    """ارسالِ متنِ بلند در چند تکه (محدودیتِ ۴۰۹۶ کاراکتریِ تلگرام)."""
    sent = []
    chunk = ""
    for line in text.split("\n"):
        if len(chunk) + len(line) + 1 > limit:
            if chunk.strip():
                try:
                    sent.append(await bot.send_message(chat_id, chunk, parse_mode="HTML"))
                except Exception as e:
                    print(f"⚠️ chunk send failed ({chat_id}):", e)
            chunk = ""
        chunk += (line + "\n")
    if chunk.strip():
        try:
            sent.append(await bot.send_message(chat_id, chunk, parse_mode="HTML"))
        except Exception as e:
            print(f"⚠️ chunk send failed ({chat_id}):", e)
    return sent


async def archive_game_to_channel(bot, header, final_text, report_text=None, score_text=None):
    """📢 لیست پایانی + گزارش شب‌به‌شب + کارنامه‌ی امتیاز → چنلِ آرشیو."""
    ch = get_archive_channel()
    if not ch:
        return False
    try:
        await _send_chunked(bot, ch, header + "\n" + final_text)
        if report_text:
            await _send_chunked(bot, ch, report_text)
        if score_text:
            await _send_chunked(bot, ch, score_text)
        return True
    except Exception as e:
        print("⚠️ archive_game_to_channel:", e)
        return False


def load_selected_list() -> dict:
    try:
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {
            "Authorization": f"token {GH_TOKEN}",
            "Accept": "application/vnd.github+json",
        }
        response = httpx.get(url, headers=headers)
        if response.status_code == 200:
            gist_data = response.json()
            content = gist_data["files"].get(SELECTED_FILENAME, {}).get("content", "{}")
            return json.loads(content) or {}
        return {}
    except Exception as e:
        print("❌ load_selected_list error:", e)
        return {}

def save_selected_list(data: dict):
    try:
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {
            "Authorization": f"token {GH_TOKEN}",
            "Accept": "application/vnd.github+json",
        }
        payload = {
            "files": {
                SELECTED_FILENAME: {
                    "content": json.dumps(data, ensure_ascii=False, indent=2)
                }
            }
        }
        httpx.patch(url, headers=headers, json=payload)
    except Exception as e:
        print("❌ save_selected_list error:", e)


def kb_selected_days(selected_days) -> InlineKeyboardMarkup:
    sel = set(selected_days or [])
    rows = []
    for idx, day in enumerate(SELECTED_DAYS):
        label = f"✅ {day}" if day in sel else day
        rows.append([InlineKeyboardButton(label, callback_data=f"selday_{idx}")])
    rows.append([InlineKeyboardButton("📝 ثبت", callback_data="sel_submit")])
    return InlineKeyboardMarkup(rows)


async def launch_selected_round(bot, candidates=None) -> int:
    """دور جدید لیست منتخب: کاندیداها را ثبت و به همه پیام دعوت می‌فرستد."""
    if candidates is None:
        current = load_player_stats() or {}
        meta = load_weekly_meta()
        snapshot = (meta or {}).get("snapshot", {})
        delta = _weekly_delta(current, snapshot)
        candidates = weekly_top_candidates(delta, 10)   # 🔗 همان رتبه‌بندیِ لیدربرد
        if not candidates:   # برای تست، اگر هفته خالی بود از کل دوران بگیر
            candidates = weekly_top_candidates(current, 10)

    if not candidates:
        return 0

    data = {
        "candidates": {str(uid): nm for uid, nm in candidates},
        "responses": {},
        "started_at": datetime.now().timestamp(),
    }
    save_selected_list(data)

    kb = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ بله", callback_data="sel_yes"),
        InlineKeyboardButton("❌ خیر", callback_data="sel_no"),
    ]])
    sent_names = []
    failed = []
    for uid, nm in candidates:
        try:
            await bot.send_message(
                int(uid),
                "🏆 تبریک! شما این هفته جزو ۱۰ نفر برتر شدید.\n\n"
                "آیا تمایل دارید در «لیست منتخب» شرکت کنید؟",
                reply_markup=kb,
            )
            sent_names.append(nm)
        except Exception as e:
            failed.append(nm)
            print(f"⚠️ selected invite failed for {uid}:", e)

    # اطلاع به ادمین دربارهٔ کسانی که پیام به آن‌ها نرسید
    if failed:
        try:
            await bot.send_message(
                ADMIN_ID,
                "⚠️ بات نتوانست به این افراد پیام دعوت بدهد "
                "(احتمالاً بات را استارت نکرده‌اند):\n"
                + "\n".join(f"• {escape(n, quote=False)}" for n in failed),
                parse_mode="HTML",
            )
        except Exception:
            pass

    return {"sent": sent_names, "failed": failed}


def build_selected_report(sl: dict) -> str:
    cand = sl.get("candidates", {})
    responses = sl.get("responses", {})

    def link(uid, name):
        nm = escape(name or "بازیکن", quote=False)
        return f"<a href='tg://user?id={uid}'>{nm}</a>"

    yes = [(u, r) for u, r in responses.items() if r.get("participate")]
    no = [(u, r) for u, r in responses.items() if not r.get("participate")]
    pending = [u for u in cand if u not in responses]

    lines = [
        "📋 <b>گزارش لیست منتخب</b>",
        f"کل کاندیداها: {len(cand)}",
        f"✅ مایل: {len(yes)} | ❌ غیرمایل: {len(no)} | ⏳ بی‌پاسخ: {len(pending)}",
        "",
    ]
    if yes:
        lines.append("✅ <b>مایل به شرکت:</b>")
        for u, r in yes:
            days = "، ".join(r.get("days", [])) or "—"
            mark = "" if r.get("submitted") else " (هنوز ثبت نکرده)"
            lines.append(f"• {link(u, r.get('name'))} (<code>{u}</code>) — {days}{mark}")
        lines.append("")
    if no:
        lines.append("❌ <b>غیرمایل:</b>")
        for u, r in no:
            lines.append(f"• {link(u, r.get('name'))} (<code>{u}</code>)")
        lines.append("")
    if pending:
        lines.append("⏳ <b>بی‌پاسخ:</b>")
        for u in pending:
            lines.append(f"• {link(u, cand.get(u))} (<code>{u}</code>)")

    while lines and lines[-1] == "":
        lines.pop()
    return "\n".join(lines)


async def _selected_live_ping(bot, sl: dict, uid: str, kind: str):
    """📣 گزارشِ لحظه‌ایِ پاسخِ هر نفر به پیویِ ادمین (مستقل از مهلتِ ۴۸ ساعته)."""
    cand = sl.get("candidates", {}) or {}
    responses = sl.get("responses", {}) or {}
    r = responses.get(uid) or {}
    nm = escape(r.get("name") or cand.get(uid) or "بازیکن", quote=False)
    who = f"<a href='tg://user?id={uid}'>{nm}</a>"

    if kind == "no":
        head = f"❌ {who} گفت <b>نمی‌آید</b>."
    elif kind == "yes":
        head = f"✅ {who} گفت <b>می‌آید</b> — منتظرِ انتخابِ روزهاست."
    else:  # submit
        head = f"📝 {who} روزهایش را ثبت کرد: <b>{escape('، '.join(r.get('days', [])), quote=False)}</b>"

    def _final(u):
        x = responses.get(u)
        return bool(x and (not x.get("participate") or x.get("submitted")))

    done = [u for u in cand if _final(u)]
    yes = [u for u in done if (responses.get(u) or {}).get("participate")]
    waiting = [u for u in cand if u not in done]
    lines = [head, f"📊 تعیین‌تکلیف‌شده: <b>{len(done)}/{len(cand)}</b> | مایل: <b>{len(yes)}</b>"]
    if waiting:
        names = "، ".join(escape((responses.get(u) or {}).get("name")
                                 or cand.get(u) or str(u), quote=False) for u in waiting)
        lines.append(f"⏳ هنوز پاسخ نداده‌اند ({len(waiting)}): {names}")
    try:
        await bot.send_message(ADMIN_ID, "\n".join(lines), parse_mode="HTML")
    except Exception as e:
        print("⚠️ selected live ping:", e)


async def _maybe_send_full_report(bot, sl: dict):
    """وقتی همهٔ کاندیداها پاسخ نهایی دادند، یک گزارش کامل به ادمین می‌فرستد."""
    cand = sl.get("candidates", {})
    responses = sl.get("responses", {})

    def finalized(uid):
        r = responses.get(uid)
        return bool(r and (not r.get("participate") or r.get("submitted")))

    if not cand or not all(finalized(u) for u in cand):
        return
    if sl.get("report_sent"):
        return

    sl["report_sent"] = True
    save_selected_list(sl)
    try:
        await bot.send_message(
            ADMIN_ID,
            "🎉 همهٔ ۱۰ نفر پاسخ دادند!\n\n" + build_selected_report(sl),
            parse_mode="HTML",
        )
    except Exception:
        pass


SELECTED_DEADLINE_SEC = 48 * 3600  # مهلت ۴۸ ساعته برای پاسخ

async def check_selected_deadline(bot):
    """اگر بعد از ۴۸ ساعت همه پاسخ نداده باشند، گزارش ناقص را به ادمین می‌فرستد."""
    sl = load_selected_list()
    if not sl.get("candidates") or sl.get("report_sent"):
        return
    started = sl.get("started_at", 0)
    if not started or (datetime.now().timestamp() - started) < SELECTED_DEADLINE_SEC:
        return

    sl["report_sent"] = True
    save_selected_list(sl)
    try:
        await bot.send_message(
            ADMIN_ID,
            "⏰ مهلت ۴۸ ساعتهٔ لیست منتخب تمام شد.\n\n" + build_selected_report(sl),
            parse_mode="HTML",
        )
    except Exception:
        pass


async def handle_selected_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    data = q.data
    uid = str(q.from_user.id)
    await safe_q_answer(q)

    sl = load_selected_list()
    cand = sl.get("candidates", {})
    responses = sl.setdefault("responses", {})

    if uid not in cand:
        try:
            await ctx.bot.send_message(int(uid), "⛔ شما در لیست برترین‌های این هفته نیستید.")
        except Exception:
            pass
        return

    name = cand.get(uid, q.from_user.full_name)

    if data == "sel_no":
        responses[uid] = {"name": name, "participate": False, "days": [], "submitted": True}
        save_selected_list(sl)
        try:
            await ctx.bot.edit_message_reply_markup(
                chat_id=int(uid), message_id=q.message.message_id, reply_markup=None
            )
        except Exception:
            pass
        await ctx.bot.send_message(int(uid), "باشه، ممنون! 🙏")
        await _selected_live_ping(ctx.bot, sl, uid, "no")
        await _maybe_send_full_report(ctx.bot, sl)
        return

    if data == "sel_yes":
        responses[uid] = {"name": name, "participate": True, "days": [], "submitted": False}
        save_selected_list(sl)
        await ctx.bot.send_message(
            int(uid),
            "📅 کدام روزها می‌توانید بازی کنید؟ (می‌توانید چند روز انتخاب کنید)\n"
            "در پایان «📝 ثبت» را بزنید:",
            reply_markup=kb_selected_days(set()),
        )
        await _selected_live_ping(ctx.bot, sl, uid, "yes")
        return

    if data.startswith("selday_"):
        r = responses.get(uid)
        if not r or not r.get("participate"):
            return
        try:
            idx = int(data.split("_")[1])
        except Exception:
            return
        day = SELECTED_DAYS[idx]
        days = set(r.get("days", []))
        if day in days:
            days.remove(day)
        else:
            days.add(day)
        r["days"] = [d for d in SELECTED_DAYS if d in days]  # حفظ ترتیب
        save_selected_list(sl)
        try:
            await ctx.bot.edit_message_reply_markup(
                chat_id=int(uid),
                message_id=q.message.message_id,
                reply_markup=kb_selected_days(r["days"]),
            )
        except Exception:
            pass
        return

    if data == "sel_submit":
        r = responses.get(uid)
        if not r or not r.get("participate"):
            return
        if not r.get("days"):
            await safe_q_answer(q, "حداقل یک روز انتخاب کن.", show_alert=True)
            return
        r["submitted"] = True
        save_selected_list(sl)
        try:
            await ctx.bot.edit_message_reply_markup(
                chat_id=int(uid), message_id=q.message.message_id, reply_markup=None
            )
        except Exception:
            pass
        await ctx.bot.send_message(
            int(uid), f"✅ ثبت شد! روزهای انتخابی شما: {'، '.join(r['days'])}"
        )
        await _selected_live_ping(ctx.bot, sl, uid, "submit")
        await _maybe_send_full_report(ctx.bot, sl)
        return


async def broadcast_weekly_stats(bot, force: bool = False):
    """در صورت رسیدن موعد هفتگی، لیدربرد را به همهٔ گروه‌های فعال می‌فرستد."""
    meta = load_weekly_meta()
    if meta is None:
        # ⚠️ خواندنِ متا خطا داد → این دور را رد کن؛ ساعتِ هفتگی دست نمی‌خورد
        return {"sent": 0, "reason": "meta_load_failed"}
    now = datetime.now().timestamp()
    last_sent = meta.get("last_sent", 0)
    snapshot = meta.get("snapshot", {})

    current = load_player_stats()

    # اولین اجرا (فایل واقعاً خالی): فقط خط مبنا را ثبت کن و صبر کن تا هفتهٔ بعد
    if not last_sent and not force:
        print("📊 weekly baseline set (first run)")
        save_weekly_meta({"last_sent": now, "snapshot": current})
        return

    if not force and (now - last_sent) < WEEKLY_PERIOD_SEC:
        return {"sent": 0, "reason": "not_due"}

    text = build_weekly_leaderboard_text(current, snapshot, require_weekly=not force)

    sent = 0
    if text:
        for chat_id in list(store.active_groups):
            try:
                msg = await bot.send_message(chat_id, text, parse_mode="HTML")
                try:
                    await bot.pin_chat_message(
                        chat_id, msg.message_id, disable_notification=True
                    )
                except Exception as e:
                    print(f"⚠️ weekly pin failed for {chat_id}:", e)
                sent += 1
            except Exception as e:
                print(f"⚠️ weekly send failed for {chat_id}:", e)

    # 🚫 محرومیتِ گادها برای هفتهٔ پیشِ‌رو (ترکِ بازی یا امتیازِ پایین)
    try:
        _delta_all = _weekly_delta(current, snapshot)
        _banned = compute_god_bans(_delta_all)
        save_god_bans({"set_at": now, "banned": _banned})
        if _banned:
            _bl = ["🚫 <b>محرومانِ گادی برای این هفته</b>", ""]
            for _u, _b in _banned.items():
                _nm = escape(_b.get("name", "بازیکن"), quote=False)
                _why = (f"{_b.get('abandons')} بار ترکِ بازی"
                        if _b.get("reason") == "abandon"
                        else f"میانگینِ {_b.get('avg')} از ۵ ({_b.get('votes')} رأی)")
                _bl.append(f"• <a href='tg://user?id={_u}'>{_nm}</a> — {_why}")
            _bl.append("")
            _bl.append("<i>تا آمارِ هفتگیِ بعد نمی‌توانند گاد شوند.</i>")
            _btxt = "\n".join(_bl)
            for _cid in list(store.active_groups):
                try:
                    await bot.send_message(_cid, _btxt, parse_mode="HTML")
                except Exception:
                    pass
            try:
                await bot.send_message(ADMIN_ID, _btxt, parse_mode="HTML")
            except Exception:
                pass
    except Exception as e:
        print("⚠️ god bans compute error:", e)

    # 📋 دعوت ۱۰ نفر برتر هفته به لیست منتخب (دستی و خودکار — هر دو)
    if text:
        try:
            delta = _weekly_delta(current, snapshot)
            # 🔗 دقیقاً همان ۱۰ نفری که در آمار هفتگی نمایش داده شدند
            cands = weekly_top_candidates(delta, 10)
            if cands:
                await launch_selected_round(bot, cands)
        except Exception as e:
            print("⚠️ launch_selected_round error:", e)

    # ⏱ /weekly دستی هم مثل خودکار: ساعتِ هفته از همین لحظه ریست + اسنپ‌شاتِ تازه
    save_weekly_meta({"last_sent": now, "snapshot": current})

    if not text:
        reason = "no_data" if not current else "no_activity"
        return {"sent": 0, "reason": reason}
    return {"sent": sent, "reason": "ok", "groups": len(store.active_groups)}


async def weekly_scheduler(app):
    """هر ساعت بررسی می‌کند که آیا موعد ارسال آمار هفتگی رسیده یا نه."""
    while True:
        try:
            await broadcast_weekly_stats(app.bot)
        except Exception as e:
            print("⚠️ weekly_scheduler error:", e)
        try:
            await check_selected_deadline(app.bot)
        except Exception as e:
            print("⚠️ check_selected_deadline error:", e)
        await asyncio.sleep(3600)


