async def _is_god_or_admin(ctx, chat_id: int, uid: int, g: GameState) -> bool:
    if uid == g.god_id:
        return True
    try:
        admins = await ctx.bot.get_chat_administrators(chat_id)
        return uid in {a.user.id for a in admins}
    except Exception:
        return False


CARDS_FILENAME = "cards.json"

def load_cards() -> dict[str, list[str]]:
    try:
        if not GH_TOKEN or not GIST_ID:
            print("⚠️ GH_TOKEN/GIST_ID not set; load_cards -> empty dict")
            return {}
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        r = requests.get(url, headers=headers, timeout=10)
        if r.status_code != 200:
            print("❌ load_cards failed:", r.status_code, r.text)
            return {}
        data = r.json()
        content = data["files"].get(CARDS_FILENAME, {}).get("content", "{}")
        return json.loads(content) if content else {}
    except Exception as e:
        print("❌ load_cards error:", e)
        return {}

def save_cards(cards: dict[str, list[str]]) -> bool:
    try:
        if not GH_TOKEN or not GIST_ID:
            print("⚠️ GH_TOKEN/GIST_ID not set; save_cards skipped")
            return False
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        payload = {
            "files": {
                CARDS_FILENAME: {
                    "content": json.dumps(cards, ensure_ascii=False, indent=2)
                }
            }
        }
        r = requests.patch(url, headers=headers, json=payload, timeout=10)
        return r.status_code in (200, 201)
    except Exception as e:
        print("❌ save_cards error:", e)
        return False


# ─────────────────────────────────────────────────────────────
#  دکمه‌های کنترل راوی در حین بازی
# ─────────────────────────────────────────────────────────────
def control_keyboard(g: GameState) -> InlineKeyboardMarkup:
    rows = []

    # اگر کارت برای این سناریو وجود داشت → اول بیاد
    cards = load_cards()
    if g.scenario and g.scenario.name in cards and cards[g.scenario.name]:
        rows.append([InlineKeyboardButton("🃏 شافل کارت", callback_data="shuffle_card")])

    # بعد بقیه دکمه‌ها
    rows.append([
        InlineKeyboardButton("⚠️ اخطار", callback_data="warn_mode"),
        InlineKeyboardButton("✂️ خط‌زدن", callback_data="strike_out"),
    ])
    # 📊 میتیک و کلاسیک اصلاً استعلامِ وضعیت ندارند → دکمه‌اش نمایش داده نمی‌شود
    if not (_is_mythic_scenario(g) or _is_classic_scenario(g)):
        rows.append([InlineKeyboardButton("📊 استعلام وضعیت", callback_data="status_auto")])

    rows.extend([
        [
            InlineKeyboardButton("🗳 رأی اولیه", callback_data="init_vote"),
            InlineKeyboardButton("🗳 رأی نهایی", callback_data="final_vote"),
        ],
        [
            InlineKeyboardButton("🛒 خریداری", callback_data="purchase_menu"),
            InlineKeyboardButton("⚙️ تنظیمات", callback_data="ctl_settings"),
        ],
    ])

    # 🌙 دکمه‌های شب/روز/معارفه (به‌جای دستورهای متنی)
    # 🎭 تا معارفه انجام نشده، «شب» اصلاً نمایش داده نمی‌شود و جایش معارفه است —
    #    وگرنه گاد اشتباهی شب را می‌زند و معارفه رد می‌شود.
    night_row = []
    if not getattr(g, "maarefe_done", False):
        night_row.append(InlineKeyboardButton("🎭 معارفه", callback_data="ctl_maarefe"))
    else:
        night_row.append(InlineKeyboardButton("🌙 شب", callback_data="ctl_night"))
    night_row.append(InlineKeyboardButton("☀️ روز", callback_data="ctl_day"))
    night_row.append(InlineKeyboardButton("👢 کیک", callback_data="ctl_kick"))
    rows.append(night_row)

    # 🧑‍⚖️ دکمه‌ی یک‌بارمصرفِ بازپرسی — بعد از معارفه ظاهر و تا استفاده‌ی گاد می‌ماند
    #    (حتی اگر بازپرس مرده/بی‌اکت باشد — که از بود‌ونبودِ دکمه چیزی لو نرود)
    if (_is_baazpors_scenario(g) and getattr(g, "maarefe_done", False)
            and not getattr(g, "baz_button_used", False)):
        rows.append([InlineKeyboardButton("🧑‍⚖️ بازپرسی", callback_data="ctl_bazparsi")])

    # 🗳 دکمه‌ی یک‌بارمصرفِ دنگِ نمایندگی — نماینده، بعد از معارفه، فقط روز ۱
    if (_is_nemayande_scenario(g) and getattr(g, "maarefe_done", False)
            and getattr(g, "night_number", 0) == 0
            and not getattr(g, "nem_deng_button_used", False)):
        rows.append([InlineKeyboardButton("🗳 نماینده", callback_data="ctl_nemayande")])

    # 🤝 دکمه‌ی یک‌بارمصرفِ معتمدِ کاپو — کاپو، بعد از معارفه، فقط روز ۱
    if (_is_kapu_scenario(g) and getattr(g, "maarefe_done", False)
            and getattr(g, "night_number", 0) == 0
            and not getattr(g, "kp_trust_button_used", False)):
        rows.append([InlineKeyboardButton("🤝 کاپو", callback_data="ctl_kapu")])

    # 💣 دکمه‌ی یک‌بارمصرفِ تروریست/یاغی — گاد به‌جای «نوشتنِ کفِ گروه» این را می‌زند.
    #    ⚠️ دیدنی بودنِ دکمه به زنده‌بودنِ نقش وابسته نیست، وگرنه از بود‌ونبودش لو می‌رود.
    if (_is_mythic_scenario(g) and getattr(g, "maarefe_done", False)
            and not getattr(g, "my_terror_used", False)):
        rows.append([InlineKeyboardButton("💣 تروریست", callback_data="ctl_terror")])
    if (_is_nemayande_scenario(g) and getattr(g, "maarefe_done", False)
            and not getattr(g, "nem_yaghi_used", False)):
        rows.append([InlineKeyboardButton("💣 یاغی", callback_data="ctl_yaghi")])

    # 🏛 دکمه‌ی یک‌بارمصرفِ معمار — هانیبال، بعد از معارفه، تا برگزاریِ دوئل
    #    ⚠️ دیدنی بودنش به وجودِ کارت وابسته نیست تا چیزی لو نرود
    if (_is_hanibal_scenario(g) and getattr(g, "maarefe_done", False)
            and not getattr(g, "hb_duel_used", False)):
        rows.append([InlineKeyboardButton("🏛 معمار", callback_data="ctl_memar")])

    # 💣 دکمه‌ی الیوت (گیمر) — همیشه هست، چون تووفیس شب‌های فرد بمبِ تازه می‌گذارد.
    #    ⚠️ دیدنی بودنش به وجودِ بمب وابسته نیست، وگرنه از بود‌ونبودش لو می‌رفت.
    if _is_gamer_scenario(g) and getattr(g, "maarefe_done", False):
        rows.append([InlineKeyboardButton("💣 الیوت", callback_data="ctl_eliot")])

    # ⚔️ دکمه‌ی یک‌بارمصرفِ شاهنامه — بعد از معارفه، فقط روز ۱
    if (_is_shahname_scenario(g) and getattr(g, "maarefe_done", False)
            and getattr(g, "night_number", 0) == 0
            and not getattr(g, "sh_button_used", False)):
        rows.append([InlineKeyboardButton("⚔️ شاهنامه", callback_data="ctl_shahname")])

    # 🔒/🔓 یک دکمه‌ی toggle برای چت اتاق مافیا (فقط وقتی اتاق فعال است)
    if getattr(g, "mafia_room_id", None):
        lbl = ("🔓 باز کردن چت مافیا" if getattr(g, "mafia_room_locked", False)
               else "🔒 بستن چت مافیا")
        rows.append([InlineKeyboardButton(lbl, callback_data="ctl_roomlock")])

    # Keep "end game" alone (safer)
    rows.append([InlineKeyboardButton("🏁 اتمام بازی", callback_data="end_game")])

    return InlineKeyboardMarkup(rows)

async def _delete_rerandom_prompt_after(ctx, chat_id: int, g: GameState, msg_id: int, seconds: int = 30):
    await asyncio.sleep(seconds)
    if getattr(g, "awaiting_rerandom_decision", False) and getattr(g, "rerandom_prompt_msg_id", None) == msg_id:
        try:
            await ctx.bot.delete_message(chat_id=chat_id, message_id=msg_id)
        except Exception:
            pass
        g.awaiting_rerandom_decision = False
        g.rerandom_prompt_msg_id = None
        store.save()

def warn_button_markup_plusminus(g: GameState) -> InlineKeyboardMarkup:
    # از dict بودن مطمئن شو
    pw = g.pending_warnings if isinstance(g.pending_warnings, dict) else {}
    w  = g.warnings          if isinstance(g.warnings, dict)          else {}

    rows = []
    # فقط زنده‌ها
    alive = [s for s in sorted(g.seats) if s not in g.striked]
    for s in alive:
        base = pw.get(s, w.get(s, 0))
        try:
            n = int(base)
        except Exception:
            n = 0
       
        n = max(0, n)
        icons = "❗️" * n if n > 0 else "(0)"
        label = f"{s} {icons}"

        rows.append([
            InlineKeyboardButton("➖", callback_data=f"warn_dec_{s}"),
            InlineKeyboardButton(label, callback_data="noop"),
            InlineKeyboardButton("➕", callback_data=f"warn_inc_{s}"),
        ])

    rows.append([InlineKeyboardButton("✅ تأیید", callback_data="warn_confirm")])
    rows.append([InlineKeyboardButton("↩️ بازگشت", callback_data="warn_back")])
    return InlineKeyboardMarkup(rows)




def _clean_sheet_possible(g):
    """🧼 (کلین‌شیتِ شهر ممکن؟، کلین‌شیتِ مافیا ممکن؟) — دقیقاً همان قاعدهٔ _win_condition:
    کلین‌شیتِ مافیا یعنی هیچ مافیایی کشته نشده؛ کلین‌شیتِ شهر یعنی هیچ شهروندی خارج نشده.
    (پس مثلاً با ۳ نفرِ باقی‌مانده، هیچ‌کدام دیگر ممکن نیست.)"""
    try:
        if not getattr(g, "assigned_roles", None):
            return True, True      # هنوز نقشی پخش نشده — چیزی را محدود نکن
        struck = {s for s in (getattr(g, "striked", None) or set()) if s in (g.seats or {})}
        city_clean = not any(_sc_side(g, s) != "مافیا" for s in struck)
        mafia_clean = not any(_sc_side(g, s) == "مافیا" for s in struck)
        return city_clean, mafia_clean
    except Exception:
        return True, True


def kb_endgame_root(g: GameState) -> InlineKeyboardMarkup:
    # 🌀 کی‌آسِ خودکار: فقط دو گزینه — بات خودش می‌داند چه کسانی کی‌آس‌اند (زنده‌ها)
    if getattr(g, "chaos_auto", False):
        return InlineKeyboardMarkup([
            [InlineKeyboardButton("😈 برد مافیا (کی‌آس)", callback_data="winner_mafia_chaos")],
            [InlineKeyboardButton("🏙 برد شهر (کی‌آس)", callback_data="winner_city_chaos")],
            [InlineKeyboardButton("⬅️ بازگشت", callback_data="back_endgame")],
        ])
    rows = [
        [InlineKeyboardButton("🏙 شهر", callback_data="winner_city")],
        [InlineKeyboardButton("😈 مافیا", callback_data="winner_mafia")],
    ]
    # 🧼 کلین‌شیت فقط وقتی «واقعاً ممکن» است دکمه دارد:
    #    شهر → هیچ شهروندی خارج نشده | مافیا → هیچ مافیایی کشته نشده
    _cc, _mc = _clean_sheet_possible(g)
    if _cc:
        rows.append([InlineKeyboardButton("🏙 کلین‌شیت شهر", callback_data="clean_city")])
    if _mc:
        rows.append([InlineKeyboardButton("😈 کلین‌شیت مافیا", callback_data="clean_mafia")])
    # ⚔️ میتیک کی‌آس ندارد → گزینه‌هایش هم نمی‌آید
    if not _is_mythic_scenario(g):
        rows += [
            [InlineKeyboardButton("🏙 شهر (کی‌آس)", callback_data="winner_city_chaos")],
            [InlineKeyboardButton("😈 مافیا (کی‌آس)", callback_data="winner_mafia_chaos")],
        ]

    indep_roles = load_indep_roles()
    if g.scenario and g.scenario.name in indep_roles and indep_roles[g.scenario.name]:
        rows.append([InlineKeyboardButton("♦️ مستقل", callback_data="winner_indep")])

    rows.append([InlineKeyboardButton("⬅️ بازگشت", callback_data="back_endgame")])
    return InlineKeyboardMarkup(rows)



def kb_pick_defense(g: GameState) -> InlineKeyboardMarkup:
    rows = []

    # فقط بازیکنان زنده (یعنی کسانی که در g.striked نیستن)
    alive_seats = [s for s in sorted(g.seats.keys()) if s not in g.striked]

    for s in alive_seats:
        uid, name = g.seats[s]
        label = f"{s}. {name}"  # شماره + نام بازیکن

        # اگر بازیکن انتخاب شده، ترتیب انتخاب را هم نشان بده
        if s in g.defense_selection:
            order = g.defense_selection.index(s) + 1
            label = f"{s}. {name} ({order}) ✅"

        rows.append([InlineKeyboardButton(label, callback_data=f"def_pick_{s}")])

    # دکمه‌های پایانی
    rows.append([InlineKeyboardButton("✅ تأیید", callback_data="def_confirm")])
    rows.append([InlineKeyboardButton("↩️ بازگشت", callback_data="def_back")])

    return InlineKeyboardMarkup(rows)

