def delete_button_markup(g: GameState) -> InlineKeyboardMarkup:
    rows = []
    # فقط صندلی‌هایی که بازیکن دارند
    for seat in sorted(g.seats.keys()):
        label = f"{seat} ✅" if seat in g.pending_delete else f"{seat}"
        rows.append([InlineKeyboardButton(label, callback_data=f"delete_toggle_{seat}")])
    # کنترل‌ها
    rows.append([InlineKeyboardButton("✅ تأیید حذف", callback_data="delete_confirm")])
    rows.append([InlineKeyboardButton("↩️ بازگشت", callback_data="delete_cancel")])
    return InlineKeyboardMarkup(rows)


# ─────── بالای فایل (یا کنار بقیهٔ ثوابت) ──────────────────
REG   = "register"   # نمایش دکمه‌های ثبت‌نامی
CTRL  = "controls"   # فقط دکمه‌های کنترلی

async def safe_q_answer(q, text=None, show_alert=False):
    try:
        await q.answer(text, show_alert=show_alert)
    except telegram.error.BadRequest:
        pass
    except Exception:
        pass
async def set_hint_and_kb(ctx, chat_id: int, g: GameState, hint: str | None, kb: InlineKeyboardMarkup, mode: str = CTRL):
    g.ui_hint = hint
    store.save()
    await publish_seating(ctx, chat_id, g, mode=mode, custom_kb=kb)


def _ui_mode(g) -> str:
    """🎛 کیبوردِ درست برای فازِ فعلی — قبل از بازی ثبت‌نامی، بعدش کنترلی.
    ⚠️ هرگز publish_seating را بدونِ mode صدا نزن: پیش‌فرضش REG است و وسطِ
    بازی، لیست را به حالتِ «قبل از شروع» برمی‌گرداند."""
    return REG if getattr(g, "phase", "idle") == "idle" else CTRL


# ⏳ دکمه‌هایی که منتظرِ «نوشتنِ متن» می‌مانند (ساعت/موضوعِ رویداد) بیش از این
#    نمی‌مانند — وگرنه گاد یادش می‌رود و بعداً اولین پیامش وسطِ بازی بلعیده می‌شود.
AWAIT_INPUT_TIMEOUT = 60


def _await_input_start(g):
    g.await_input_ts = datetime.now(timezone.utc).timestamp()


def _await_input_alive(g) -> bool:
    """آیا پنجرهٔ ۶۰ ثانیه‌ایِ ورودی هنوز باز است؟ (منقضی → بسته می‌شود)"""
    ts = getattr(g, "await_input_ts", None)
    if ts is None:
        return False
    if datetime.now(timezone.utc).timestamp() - float(ts) <= AWAIT_INPUT_TIMEOUT:
        return True
    g.await_input_ts = None
    g.awaiting_event_title = False
    if getattr(g, "vote_type", None) == "awaiting_time":
        g.vote_type = None
    store.save()
    return False

EVENT_NUMBERS_CACHE = None

def get_event_numbers():
    global EVENT_NUMBERS_CACHE
    if EVENT_NUMBERS_CACHE is None:
        EVENT_NUMBERS_CACHE = load_event_numbers() or {}
    return EVENT_NUMBERS_CACHE


# ---- Concurrency / Debounce / Retry helpers ----
DEBOUNCE_EDIT_SEC = 0.15
SAVE_DEBOUNCE_SEC = 0.30

CHAT_LOCKS: dict[int, asyncio.Lock] = {}
def get_chat_lock(chat_id: int) -> asyncio.Lock:
    lock = CHAT_LOCKS.get(chat_id)
    if lock is None:
        lock = asyncio.Lock()
        CHAT_LOCKS[chat_id] = lock
    return lock


_SAVE_TASK: asyncio.Task | None = None
def save_debounced():
    global _SAVE_TASK
    if _SAVE_TASK and not _SAVE_TASK.done():
        return
    async def _do():
        await asyncio.sleep(SAVE_DEBOUNCE_SEC)
        try:
            store.save()
        except Exception as e:
            print("save_debounced error:", e)
    _SAVE_TASK = asyncio.create_task(_do())

# Retry wrapper for Telegram rate limits
async def _retry(coro):
    try:
        return await coro
    except RetryAfter as e:
        await asyncio.sleep(float(getattr(e, "retry_after", 1.0)) + 0.1)
        return await coro


def scenario_roles_text(g) -> str | None:
    """📜 متنِ «لیست نقش‌های سناریو» — مشترکِ لیستِ خودکار و /list.
    None اگر سناریویی انتخاب نشده باشد."""
    if not getattr(g, "scenario", None):
        return None
    mafia_roles = {_nz(x) for x in load_mafia_roles()}
    indep_for_this = {_nz(x) for x in (load_indep_roles() or {}).get(g.scenario.name, [])}
    mafia_lines = ["<b>نقش‌های مافیا:</b>"]
    citizen_lines = ["<b>نقش‌های شهروند:</b>"]
    indep_lines = ["<b>نقش‌های مستقل:</b>"]

    for role, count in g.scenario.roles.items():
        for _ in range(count):
            if _nz(role) in mafia_roles:
                mafia_lines.append(f"♠️ {role}")
            elif _nz(role) in indep_for_this:
                indep_lines.append(f"♦️ {role}")
            else:
                citizen_lines.append(f"♥️ {role}")

    lines = ["📜 <b>لیست نقش‌های سناریو:</b>\n"]
    lines.extend(mafia_lines)
    lines.append("")
    lines.extend(citizen_lines)
    if len(indep_lines) > 1:      # یعنی حداقل یک نقش مستقل هست
        lines.append("")
        lines.extend(indep_lines)
    return "\n".join(lines)


# ─────── تابع اصلاح‌ شده ───────────────────────────────────
async def publish_seating(
    ctx,
    chat_id: int,
    g: GameState,
    mode: str = REG,
    custom_kb: InlineKeyboardMarkup | None = None,
):
    lock = get_chat_lock(chat_id)
    async with lock:
        await asyncio.sleep(DEBOUNCE_EDIT_SEC)

        if not g.max_seats or g.max_seats <= 0:
            await _retry(ctx.bot.send_message(chat_id, "برای شروع، ادمین باید /newgame <seats> بزند."))
            return

        # 🎖 کشِ مدال‌ها (حداکثر هر نیم ساعت یک‌بار از گیست خوانده می‌شود — در ترد جدا)
        try:
            await asyncio.to_thread(ensure_medal_cache)
        except Exception:
            pass

        today = jdatetime.date.today().strftime("%Y/%m/%d")
        emoji_numbers = [
            "⓿", "➊", "➋", "➌", "➍", "➎", "➏", "➐", "➑", "➒",
            "➓", "⓫", "⓬", "⓭", "⓮", "⓯", "⓰", "⓱", "⓲", "⓳", "⓴"
        ]

        # آیدی/لینک گروه
        if not hasattr(g, "_chat_cache"):
            g._chat_cache = {}
        group_id_or_link = f"🆔 {chat_id}"
        if ctx.bot.username and chat_id < 0:
            try:
                if "username" in g._chat_cache and "title" in g._chat_cache:
                    username = g._chat_cache["username"]
                    title = g._chat_cache["title"]
                else:
                    chat_obj = await _retry(ctx.bot.get_chat(chat_id))
                    username = getattr(chat_obj, "username", None)
                    title = getattr(chat_obj, "title", None)
                    g._chat_cache["username"] = username
                    g._chat_cache["title"] = title

                if username:
                    group_id_or_link = f"🔗 <a href='https://t.me/{username}'>{title}</a>"
                elif title:
                    group_id_or_link = f"🔒 {title}"
            except Exception:
                pass

        # متن اصلی
        # تاج ♚ فقط قبل از شروع بازی (مرحلهٔ ثبت‌نام) نمایش داده می‌شود
        game_started = g.phase != "idle"
        cr = "" if game_started else "♚"
        event_num = int(get_event_numbers().get(str(chat_id), 1))

        lines = [
            f"{group_id_or_link}",
            f"{cr}🎯 <b>شماره رویداد:</b> {event_num}",
            f"{cr}🎭 <b>{escape(g.event_title, quote=False) if g.event_title else 'رویداد مافیا'}</b>",
            f"{cr}📆 <b>تاریخ:</b> {today}",
            f"{cr}🕰 <b>زمان:</b> {g.event_time or '---'}",
            f"{cr}🎩 <b>راوی:</b> <a href='tg://user?id={g.god_id}'>{g.god_name or '❓'}</a>"
            f"{medal_tag(g.god_id)}",
        ]

        if g.scenario:
            lines.append(f"{cr}📜 <b>سناریو:</b> {g.scenario.name} | 👥 {sum(g.scenario.roles.values())} نفر")

        lines.append(f"\n\n{cr}📂 <b>بازیکنان:</b>\n")

        # لیست صندلی‌ها
        for i in range(1, g.max_seats + 1):
            emoji_num = emoji_numbers[i] if i < len(emoji_numbers) else str(i)
            if i in g.seats:
                uid, name = g.seats[i]
                safe_name = escape(name, quote=False)
                # 🎖 نشانِ مدال (اگر دارد) بلافاصله بعد از اسم
                name_link = (f"<a href='tg://user?id={uid}'>{safe_name}</a>"
                             f"{medal_tag(uid)}")

                wn = 0
                if isinstance(getattr(g, "warnings", None), dict):
                    wn = g.warnings.get(i, 0)
                try:
                    wn = int(wn)
                except Exception:
                    wn = 0
                wn = max(0, wn)
                warn_suffix = (" " + ("❗️" * wn)) if wn > 0 else ""

                if not game_started:
                    # قبل از بازی: حالت اصلی با تاج
                    line = f"♚{i}  {name_link}{warn_suffix}"
                elif i in g.striked:
                    # مرده: دایرهٔ قرمز، خط روی شماره و اسم، فونت عادی (+ نشانِ کیک)
                    _kick_mark = " ✖️کیک" if i in (getattr(g, "score_kicked", set()) or set()) else ""
                    line = f"🔴<s>{i}  {name_link}</s>{_kick_mark}{warn_suffix}"
                else:
                    # زنده: دایرهٔ سبز، فونت بولد
                    line = f"🟢<b>{i}  {name_link}</b>{warn_suffix}"
            else:
                # صندلی خالی
                line = f"⬜{i} /{i}" if game_started else f"♚{i} ⬜ /{i}"
            lines.append(line)

        # استعلام وضعیت
        if g.status_counts.get("citizen", 0) > 0 or g.status_counts.get("mafia", 0) > 0:
            c = g.status_counts.get("citizen", 0)
            m = g.status_counts.get("mafia", 0)
            lines.append(f"\n🧾 <i>استعلام وضعیت: {c} شهروند و {m} مافیا</i>")

        if getattr(g, "ui_hint", None):
            lines.append("")
            lines.append(f"ℹ️ <i>{g.ui_hint}</i>")

        text = "\n".join(lines)

        # انتخاب کیبورد
        if custom_kb is not None:
            kb = custom_kb
        elif getattr(g, "awaiting_scenario_change", False):
            # 🪄 وسطِ انتخابِ ظرفیت/سناریو، ثبت‌نامِ بقیه نباید کیبوردِ گاد را بپراند
            _psz = getattr(g, "pending_size", None)
            kb = kb_choose_scenarios_for(_psz) if _psz else kb_choose_sizes()
        else:
            if mode == REG:
                kb = text_seating_keyboard(g)
            elif mode == "strike":
                kb = strike_button_markup(g)
            elif mode == "kick":
                kb = kick_button_markup(g)
            elif mode == "status":
                kb = status_button_markup(g)
            elif mode == "delete":
                kb = delete_button_markup(g)
            elif mode == "warn":
                kb = warn_button_markup_plusminus(g)
            else:
                kb = control_keyboard(g)

        # --- ذخیره اسنپ‌شات آخرین لیست برای بازیابی با /lists ---
        try:
            g.last_snapshot = {
                "text": text,
                "kb": kb.to_dict(),  # کیبورد رو به dict ذخیره می‌کنیم
            }
            store.save()
        except Exception as e:
            print("⚠️ snapshot save error:", e)
        # پیام لیست
        try:
            if g.last_seating_msg_id:
                try:
                    await _retry(ctx.bot.edit_message_text(
                        chat_id=chat_id,
                        message_id=g.last_seating_msg_id,
                        text=text,
                        parse_mode="HTML",
                        reply_markup=kb,
                    ))
                except BadRequest as e:
                    s = str(e)
                    if "message is not modified" in s:
                        try:
                            await _retry(ctx.bot.edit_message_reply_markup(
                                chat_id=chat_id,
                                message_id=g.last_seating_msg_id,
                                reply_markup=kb
                            ))
                        except BadRequest as e2:
                            if "message is not modified" in str(e2):
                                pass
                            else:
                                raise
                    else:
                        raise
            else:
                msg = await _retry(ctx.bot.send_message(
                    chat_id,
                    text,
                    parse_mode="HTML",
                    reply_markup=kb
                ))
                g.last_seating_msg_id = msg.message_id
                if chat_id < 0:
                    try:
                        await _retry(ctx.bot.pin_chat_message(
                            chat_id,
                            msg.message_id,
                            disable_notification=True
                        ))
                    except Exception:
                        pass
        except (TimedOut, RetryAfter):
            pass  # خطای گذرا – پیام جدید نفرست
        except telegram.error.BadRequest as e:
            if "not modified" in str(e).lower():
                pass  # محتوا تغییری نکرده (مثلاً شبِ بدون کشته) – پیام جدید نفرست
            else:
                old_msg_id = g.last_seating_msg_id
                msg = await _retry(ctx.bot.send_message(
                    chat_id,
                    text,
                    parse_mode="HTML",
                    reply_markup=kb
                ))
                g.last_seating_msg_id = msg.message_id
                if chat_id < 0:
                    try:
                        await _retry(ctx.bot.pin_chat_message(
                            chat_id, msg.message_id, disable_notification=True))
                    except Exception:
                        pass
                if old_msg_id:
                    try:
                        await ctx.bot.delete_message(chat_id, old_msg_id)
                    except Exception:
                        pass
        except Exception:
            old_msg_id = g.last_seating_msg_id
            msg = await _retry(ctx.bot.send_message(
                chat_id,
                text,
                parse_mode="HTML",
                reply_markup=kb
            ))
            g.last_seating_msg_id = msg.message_id

            if chat_id < 0:
                try:
                    await _retry(ctx.bot.pin_chat_message(
                        chat_id,
                        msg.message_id,
                        disable_notification=True
                    ))
                except Exception:
                    pass

            if old_msg_id:
                try:
                    await ctx.bot.delete_message(chat_id, old_msg_id)
                except Exception:
                    pass

  
        # لیست نقش‌ها
        if g.scenario and mode == REG:
            if getattr(g, "last_roles_scenario_name", None) != g.scenario.name:
                role_text = scenario_roles_text(g)

                try:
                    if getattr(g, "last_roles_msg_id", None):
                        try:
                            await _retry(ctx.bot.edit_message_text(
                                chat_id=chat_id,
                                message_id=g.last_roles_msg_id,
                                text=role_text,
                                parse_mode="HTML",
                            ))
                        except BadRequest as e:
                            if "message is not modified" in str(e):
                                pass
                            else:
                                raise
                    else:
                        role_msg = await _retry(
                            ctx.bot.send_message(chat_id, role_text, parse_mode="HTML")
                        )
                        g.last_roles_msg_id = role_msg.message_id
                except Exception:
                    role_msg = await _retry(
                        ctx.bot.send_message(chat_id, role_text, parse_mode="HTML")
                    )
                    g.last_roles_msg_id = role_msg.message_id

                g.last_roles_scenario_name = g.scenario.name


        save_debounced()


# ─────────────────────────────────────────────────────────────
#  رأی‌گیری (همان نسخهٔ قبلی؛ فقط دست نزدیم)
# ─────────────────────────────────────────────────────────────
def _is_valid_vote_text(text: str) -> bool:
    """رأی معتبر: فقط «دولایک با هر رنگ پوست» یا «دو نقطه ..»"""
    t = (text or "").strip()
    if t == "..":
        return True
    # حذف رنگ پوست، کاراکترهای نامرئی ایموجی و فاصله‌ها
    _strip = {"︎", "️", "‍", " ", "‌"}    # variation selectors + ZWJ + فاصله + نیم‌فاصله
    cleaned = "".join(
        ch for ch in t
        if not ("\U0001F3FB" <= ch <= "\U0001F3FF")           # skin tone modifiers
        and ch not in _strip
    )
    return cleaned == "\U0001F44D\U0001F44D"                  # 👍👍


def _try_capture_vote(g, msg, uid, text) -> bool:
    """اگر پیام یک رأی معتبر داخل پنجرهٔ رأی‌گیری (جاری یا قبلی) باشد، ثبتش می‌کند.
    ملاک زمان = ساعتِ ارسال تلگرام (msg.date)، نه زمان پردازش.
    پنجره‌ی قبلی برای رأی‌هایی است که به‌موقع فرستاده شده ولی دیر به بات رسیده‌اند."""
    if not _is_valid_vote_text(text):
        return False
    try:
        msg_ts = msg.date.timestamp()
    except Exception:
        msg_ts = datetime.now().timestamp()

    candidates = []
    cur = getattr(g, "vote_window", None)
    target_now = getattr(g, "current_vote_target", None)
    if cur and target_now and cur[2] == target_now:
        candidates.append((cur, getattr(g, "vote_bounds", None)))
    prev = getattr(g, "vote_prev_window", None)
    if prev:
        candidates.append((prev, getattr(g, "vote_prev_bounds", None)))

    for (start, end, win_target), bounds in candidates:
        if not (start <= msg_ts <= end):   # بدون تلورانس — ساعتِ بعد از «تمام» رد می‌شود
            continue
        # 🔒 فیلترِ دوم (ترتیبِ چت): رأیی که پایینِ «تمام» نشسته، حتی هم‌ثانیه، رد می‌شود
        if bounds:
            b_start, b_end = bounds
            if b_start and msg.message_id <= b_start:
                continue
            if b_end and msg.message_id >= b_end:
                continue
        voter_seat = next((s for s, (u, _) in g.seats.items() if u == uid), None)
        if not voter_seat or voter_seat in (g.striked or set()):
            return False
        # 🎃 سمِ مترسک: رأیِ نهاییِ امروزِ این نفر خوانده می‌شود ولی شمرده نمی‌شود
        #    (بی‌سروصدا — نه در گروه چیزی گفته می‌شود نه به خودش)
        if (getattr(g, "vote_stage", None) == "final"
                and getattr(g, "gm_poisoned", None) == voter_seat):
            return True
        # 🗳 میتیک: رأی به خود مجاز است و شمرده می‌شود؛ بقیهٔ سناریوها نه
        if voter_seat == win_target and not _is_mythic_scenario(g):
            return False
        # ⚔️ اگر دقیقاً دو نفر در رأی‌گیریِ نهایی باشند، آن دو به هم رأی نمی‌دهند
        #    و رأیشان اصلاً خوانده نمی‌شود — در همهٔ سناریوها به‌جز میتیک.
        if not _is_mythic_scenario(g) and _sh_duel_locked(g, voter_seat, win_target):
            return False
        g.votes_cast.setdefault(win_target, set())
        if uid not in g.votes_cast[win_target]:  # هر نفر برای «هر هدف» فقط یک رأی
            g.votes_cast[win_target].add(uid)
            if not hasattr(g, "vote_logs"):
                g.vote_logs = {}
            g.vote_logs.setdefault(win_target, [])
            g.vote_logs[win_target].append((uid, msg_ts - start))
            store.save()
        if not hasattr(g, "vote_cleanup_ids"):
            g.vote_cleanup_ids = []
        g.vote_cleanup_ids.append(msg.message_id)
        return True
    return False


def _final_vote_threshold(alive_count: int, g=None) -> int:
    """حدنصابِ ورود به دفاعیه بر اساس تعداد زنده‌ها:
    ۴-۵ نفر → ۲ | ۶-۷ نفر → ۳ | ۸-۱۰ نفر → ۴ | ۱۱-۱۲ نفر → ۵ |
    بیشتر → ثلثِ زنده‌ها +۱
    ⚔️ میتیک قانونِ خودش را دارد: نصفِ زنده‌ها، و اگر فرد بود نصف+۱ (۹ → ۵، ۱۰ → ۵)."""
    if g is not None and _is_mythic_scenario(g):
        return (alive_count + 1) // 2
    if alive_count <= 5:
        return 2
    if alive_count <= 7:
        return 3
    if alive_count <= 10:
        return 4
    if alive_count <= 12:
        return 5          # ۱۱ و ۱۲ نفرِ زنده → ۵ رأی
    return alive_count // 3 + 1


def _bump_defense_history(g, seats):
    """📜 ثبتِ «سابقهٔ دفاع» — فقط رأی‌گیریِ نهایی و جفتِ دفاعِ کاپویی.
    ⚠️ بازپرسی سابقه حساب نمی‌شود. (این سابقه ملاکِ تساوی در رأی نهایی است)"""
    hist = getattr(g, "defense_history", {}) or {}
    for s in (seats or []):
        if s in (getattr(g, "seats", {}) or {}):
            hist[s] = hist.get(s, 0) + 1
    g.defense_history = hist
    store.save()


SPEAK_ANCHOR_D3 = 6      # 🗣 روز ۳: ۶ → ۷ → ۸ → ۹ → ۱۰ → ۱ → ۲ → ۳ → ۴ → ۵ (صعودی، آخر ۵)
SPEAK_ANCHOR_D4 = 5      # 🗣 روز ۴: ۵ → ۴ → ۳ → ۲ → ۱ → ۱۰ → ۹ → ۸ → ۷ → ۶ (نزولی، آخر ۶)


def _day_speak_order(g):
    """🗣 ترتیبِ سرِ صحبت (و رأی‌گیری) — چرخهٔ ۴روزه، بعدش ریست:
    روز ۱: از اولین زنده، صعودی (۱→۱۰) | روز ۲: از آخرین زنده، نزولی (۱۰→۱)
    روز ۳: از صندلی ۶، صعودی (۶→۷→…→۱۰→۱→…→۵) | روز ۴: از صندلی ۵، نزولی (۵→۴→…→۱→۱۰→…→۶)
    اگر خودِ آن صندلی زنده نباشد، نزدیک‌ترین زنده در همان جهت جایش را می‌گیرد.
    در هر حالت یک دورِ کامل می‌چرخد و به نفرِ پشتِ سرِ شروع‌کننده ختم می‌شود."""
    alive = _alive_seats(g)
    n = len(alive)
    if n == 0:
        return []
    day = (getattr(g, "night_number", 0) or 0) + 1
    k = ((day - 1) % 4) + 1
    if k == 1:
        start_seat, step = alive[0], 1
    elif k == 2:
        start_seat, step = alive[-1], -1
    elif k == 3:
        step = 1
        start_seat = next((s for s in alive if s >= SPEAK_ANCHOR_D3), alive[0])
    else:
        step = -1
        start_seat = next((s for s in reversed(alive) if s <= SPEAK_ANCHOR_D4), alive[-1])
    i = alive.index(start_seat)
    return [alive[(i + step * j) % n] for j in range(n)]


_FA_OUT = str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹")


def _fa_seq(seats) -> str:
    """دنبالهٔ صندلی‌ها با عددِ فارسی و ویرگول — تا در چتِ راست‌به‌چپ وارونه دیده نشود.
    (عددِ انگلیسی + فلش در متنِ فارسی، جهتِ خط را به‌هم می‌ریخت و ترتیب برعکس رندر می‌شد.)"""
    return "، ".join(str(s).translate(_FA_OUT) for s in seats)


async def _announce_speak_order(ctx, chat_id, g):
    """🗣 اعلامِ سرِ صحبتِ امروز در گروه."""
    if not getattr(g, "assigned_roles", None) or g.phase in ("idle", "ended"):
        return
    order = _day_speak_order(g)
    if not order:
        return
    first = order[0]
    day = (getattr(g, "night_number", 0) or 0) + 1
    try:
        await ctx.bot.send_message(
            chat_id,
            f"🗣 <b>روز {day}</b> — سرِ صحبت: "
            f"<b>{first}. {escape(g.seats[first][1], quote=False)}</b>\n"
            f"ترتیب: {_fa_seq(order)}\n"
            f"نفرِ آخر: <b>{order[-1]}. {escape(g.seats[order[-1]][1], quote=False)}</b>",
            parse_mode="HTML")
    except Exception as e:
        print("⚠️ speak order:", e)


async def _offer_auto_defense(ctx, chat_id, g, counts=None):
    """بعد از پایانِ رأی اولیه: محاسبه‌ی حدنصاب، اعلامِ واجدانِ دفاعیه و پیشنهاد ساختِ رأی نهایی.
    counts (اختیاری): شمارشِ آماده — برای رأی‌گیری از طریقِ «پل»."""
    alive = len(_alive_seats(g))
    thr = _final_vote_threshold(alive, g)
    counts = ({t: len(v) for t, v in (g.votes_cast or {}).items()}
              if counts is None else {int(k): int(v) for k, v in counts.items()})
    order, seen = [], set()
    for t in (getattr(g, "vote_order", []) or []):
        if t not in seen and t in counts:
            seen.add(t); order.append(t)
    for t in counts:
        if t not in seen:
            seen.add(t); order.append(t)
    qualified = [t for t in order
                 if counts.get(t, 0) >= thr and t in g.seats and t not in (g.striked or set())]

    # مرتب‌سازی بر اساس تعداد رأی (نزولی)؛ در تساوی، ترتیبِ رأی‌گیری
    qualified.sort(key=lambda t: (-counts.get(t, 0), order.index(t)))

    # ⚖️ قانونِ اختلاف آرا — ساده: هرکس ۳ رأی یا بیشتر از نفرِ اول عقب باشد،
    #    اصلاً واردِ دفاعیه نمی‌شود. (۴ و ۵ و ۷ → فقط ۵ و ۷)
    gap_note = None
    if qualified:
        top = counts.get(qualified[0], 0)
        dropped = [t for t in qualified if (top - counts.get(t, 0)) >= 3]
        if dropped:
            qualified = [t for t in qualified if t not in dropped]
            _nms = "، ".join(f"{t}. {escape(g.seats[t][1], quote=False)}"
                             for t in sorted(dropped))
            gap_note = (f"⚖️ اختلافِ ۳ رأی یا بیشتر با نفرِ اول ({top} رأی) → "
                        f"{_nms} واردِ دفاعیه نمی‌شود.")

    # 🔢 ترتیبِ نهایی (لیست و دکمه‌های رأی نهایی) = ترتیبِ رأی‌گیریِ اولیه، نه تعدادِ رأی
    qualified.sort(key=lambda t: order.index(t))

    # ⚖️ نماینده: اکتِ وکیل (فقط ۲۴ ساعت — همان شبِ قبل) مانع ورود به دفاعیه می‌شود
    lawyer_seat = None
    if _is_nemayande_scenario(g):
        lt = getattr(g, "night_lawyer_target", None)
        if lt in qualified:
            # 💻 اگر هکر همان شب اکتِ وکیل را روی همین موکل بسته باشد،
            #    وکالت به او نرسیده → مثلِ بقیه واردِ دفاع می‌شود (گروه چیزی نمی‌فهمد)
            _law = _find_seat_role_sub(g, _R_LAWYER, alive_only=False)
            if (_law is not None
                    and getattr(g, "night_hacker_actor", None) == _law
                    and getattr(g, "night_hacker_target", None) == lt):
                await _night_report(ctx, g, f"💻 وکالتِ <b>{lt}</b> دیشب هک شده بود → بی‌اثر؛ "
                                            f"واردِ دفاع می‌شود (فقط تو می‌دانی).")
            else:
                qualified.remove(lt)
                lawyer_seat = lt

    if not qualified and lawyer_seat is None:
        await ctx.bot.send_message(chat_id, f"ℹ️ هیچ‌کس به حدنصاب دفاعیه ({thr} رأی) نرسید.")
        return

    lines = [f"🗳 حدنصاب دفاعیه با {alive} بازیکنِ زنده: <b>{thr}</b> رأی",
             "🧍 <b>این افراد داخل دفاعیه هستند:</b>"]
    for t in qualified:
        lines.append(f"• {t}. {escape(g.seats[t][1], quote=False)} — {counts.get(t, 0)} رأی")
    if gap_note:
        lines.append(gap_note)
    if lawyer_seat is not None:
        lines.append(f"⚖️ {lawyer_seat}. {escape(g.seats[lawyer_seat][1], quote=False)} "
                     f"با اکتِ وکیل واردِ دفاع نمی‌شود.")
    if not qualified:
        await ctx.bot.send_message(chat_id, "\n".join(lines), parse_mode="HTML")
        return

    g.pending_defense = list(qualified)
    store.save()
    lines.append("")
    lines.append("تأیید می‌کنید؟ (با «بله» رأی‌گیری نهایی برای همین افراد ساخته می‌شود)")
    kb = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ بله", callback_data="autofinal_yes"),
        InlineKeyboardButton("🚫 خیر", callback_data="autofinal_no"),
    ]])
    await ctx.bot.send_message(chat_id, "\n".join(lines), parse_mode="HTML", reply_markup=kb)


# ═══════════════ 🏅 موتورِ امتیازدهی (تستی) ═══════════════
def _sc_add(g, seat, cat, pts, reason):
    """ثبتِ یک رویدادِ امتیازی برای صندلی."""
    if seat is None or seat not in (g.seats or {}):
        return
    ev = g.score_events.setdefault(seat, [])
    ev.append((cat, float(pts), reason))


def _sc_side(g, seat):
    """سایدِ لحظه‌ای صندلی: مافیا (شامل مذاکره/یاکوزا/خریداری) / مستقل / شهر."""
    try:
        if seat in _mafia_seats(g):
            return "مافیا"
    except Exception:
        pass
    ss = getattr(g, "seat_sides", None) or {}
    s = ss.get(seat, "شهر")
    return "مستقل" if s == "مستقل" else ("مافیا" if s == "مافیا" else "شهر")


def _sc_side_final(g, seat):
    """سایدِ «نهایی» برای امتیاز و آمار: مثلِ _sc_side، به‌علاوهٔ اسمیگلِ خیانت‌کرده که
    در شمارشِ بُرد شهروند می‌ماند ولی امتیاز و بُرد/باختش با تیمِ مافیا ثبت می‌شود."""
    try:
        if (getattr(g, "gm_smeagol_turned", False)
                and _R_SMEAGOL in _seat_role_norm(g, seat)):
            return "مافیا"
    except Exception:
        pass
    return _sc_side(g, seat)


def _score_votes_initial(g):
    """تشخیص: رأی اولیه به مافیا +۵ / به شهروند −۲.۵ (فقط برای رأی‌دهنده‌ی شهروند)."""
    try:
        for t, voters in (g.votes_cast or {}).items():
            if t not in g.seats:
                continue
            tside = _sc_side(g, t)
            for u in (voters or set()):
                vs = _seat_of_uid(g, u)
                if vs is None or vs == t or _sc_side(g, vs) != "شهر":
                    continue
                if tside == "مافیا":
                    _sc_add(g, vs, "tash", 5, "رأی اولیه به مافیا")
                    # 🎭 فریبِ مافیا: هر رأیِ اولیه‌ای که از «شهروند» می‌خورد −۲.۵
                    _sc_add(g, t, "farib1", -2.5, "رأی اولیه از شهروند")
                elif tside == "شهر":
                    _sc_add(g, vs, "tash", -2.5, "رأی اولیه به شهروند")
        g.score_day_initial = True
        store.save()
    except Exception as e:
        print("⚠️ score initial err:", e)


def _score_votes_final(g, targets, exit_seat, exited):
    """تشخیص رأی نهایی (+۱۰/−۵/−۱۰ جایگزین) + پوشِ مافیا + فریبِ «به دفاع نیامد»."""
    try:
        for t in targets:
            if t not in g.seats:
                continue
            tside = _sc_side(g, t)
            for u in (g.votes_cast.get(t) or set()):
                vs = _seat_of_uid(g, u)
                if vs is None or vs == t:
                    continue
                vside = _sc_side(g, vs)
                if vside == "شهر":
                    if tside == "مافیا":
                        if exited and t == exit_seat:
                            _sc_add(g, vs, "tash", 20, "رأی منجر به خروجِ مافیا")
                        else:
                            _sc_add(g, vs, "tash", 10, "رأی خروج به مافیا")
                    elif tside == "شهر":
                        if exited and t == exit_seat:
                            _sc_add(g, vs, "tash", -10, "رأی خروج منجر به خروجِ شهروند")
                        else:
                            _sc_add(g, vs, "tash", -5, "رأی خروج به شهروند")
                elif vside == "مافیا":
                    if tside == "شهر" and exited and t == exit_seat:
                        _sc_add(g, vs, "push", 15, "پوش: دخالت در خروجِ شهروند")
                    elif tside == "مافیا":
                        # 🔻 رأی نهایی به هم‌تیمی: −۵ / اگر منجر به خروجش شد: −۱۰ (جایگزین)
                        if exited and t == exit_seat:
                            _sc_add(g, vs, "push", -10, "رأی منجر به خروجِ هم‌تیمی")
                        else:
                            _sc_add(g, vs, "push", -5, "رأی خروج به هم‌تیمیِ مافیا")
        # فریب (کسرشونده از ۴۰): حضور در دفاع −۵؛ خروج با رأی → فریب کلاً صفر (کسی را فریب نداده)
        for t in targets:
            if t in g.seats and _sc_side(g, t) == "مافیا":
                if exited and t == exit_seat:
                    _sc_add(g, t, "farib1", -100, "خروج با رأی — فریب صفر")
                else:
                    _sc_add(g, t, "farib1", -10, "حضور در دفاع")
        g.score_day_final = True
        store.save()
    except Exception as e:
        print("⚠️ score final err:", e)


def _score_day_rollover(g):
    """مرزِ روز→شب: ریستِ پرچم‌های روز (فریب کسرشونده است؛ روزِ بدونِ دفاع = بدونِ کسر)."""
    try:
        g.score_day_initial = False
        g.score_day_final = False
        store.save()
    except Exception as e:
        print("⚠️ score rollover err:", e)


def _score_compute(g):
    """محاسبه‌ی نهایی: seat → {side, total, parts, no_act} طبق قوانین (سقف/کف/بازتوزیع)."""
    out = {}
    ev = getattr(g, "score_events", {}) or {}
    warns = getattr(g, "warnings", {}) or {}
    kicked = getattr(g, "score_kicked", set()) or set()
    # 🏅 در سناریوهای بدونِ استعلامِ وضعیت (میتیک/کلاسیک/کلاسیک‌دن) کیک امتیاز را صفر
    #    نمی‌کند — نشانِ «✖️کیک» در لیست سرِ جایش می‌ماند، فقط نمره نمی‌سوزد
    if _side_secret(g):
        kicked = set()
    impossible = getattr(g, "score_act_impossible", set()) or set()
    for seat in sorted(g.seats or {}):
        side = _sc_side_final(g, seat)   # 🌀 اسمیگلِ خیانت‌کرده → مافیا
        sev = ev.get(seat, []) or []

        # 👢 کیک‌شده: همه‌ی امتیازها صفر (برد، تشخیص/فریب/پوش، حدس، انضباط — همه)
        if seat in kicked:
            if side == "مافیا":
                parts = {"win": 0.0, "farib": 0.0, "push": 0.0, "enz": 0.0}
            else:
                parts = {"win": 0.0, "tash": 0.0, "guess": 0.0, "enz": 0.0}
            out[seat] = {"side": side, "total": 0.0, "parts": parts}
            continue

        def _sum(cat):
            return sum(p for c, p, _r in sev if c == cat)

        # 📐 فرمولِ یکدست (اکتِ شب فعلاً در امتیاز لحاظ نمی‌شود؛ رویدادها برای آینده ثبت می‌مانند)
        win = 25.0 if side == getattr(g, "winner_side", None) else 0.0
        enz = 0.0 if seat in kicked else max(0.0, 15.0 - 5.0 * int(warns.get(seat, 0) or 0))
        if side == "مافیا":
            # فریب: پایه‌ی ۴۰ منهای کسرها (رأی اولیه از شهروند −۲.۵، حضور در دفاع −۱۰) — بازه [۰، ۴۰]
            farib = max(0.0, min(40.0, 40.0 + _sum("farib1")))
            # 🚪 به هر نحوی از بازی خارج شده (شات، رأی، دوئل…) → فریب صفر — جز فدای یاکوزایی
            if (seat in (g.striked or set())
                    and seat not in (getattr(g, "score_yakuza_sac", set()) or set())):
                farib = 0.0
            push = max(0.0, min(20.0, _sum("push")))   # کف ۰ (رأی به هم‌تیمی منفی دارد)
            parts = {"win": win, "farib": farib, "push": push, "enz": enz}
            total = win + farib + push + enz
        else:
            tash = max(0.0, min(60.0, _sum("tash")))
            guess = _sum("guess")   # 🎯 جایزه‌ی حدسِ شهروندِ خروجیِ روز ۱ (خارج از سقف)
            parts = {"win": win, "tash": tash, "guess": guess, "enz": enz}
            total = win + tash + guess + enz
        out[seat] = {"side": side, "total": round(total, 1), "parts": parts}
    return out


def _sc_fmt(x):
    try:
        v = float(x)
        s = str(int(v)) if v.is_integer() else f"{v:.1f}"
    except Exception:
        s = str(x)
    # 🔡 اعداد یکدستِ فارسی
    return s.translate(str.maketrans("0123456789.", "۰۱۲۳۴۵۶۷۸۹٫"))


def _score_card_lines(g, scores):
    """کارنامه‌ی امتیاز برای گروه — به تفکیکِ اجزا."""
    lines = ["🏅 <b>امتیازِ این بازی (از ۱۰۰)</b>"]
    for seat in sorted(scores):
        sc = scores[seat]
        p = sc["parts"]
        name = escape(g.seats[seat][1], quote=False)
        if sc["side"] == "مافیا":
            mark = "◾️"
            det = f"برد {_sc_fmt(p['win'])} | فریب {_sc_fmt(p['farib'])}/۴۰ | پوش {_sc_fmt(p['push'])}/۲۰"
        else:
            mark = "♦️" if sc["side"] == "مستقل" else "◽️"
            det = f"برد {_sc_fmt(p['win'])} | تشخیص {_sc_fmt(p['tash'])}/۶۰"
            if p.get("guess"):
                det += f" | حدس {_sc_fmt(p['guess'])}"
        det += f" | انضباط {_sc_fmt(p['enz'])}"
        lines.append(f"{mark}{seat}. {name} — <b>{_sc_fmt(sc['total'])}</b> ({det})")
    lines.append("")
    lines.append(CHANNEL_AD)
    return lines
_SC_SHOOTER_ROLES = ("دن‌کارلئونه", "دن‌مافیا", "دن", "جلاد", "کاپو", "رئیس‌مافیا", "پدرخوانده")
_SC_SNIPER_ROLES = ("تک‌تیرانداز", "اسنایپر", "ریک‌گرایمز", "تکاور", "هانتر", "شکارچی")
_SC_DOCTOR_ROLES = ("پزشک", "دکتر", "کستیل", "دکترواتسون")


def _sc_find_role(g, names):
    for n in names:
        try:
            s = _find_seat_by_role(g, _nz(n))
        except Exception:
            s = None
        if s is not None:
            return s
    return None


def _score_night_acts(g, dead, reasons):
    """🏅 امتیازِ اکت‌های شب — مشترک بین همه‌ی سناریوها (از خروجیِ resolve)."""
    try:
        # ── شاتِ تیمِ مافیا ──
        st = getattr(g, "night_shot_target", None)
        if st and st in g.seats:
            out = _shot_outcome(g, st)
            shooter = _sc_find_role(g, _SC_SHOOTER_ROLES)
            good = (out == "kill" and _sc_side(g, st) != "مافیا")
            if shooter is not None:
                if good:
                    _sc_add(g, shooter, "act", 15, f"شاتِ موفق روی {st}")
                else:
                    _sc_add(g, shooter, "act", -5, f"شاتِ ناموفق روی {st} ({out})")

        # ── سیوِ پزشک: سیوِ مافیا = فریبِ مافیا + اکتِ منفیِ پزشک؛ سیوِ شاتِ شهروند = اکتِ موفق ──
        doc = _sc_find_role(g, _SC_DOCTOR_ROLES)
        for sv in (getattr(g, "night_doc_saved", None) or []):
            if sv not in g.seats:
                continue
            if _sc_side(g, sv) == "مافیا":
                _sc_add(g, sv, "farib2", 5, "سیوِ اشتباهِ پزشک روی مافیا")
                if doc is not None:
                    _sc_add(g, doc, "act", -5, f"سیوِ مافیا ({sv})")
            elif doc is not None and st and sv == st and _shot_outcome(g, sv) == "saved":
                _sc_add(g, doc, "act", 15, f"سیوِ موفقِ {sv}")

        # ── تیرهای تکی و مین (از روی دلیلِ مرگ) ──
        for s, r in (reasons or {}).items():
            if s not in g.seats:
                continue
            rn = _nz(str(r))
            # 🥷 فدای یاکوزایی: تنها خروجی که فریبش صفر «نمی‌شود»
            if "یاکوزایی" in rn and "فدا" in rn:
                g.score_yakuza_sac.add(s)
            if any(k in rn for k in ("تکتیر", "اسنایپ", "شکار", "تیرِریک", "تیرریک")):
                sn = _sc_find_role(g, _SC_SNIPER_ROLES)
                if sn is not None:
                    if _sc_side(g, s) == "مافیا":
                        _sc_add(g, sn, "act", 15, f"تیرِ درست روی {s}")
                    else:
                        _sc_add(g, sn, "act", -5, f"تیرِ اشتباه روی {s}")
            if "مین" in rn:
                ml = _sc_find_role(g, ("مین‌گذار",))
                if ml is not None:
                    if _sc_side(g, s) != "مافیا":
                        _sc_add(g, ml, "act", 15, f"مینِ موفق ({s})")
                    else:
                        _sc_add(g, ml, "act", -5, f"مین روی مافیا ({s})")
        store.save()
    except Exception as e:
        print("⚠️ score night acts err:", e)


# ── 🎯 حدسِ ۳ مافیا — شهروندِ خروجیِ روزِ ۱ (۲:۳۰ فرصت، هر حدسِ درست +۱۵) ──
def _d1_guess_kb(g):
    ex = getattr(g, "d1_guess_seat", None)
    picks = getattr(g, "d1_guess_picks", []) or []
    rows = []
    for s in sorted(g.seats):
        if s == ex or s in (g.striked or set()):
            continue
        mark = "✅ " if s in picks else ""
        rows.append([InlineKeyboardButton(f"{mark}{s} {g.seats[s][1]}", callback_data=f"d1g_{s}")])
    rows.append([InlineKeyboardButton("🎯 تأیید (۳ نفر)", callback_data="d1g_ok")])
    return InlineKeyboardMarkup(rows)


async def _d1_guess_finish(ctx, g, timeout=False):
    if getattr(g, "d1_guess_done", False):
        return
    g.d1_guess_done = True
    seat = g.d1_guess_seat
    picks = list(getattr(g, "d1_guess_picks", []) or [])[:3]
    correct = [s for s in picks if _sc_side(g, s) == "مافیا"]
    pts = 15 * len(correct)
    if pts and seat in g.seats:
        _sc_add(g, seat, "guess", pts, f"{len(correct)} حدسِ درستِ مافیا")
    store.save()
    try:
        txt = "⏱ وقت تمام شد — " if timeout else ""
        await ctx.bot.send_message(g.seats[seat][0],
                                   f"{txt}🎯 حدس‌هایت ثبت شد. نتیجه پایانِ بازی مشخص می‌شود.")
    except Exception:
        pass
    pk = "، ".join(str(x) for x in picks) if picks else "—"
    ck = "، ".join(str(x) for x in correct) if correct else "—"
    await _night_report(ctx, g, f"🎯 حدسِ شهروندِ خروجی ({seat}): [{pk}] → درست: [{ck}] = +{pts}")


async def _d1_guess_start(ctx, g, seat):
    """فقط برای شهروندِ خروجیِ روزِ ۱ — یک‌بار در بازی."""
    if getattr(g, "d1_guess_seat", None) is not None or getattr(g, "d1_guess_done", False):
        return
    if getattr(g, "night_number", 0) != 0 or seat not in g.seats or _sc_side(g, seat) != "شهر":
        return
    g.d1_guess_seat = seat
    g.d1_guess_picks = []
    g.d1_guess_done = False
    store.save()
    m = await _safe_pm(ctx, g.seats[seat][0],
                       "🎯 تو شهروندِ خروجیِ روزِ اولی!\n"
                       "۳ نفر را که فکر می‌کنی تیمِ مافیا هستند انتخاب کن.\n"
                       "⏱ ۲ دقیقه و ۳۰ ثانیه فرصت داری — هر حدسِ درست ۱۵ امتیاز!",
                       _d1_guess_kb(g))
    if not m:
        g.d1_guess_done = True
        store.save()
        await _night_report(ctx, g, f"🎯 پیویِ شهروندِ خروجی ({seat}) بسته بود — حدسِ مافیا انجام نشد.")
        return
    await _night_report(ctx, g, f"🎯 حدسِ ۳ مافیا برای شهروندِ خروجی ({seat}) فرستاده شد — ⏱ ۲:۳۰")

    async def _d1_timer():
        try:
            await asyncio.sleep(150)
            if not getattr(g, "d1_guess_done", False):
                await _d1_guess_finish(ctx, g, timeout=True)
        except Exception as e:
            print("⚠️ d1 timer err:", e)
    asyncio.create_task(_d1_timer())


async def handle_d1_guess_callback(update, ctx):
    q = update.callback_query
    data = q.data
    uid = q.from_user.id
    g = None
    for cid, game in store.games.items():
        ds = getattr(game, "d1_guess_seat", None)
        if (ds is not None and not getattr(game, "d1_guess_done", False)
                and ds in game.seats and game.seats[ds][0] == uid):
            g = game
            break
    if g is None:
        await safe_q_answer(q, "مهلت تمام شده یا درخواستِ فعالی نیست.", show_alert=True)
        return
    mid = q.message.message_id if q.message else None
    if data == "d1g_ok":
        if len(g.d1_guess_picks or []) != 3:
            await safe_q_answer(q, "دقیقاً ۳ نفر را انتخاب کن.", show_alert=True)
            return
        await safe_q_answer(q)
        try:
            await _close_pm(ctx, uid, mid, "🎯 ثبت شد.")
        except Exception:
            pass
        await _d1_guess_finish(ctx, g, timeout=False)
        return
    s = int(data.rsplit("_", 1)[1])
    picks = list(g.d1_guess_picks or [])
    if s in picks:
        picks.remove(s)
    elif len(picks) < 3:
        picks.append(s)
    else:
        await safe_q_answer(q, "حداکثر ۳ نفر — یکی را بردار.", show_alert=True)
        return
    await safe_q_answer(q)
    g.d1_guess_picks = picks
    store.save()
    await _edit_pm(ctx, uid, mid,
                   "🎯 ۳ نفر را که فکر می‌کنی تیمِ مافیا هستند انتخاب کن:", _d1_guess_kb(g))
# ═══════════════ پایانِ موتورِ امتیازدهی ═══════════════


async def _finalize_final_vote(ctx, chat_id, g):
    """بعد از «پایان رأی‌گیری نهایی»: تعیینِ خروج (با سابقه در تساوی) + افتادنِ زره/شیلد + ثبتِ سابقه."""
    # 🗳 «کی به کی رأی داد» را نگه دار — بلافاصله بعدِ این تابع آرا پاک می‌شوند و
    #    اکت‌هایی مثلِ دکستر (گیمر) به همین سابقه نیاز دارند.
    try:
        _lfv = {}
        for _t, _voters in (g.votes_cast or {}).items():
            if _t not in g.seats:
                continue
            _lfv[_t] = sorted({s for s in (_seat_of_uid(g, u) for u in (_voters or set()))
                               if s is not None})
        g.last_final_votes = _lfv
    except Exception as _e:
        print("⚠️ last_final_votes:", _e)

    counts = {t: len(v) for t, v in (g.votes_cast or {}).items()
              if t in g.seats and t not in (g.striked or set())}
    targets, seen = [], set()
    for t in (getattr(g, "vote_order", []) or []):
        if t in counts and t not in seen:
            seen.add(t); targets.append(t)
    for t in counts:
        if t not in seen:
            seen.add(t); targets.append(t)
    if not targets:
        return

    # 🗡 دنگ خیانت (نماینده — فقط اولین رأی نهایی بعد از ثبت): ±۱ روی نفرِ اول/دومِ رأی‌گیری
    if (_is_nemayande_scenario(g) and getattr(g, "nem_ding", None)
            and not getattr(g, "nem_ding_used", False)
            and isinstance(g.nem_ding, tuple) and g.nem_ding[1] != 0):
        idx, sign = g.nem_ding
        g.nem_ding_used = True
        store.save()
        if g.night_number != 0:
            # ⏳ فقط روزِ ۱ اعتبار دارد — روزهای بعد بی‌صدا منقضی (فقط گاد می‌فهمد)
            await _night_report(ctx, g, "🗡 دنگ خیانت فقط برای روزِ ۱ بود — منقضی شد.")
        else:
            rep_lbl = "اول" if idx == 0 else "دوم"
            sign_lbl = "مثبت (+۱)" if sign > 0 else "منفی (−۱)"
            if idx < len(targets):
                t = targets[idx]
                old_c = counts[t]
                counts[t] = max(0, old_c + sign)
                note = (f"🗡 با احتسابِ دنگ خیانتِ {sign_lbl} روی نماینده‌ی {rep_lbl}: "
                        f"آرای نفرِ {rep_lbl} رأی‌گیری ({t}. {escape(g.seats[t][1], quote=False)}): "
                        f"{old_c} ← <b>{counts[t]}</b>")
            else:
                note = (f"🗡 دنگ خیانتِ {sign_lbl} روی نماینده‌ی {rep_lbl} بود، "
                        f"اما نفرِ {rep_lbl}ی در رأی‌گیری نبود — بی‌اثر.")
            await ctx.bot.send_message(chat_id, note, parse_mode="HTML")
            await _night_report(ctx, g, note)

    hist = getattr(g, "defense_history", {}) or {}
    alive = len(_alive_seats(g))
    thr = _final_vote_threshold(alive, g)
    reached = [t for t in targets if counts[t] >= thr]

    exiter = None
    if reached:
        mx = max(counts[t] for t in reached)
        tops = [t for t in reached if counts[t] == mx]
        if len(tops) == 1:
            exiter = tops[0]
        else:
            # 📜 تساوی آرا → سابقه‌ی بیشتر (دفعاتِ حضور در رأی نهایی) خارج می‌شود
            hmx = max(hist.get(t, 0) for t in tops)
            htops = [t for t in tops if hist.get(t, 0) == hmx]
            if len(htops) == 1:
                exiter = htops[0]
                await ctx.bot.send_message(
                    chat_id,
                    f"📜 تساوی آرا — {exiter}. {escape(g.seats[exiter][1], quote=False)} "
                    f"به‌دلیلِ سابقه‌ی بیشتر ({hmx} بار حضور در دفاع) انتخاب شد.",
                    parse_mode="HTML")
            else:
                await ctx.bot.send_message(chat_id, "📜 تساوی آرا و تساوی سابقه — تصمیم با گاد.")

    # 📜 ثبتِ سابقه برای همه‌ی حاضرانِ دفاعِ امروز
    _bump_defense_history(g, targets)

    if exiter is None:
        _score_votes_final(g, targets, None, False)   # 🏅 کسی خارج نشد
        return

    nm = escape(g.seats[exiter][1], quote=False)
    # ⚠️ پیامِ یکسان برای همه — هیچ ساید/نقشی لو نمی‌رود
    await ctx.bot.send_message(chat_id, f"🚪 {exiter}. {nm} حد نصاب آورد — وصیت کند.",
                               parse_mode="HTML")

    # 💠 سنگِ روحِ تانوس: ۲۴ ساعت نه اجماع می‌شود نه شات
    if (_is_gamer17(g) and _seat_role_norm(g, exiter) == _R_GM_THANOS
            and int(getattr(g, "gm_th_soul_day", 0) or 0) >= int(g.night_number or 0)):
        await ctx.bot.send_message(
            chat_id, f"🕊 {exiter}. {escape(g.seats[exiter][1], quote=False)} "
                     f"حد نصاب آورد ولی از بازی خارج نشد.", parse_mode="HTML")
        await _night_report(ctx, g, "💠 سنگِ روح — تانوس با رأی خارج نشد (فقط تو می‌دانی).")
        _score_votes_final(g, targets, None, False)
        return

    # 🛡 زره‌پوش (مذاکره) و نگهبانِ شیلددار (تکاور) خط نمی‌خورند —
    #    تصمیم (افتادنِ شیلد یا خروج) با خودِ گاد است
    rn = _seat_role_norm(g, exiter)
    protected = ((_is_takavar_scenario(g) and rn == _R_WATCHMAN
                  and not getattr(g, "tk_shield_lost", False))
                 or (_is_neg_scenario(g) and rn == _R_ARMORED
                     and not getattr(g, "zereh_fallen", False)))
    if protected:
        # 🛡 افتادنِ خودکارِ زره/شیلد با همین رأی — بدونِ اعلامِ عمومی (نقش لو نمی‌رود)
        if rn == _R_WATCHMAN:
            g.tk_shield_lost = True
        else:
            g.zereh_fallen = True
        store.save()
        await _night_report(ctx, g,
                            f"🛡 {exiter}. {nm} با رأی خارج نشد — زره/شیلدش از همین حالا افتاد (فقط تو می‌دانی).")
    if not protected:
        g.striked.add(exiter)
        store.save()
        await _room_drop_dead(ctx, g)   # 🚪 خروجی‌شدهٔ مافیا، همان لحظه از اتاق بیرون
        try:
            await publish_seating(ctx, chat_id, g, mode=CTRL)
        except Exception:
            pass
        await _check_auto_end(ctx, chat_id, g)   # 🏁
        _bzp_hunter_day_exit(ctx, chat_id, g, exiter)   # 🪢 هانترِ درست‌بسته → ۹۰ ثانیه بعد
        _hb_day_exit(ctx, chat_id, g, exiter)           # 🧬 بافتِ هانیبال → ۹۰ ثانیه بعد

    # 🏅 امتیازِ رأی نهایی (خروجِ واقعی = وقتی خط خورده باشد)
    _score_votes_final(g, targets, exiter, not protected)

    # 🎯 خروجِ خودکارِ شهروند در روزِ ۱ → حدسِ ۳ مافیا
    if not protected:
        await _d1_guess_start(ctx, g, exiter)


def _autovote_pending(g):
    """🤖 کسانی که هنوز ازشان رأی گرفته نشده.
    تا وقتی خالی نشده، دکمهٔ «رأی‌گیریِ اتومات» در کیبورد می‌ماند."""
    cands = [x for x in (g.vote_candidates or [])
             if x in g.seats and x not in (g.striked or set())]
    done = set(getattr(g, "voted_targets", set()) or set())
    return [x for x in cands if x not in done]


def _autovote_row(g, stage):
    """ردیفِ دکمهٔ اتومات — در هر ظرفیتی (ترتیبِ سرِ صحبت برای هر تعدادی کار می‌کند).
    فقط وقتی از همه رأی گرفته شده یا در حالِ اجراست، هیچ."""
    if getattr(g, "auto_vote_running", False) or not _autovote_pending(g):
        return []
    cb = "autovote_initial" if stage == "initial_vote" else "autovote_final"
    return [[InlineKeyboardButton("🤖 رأی‌گیریِ اتومات", callback_data=cb)]]


async def start_vote(ctx, chat_id: int, g: GameState, stage: str):
    g.vote_stage = stage
    g.tally = {}
    g.current_target = None
    g.collecting = False

    candidates = g.defense_seats if stage == "final" else list(g.seats.keys())
    g.vote_candidates = [s for s in candidates if s not in g.striked]
    if stage != "final":
        g.vote_candidates = sorted(g.vote_candidates)

    btns = []
    for s in g.vote_candidates:
        name = g.seats[s][1]
        label = f"✅ {s}. {name}" if s in getattr(g, "voted_targets", set()) else f"{s}. {name}"
        btns.append([InlineKeyboardButton(label, callback_data=f"vote_{s}")])

    if stage == "initial_vote":
        btns.append([InlineKeyboardButton("🧹 پاک کردن رأی‌گیری", callback_data="clear_vote_initial")])
        btns.extend(_autovote_row(g, "initial_vote"))
        btns.append([InlineKeyboardButton("✅ پایان رأی‌گیری", callback_data="vote_done_initial")])
    else:  # final
        btns.append([InlineKeyboardButton("🧹 پاک کردن رأی‌گیری", callback_data="clear_vote_final")])
        btns.extend(_autovote_row(g, "final"))
        btns.append([InlineKeyboardButton("✅ پایان رأی‌گیری", callback_data="vote_done_final")])

    back_code = "back_vote_init" if stage == "initial_vote" else "back_vote_final"
    btns.append([InlineKeyboardButton("⬅️ بازگشت", callback_data=back_code)])

    title = "🗳 رأی‌گیری اولیه – انتخاب هدف:" if stage == "initial_vote" else "🗳 رأی‌گیری نهایی – انتخاب حذف:"
    msg = await ctx.bot.send_message(chat_id, title, reply_markup=InlineKeyboardMarkup(btns))

    g.vote_msg_id = msg.message_id

    if stage == "initial_vote":
        g.first_vote_msg_id_initial = msg.message_id
        g.last_vote_msg_id_initial = msg.message_id
    elif stage == "final":
        g.first_vote_msg_id_final = msg.message_id
        g.last_vote_msg_id_final = msg.message_id

    store.save()


async def _finish_initial_vote(ctx, chat_id, g):
    await ctx.bot.send_message(chat_id, "✅ رأی‌گیری اولیه تمام شد.")
    await _offer_auto_defense(ctx, chat_id, g)   # 🧍 دفاعیه‌ی خودکار (قبل از پاک شدن آرا)
    _score_votes_initial(g)                      # 🏅 تشخیصِ رأی اولیه (قبل از پاک شدن آرا)
    g.votes_cast = {}
    g.vote_logs = {}
    g.current_vote_target = None
    g.vote_window = None
    g.vote_prev_window = None
    g.vote_bounds = None
    g.vote_prev_bounds = None
    g.vote_has_ended_initial = True
    g.vote_order = []
    store.save()


async def _finish_final_vote(ctx, chat_id, g):
    await ctx.bot.send_message(chat_id, "✅ رأی‌گیری نهایی تمام شد.")
    await _finalize_final_vote(ctx, chat_id, g)   # 🚪 خروج/سابقه/افتادنِ زره و شیلد
    g.votes_cast = {}
    g.vote_logs = {}
    g.current_vote_target = None
    g.vote_window = None
    g.vote_prev_window = None
    g.vote_bounds = None
    g.vote_prev_bounds = None
    g.vote_has_ended_final = True
    g.vote_order = []
    store.save()


AUTO_VOTE_GAP = 3         # ⏳ مکثِ ساکت بینِ دو نفر در رأی‌گیریِ اتومات
# ⏳ بعد از نفرِ آخر، قبل از شمارش. رأی با «ساعتِ ارسال» ثبت می‌شود ولی فقط وقتی
#    به بات برسد؛ در حالتِ دستی گاد چند ثانیه بعد «پایان» را می‌زند و رأی‌های
#    در راه می‌رسند. اتومات چون بلافاصله می‌شمرد، آن‌ها را جا می‌گذاشت.
AUTO_VOTE_SETTLE = 6
POLL_VOTE_SECONDS = 15    # ⏳ فرصتِ رأی‌دادن در حالتِ «پل»


async def _run_auto_vote(ctx, chat_id, g, stage):
    """🤖 رأی‌گیریِ اتومات: بات خودش به‌ترتیب از همه رأی می‌گیرد و آخرش جمع‌بندی می‌کند.
    دیگر لازم نیست گاد روی تک‌تکِ دکمه‌ها بزند (تا نتِ ضعیفش پنجره را کوتاه نکند)."""
    if getattr(g, "auto_vote_running", False):
        await ctx.bot.send_message(chat_id, "⏳ رأی‌گیریِ اتومات همین الان در جریان است.")
        return
    cands = [s for s in (g.vote_candidates or [])
             if s in g.seats and s not in (g.striked or set())]
    if stage == "initial_vote":
        order = [s for s in _day_speak_order(g) if s in cands]
    else:
        order = [s for s in (g.defense_seats or []) if s in cands]
    for s in cands:                       # هرکس از قلم افتاد ته صف
        if s not in order:
            order.append(s)
    done = set(getattr(g, "voted_targets", set()) or set())
    todo = [s for s in order if s not in done]
    if not todo:
        await ctx.bot.send_message(chat_id, "ℹ️ از همه رأی گرفته شده — «پایان رأی‌گیری» را بزن.")
        return

    g.auto_vote_running = True
    store.save()
    panel_mid = None
    stopped = False
    try:
        _m = await ctx.bot.send_message(
            chat_id,
            "🤖 <b>رأی‌گیریِ اتومات شروع شد</b>\n"
            f"ترتیب: {_fa_seq(todo)}\n"
            "<i>گاد لازم نیست دکمه بزند؛ بات خودش تا آخر می‌رود.</i>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("⏹ توقف", callback_data="autovote_stop")]]))
        panel_mid = _m.message_id
        for s in todo:
            if s in (g.striked or set()):
                continue
            # 🎙 «رأی‌گیری برای صندلیِ N» همین اول، تا در مکثِ ۳ ثانیه‌ای گفته شود
            #    (بعد از «تمام»ِ نفرِ قبل، یا بلافاصله بعد از دکمه برای نفرِ اول)
            voice_god.say(chat_id, f"vote_{s}")
            # ⏳ مهلتِ ساکت پیش از هر نفر — شاملِ نفرِ اول، تا بعدِ زدنِ دکمه
            #    یکهو شروع نشود. هیچ پیامی نوشته نمی‌شود.
            await asyncio.sleep(AUTO_VOTE_GAP)
            if g.phase in ("idle", "ended") or not getattr(g, "auto_vote_running", False):
                await ctx.bot.send_message(chat_id, "⏹ رأی‌گیریِ اتومات متوقف شد.")
                stopped = True
                return
            if s in (g.striked or set()):
                continue
            # 🔇 کیبورد وسطِ کار به‌روز نمی‌شود تا سقفِ پیامِ تلگرام پُر نشود
            await handle_vote(ctx, chat_id, g, s, refresh_buttons=False)
    finally:
        g.auto_vote_running = False
        store.save()
        # 🧹 پیامِ «شروع شد» با دکمهٔ توقف دیگر لازم نیست
        if panel_mid:
            try:
                await ctx.bot.delete_message(chat_id=chat_id, message_id=panel_mid)
            except Exception:
                try:
                    await ctx.bot.edit_message_reply_markup(
                        chat_id=chat_id, message_id=panel_mid, reply_markup=None)
                except Exception:
                    pass
        try:
            await update_vote_buttons(ctx, chat_id, g)   # یک‌بار، در پایان
        except Exception:
            pass

    if stopped:
        return

    # ⏳ فرصت به رأی‌های در راه تا برسند، بعد شمارش
    try:
        await ctx.bot.send_message(chat_id, "⏳ چند لحظه — رأی‌های دیررسیده هم شمرده می‌شوند…")
    except Exception:
        pass
    await asyncio.sleep(AUTO_VOTE_SETTLE)

    # ✅ نفرِ آخر هم تیک خورد → خودکار جمع‌بندی
    if stage == "initial_vote":
        await _finish_initial_vote(ctx, chat_id, g)
    else:
        await _finish_final_vote(ctx, chat_id, g)


async def update_vote_buttons(ctx, chat_id: int, g: GameState):
    btns = []
    for s in g.vote_candidates:
        name = g.seats[s][1]
        label = f"✅ {s}. {name}" if s in getattr(g, "voted_targets", set()) else f"{s}. {name}"
        btns.append([InlineKeyboardButton(label, callback_data=f"vote_{s}")])

    if g.vote_stage == "initial_vote":
        btns.append([InlineKeyboardButton("🧹 پاک کردن رأی‌گیری", callback_data="clear_vote_initial")])
        btns.extend(_autovote_row(g, "initial_vote"))
        btns.append([InlineKeyboardButton("✅ پایان رأی‌گیری", callback_data="vote_done_initial")])
        btns.append([InlineKeyboardButton("⬅️ بازگشت", callback_data="back_vote_init")])
    elif g.vote_stage == "final":
        btns.append([InlineKeyboardButton("🧹 پاک کردن رأی‌گیری", callback_data="clear_vote_final")])
        btns.extend(_autovote_row(g, "final"))
        btns.append([InlineKeyboardButton("✅ پایان رأی‌گیری", callback_data="vote_done_final")])
        btns.append([InlineKeyboardButton("⬅️ بازگشت", callback_data="back_vote_final")])

    try:
        await ctx.bot.edit_message_reply_markup(
            chat_id=chat_id,
            message_id=g.vote_msg_id,  # 📌 فقط روی پیام دکمه‌های اصلی
            reply_markup=InlineKeyboardMarkup(btns)
        )
    except:
        pass


async def handle_vote(ctx, chat_id: int, g: GameState, target_seat: int,
                      refresh_buttons: bool = True):
    g.current_vote_target = target_seat

    g.vote_collecting = True
    g.votes_cast.setdefault(target_seat, set())
    g.vote_logs.setdefault(target_seat, [])

    if not hasattr(g, "vote_order"):
        g.vote_order = []
    g.vote_order.append(target_seat)

    if not hasattr(g, "vote_cleanup_ids"):
        g.vote_cleanup_ids = []

    # 🎙 صدای «رأی‌گیری برای صندلیِ N» در _run_auto_vote و «قبل از» مکثِ ۳ ثانیه
    #    پخش می‌شود، نه اینجا — تا جمله در همان مکث گفته شود و با پیام تمام شده باشد.
    msg = await ctx.bot.send_message(
        chat_id,
        f"⏳ رأی‌گیری برای <b>{target_seat}. {g.seats[target_seat][1]}</b>",
        parse_mode="HTML"
    )
    g.vote_cleanup_ids.append(msg.message_id)

    # ⏱ ملاک زمان = ساعتِ سرور تلگرام (msg.date) — سقفِ موقت تا ارسال «تمام»
    start_time = msg.date.timestamp()
    # 🕰 پنجره‌ی قبلی را نگه دار تا رأی‌های دیررسیده‌ی دورِ قبل گم نشوند
    _old = getattr(g, "vote_window", None)
    _old_b = getattr(g, "vote_bounds", None)
    if _old:
        _os, _oe, _ot = _old
        if _oe > start_time:
            _oe = start_time   # سقفِ بازِ قبلی با شروعِ دورِ جدید بسته می‌شود
        g.vote_prev_window = (_os, _oe, _ot)
        if _old_b:
            g.vote_prev_bounds = (_old_b[0], _old_b[1] or msg.message_id)
        else:
            g.vote_prev_bounds = None
    g.vote_window = (start_time, start_time + 30.0, target_seat)
    g.vote_bounds = (msg.message_id, None)
    store.save()

    await asyncio.sleep(4)

    g.vote_collecting = False
    end_msg = await ctx.bot.send_message(chat_id, "🛑 تمام", parse_mode="HTML")

    # ⏱ بستنِ پنجره با ساعتِ واقعیِ پیامِ «تمام» — رأی‌های دیررسیده ولی به‌موقع‌فرستاده هنوز شمرده می‌شوند
    end_real = end_msg.date.timestamp()
    g.vote_window = (start_time, end_real, target_seat)
    g.vote_bounds = (g.vote_bounds[0] if g.vote_bounds else None, end_msg.message_id)

    # ✂️ هرسِ نهایی: رأی‌هایی که در شکافِ کوتاهِ قبل از ثبتِ «تمام» با سقفِ موقت قبول شده‌اند
    #     ولی ساعتشان واقعاً بعد از «تمام» است، حذف می‌شوند (علتِ رأی‌های ۴-۵ ثانیه‌ای)
    dur = end_real - start_time
    logs = (g.vote_logs or {}).get(target_seat, [])
    removed = [(u, rel) for (u, rel) in logs if rel > dur + 0.001]
    if removed:
        g.vote_logs[target_seat] = [(u, rel) for (u, rel) in logs if rel <= dur + 0.001]
        for u, _r in removed:
            (g.votes_cast.get(target_seat) or set()).discard(u)
    store.save()

    if g.vote_stage == "initial_vote":
        g.last_vote_msg_id_initial = end_msg.message_id
    elif g.vote_stage == "final":
        g.last_vote_msg_id_final = end_msg.message_id

    g.voted_targets.add(target_seat)
    # ⏱ در رأی‌گیریِ اتومات کیبورد هر دور به‌روز نمی‌شود — یک درخواستِ کمتر
    # در هر نوبت یعنی تلگرام دیرتر محدودمان می‌کند و پیام‌ها عقب نمی‌افتند
    if refresh_buttons:
        await update_vote_buttons(ctx, chat_id, g)
    store.save()









# ─── تایمر انقضای انتظار تغییر نام ──────────────────────────────
async def _expire_name_prompt(ctx, chat_id: int, uid: int, seat_no: int,
                              prompt_msg_id: int | None, token: float):
    """اگر تا ۶۰ ثانیه نام جدید دریافت نشد، انتظار را لغو و پیام درخواست را پاک می‌کند."""
    await asyncio.sleep(60)
    g = gs(chat_id)
    # فقط اگر هنوز منتظر همین درخواست هستیم لغو کن (کاربر دوباره کلیک نکرده باشد)
    if g.waiting_name.get(uid) != seat_no:
        return
    if getattr(g, "waiting_name_token", {}).get(uid) != token:
        return

    g.waiting_name.pop(uid, None)
    if isinstance(getattr(g, "waiting_name_token", None), dict):
        g.waiting_name_token.pop(uid, None)
    store.save()

    if prompt_msg_id:
        try:
            await ctx.bot.delete_message(chat_id=chat_id, message_id=prompt_msg_id)
        except Exception:
            pass


def _start_name_wait(ctx, chat_id: int, g: GameState, uid: int,
                     seat_no: int, prompt_msg):
    """انتظار تغییر نام را با یک تایمر ۶۰ ثانیه‌ای ثبت می‌کند."""
    g.waiting_name[uid] = seat_no
    if not isinstance(getattr(g, "waiting_name_token", None), dict):
        g.waiting_name_token = {}
    token = datetime.now().timestamp()
    g.waiting_name_token[uid] = token
    store.save()
    prompt_id = getattr(prompt_msg, "message_id", None)
    asyncio.create_task(
        _expire_name_prompt(ctx, chat_id, uid, seat_no, prompt_id, token)
    )


async def _send_god_rating_prompts(ctx, g, group_title=None):
    """🎩 بعد از بازی: از همهٔ بازیکنانِ لیست بپرس به گاد چه امتیازی می‌دهند."""
    god = getattr(g, "god_id", None)
    if not god or not g.seats:
        return 0
    token = str(int(datetime.now(timezone.utc).timestamp()))[-7:]
    gname = escape(getattr(g, "god_name", None) or "گاد", quote=False)
    kb = InlineKeyboardMarkup([[
        InlineKeyboardButton(str(n), callback_data=f"grate_{god}_{token}_{n}")
        for n in (1, 2, 3, 4, 5)
    ]])
    txt = (f"🎩 <b>بازی تمام شد</b>"
           + (f" — {escape(group_title, quote=False)}" if group_title else "")
           + f"\n\nبه راویِ این بازی، <b>{gname}</b>، چه امتیازی می‌دهی؟\n"
             f"<i>۱ = خیلی ضعیف   …   ۵ = عالی</i>")
    prompts = []
    for s in sorted(g.seats):
        uid, _n = g.seats[s]
        if uid == god:
            continue   # گاد به خودش رأی نمی‌دهد
        try:
            m = await ctx.bot.send_message(uid, txt, parse_mode="HTML", reply_markup=kb)
            prompts.append((uid, m.message_id))
        except Exception:
            pass   # پیوی بسته — بی‌خیال
    if prompts:
        asyncio.create_task(_expire_god_rating(ctx, prompts, token))
    return len(prompts)


async def _expire_god_rating(ctx, prompts, token, delay=3600):
    """⏳ بعد از ۱ ساعت، پیامِ امتیازدهیِ بی‌پاسخ از پیویِ بازیکن پاک می‌شود."""
    try:
        await asyncio.sleep(delay)
    except Exception:
        return
    seen = getattr(store, "god_rate_done", None) or set()
    for uid, mid in prompts:
        if f"{uid}_{token}" in seen:
            continue   # رأی داده — دست نزن
        try:
            await ctx.bot.delete_message(chat_id=uid, message_id=mid)
        except Exception:
            try:   # اگر پاک نشد، دست‌کم دکمه‌ها را بردار
                await ctx.bot.edit_message_text(
                    chat_id=uid, message_id=mid,
                    text="⏰ مهلتِ امتیازدهی به گاد تمام شد.")
            except Exception:
                pass


async def handle_god_rating_callback(update, ctx):
    """🎩 ثبتِ رأیِ بازیکن به گاد (۱ تا ۵)."""
    q = update.callback_query
    try:
        _, god_s, token, score_s = (q.data or "").split("_", 3)
        god_uid, score = int(god_s), int(score_s)
    except Exception:
        await safe_q_answer(q, "دکمه معتبر نیست.", show_alert=True)
        return
    if not (1 <= score <= 5):
        await safe_q_answer(q, "امتیاز باید بین ۱ تا ۵ باشد.", show_alert=True)
        return

    rater = q.from_user.id
    if rater == god_uid:
        await safe_q_answer(q, "به خودت که نمی‌شود رأی داد 🙂", show_alert=True)
        return

    seen = getattr(store, "god_rate_done", None)
    if not isinstance(seen, set):
        seen = set()
        store.god_rate_done = seen
    key = f"{rater}_{token}"
    if key in seen:
        await safe_q_answer(q, "قبلاً رأی داده‌ای.", show_alert=True)
        return

    await safe_q_answer(q)
    ok = record_god_rating(god_uid, score)
    if not ok:
        try:
            await ctx.bot.edit_message_text(
                chat_id=rater, message_id=q.message.message_id,
                text="⚠️ ثبتِ رأی موقتاً ممکن نشد؛ کمی بعد دوباره امتحان کن.")
        except Exception:
            pass
        return

    seen.add(key)
    if len(seen) > 5000:      # جلوگیری از رشدِ بی‌پایان
        store.god_rate_done = set(list(seen)[-2000:])
    store.save()
    try:
        await ctx.bot.edit_message_text(
            chat_id=rater, message_id=q.message.message_id,
            text=f"✅ رأیت ثبت شد: <b>{score}/5</b>\nممنون 🙏", parse_mode="HTML")
    except Exception:
        pass


_TEHRAN_TZ = timezone(timedelta(hours=3, minutes=30))   # 🇮🇷 ایران DST ندارد


def _teh_clock(ts=None) -> str:
    """⏰ «HH:MM» به وقتِ تهران — بدونِ ts یعنی همین الان؛ ts نامعتبر → «—»."""
    try:
        dt = (datetime.now(_TEHRAN_TZ) if ts is None
              else datetime.fromtimestamp(float(ts), _TEHRAN_TZ))
        return dt.strftime("%H:%M")
    except Exception:
        return "—"


async def announce_winner(ctx, update, g: GameState):
    chat = update.effective_chat
    group_title = chat.title or "—"
    date_str = jdatetime.date.today().strftime("%Y/%m/%d")
    scenario_name = getattr(g.scenario, "name", "—")

    # ← فقط از کش
    nums = get_event_numbers()
    key = str(chat.id)
    event_num = int(nums.get(key, 1))  # نمایش عدد فعلی

    # لینک‌دار کردن گروه
    if chat.username:
        group_link = f"<a href='https://t.me/{chat.username}'>{group_title}</a>"
    else:
        group_link = group_title

    event_title = escape(g.event_title, quote=False) if getattr(g, "event_title", None) else "رویداد مافیا"
    lines = [
        f"🎭 <b>{event_title}</b>",
        f"░⚜️🎮 گروه: {group_link}",
        f"░⚜️📅 تاریخ: {date_str}",
        f"░⚜️⏰ ساعت: "
        f"{_teh_clock(g.game_start_ts) if getattr(g, 'game_start_ts', None) else '—'}"
        f" تا {_teh_clock()}",
        f"░⚜️🎯 شماره رویداد:{event_num}",
        f"░💡🔱 راوی: <a href='tg://user?id={g.god_id}'>{g.god_name or '❓'}</a>"
        f"{medal_tag(g.god_id)}",
        f"░⚜️📃 سناریو: {scenario_name}",
        "",
        "░⚜️💫 لیست بازیکنان ⬇️",
        "",
    ]

    mafia_roles = {_nz(x) for x in load_mafia_roles()}
    indep_roles = load_indep_roles()
    indep_for_this = {_nz(x) for x in indep_roles.get(g.scenario.name, [])}

    for seat in sorted(g.seats):
        uid, name = g.seats[seat]
        role = g.assigned_roles.get(seat, "—")

        # انتخاب مارکر بر اساس نقش
        if seat in getattr(g, "negotiated_seats", set()):
            role_display = f"{role} / مافیا ساده"
            marker = "◾️"  # مذاکره‌شده → مافیا ساده
        elif getattr(g, "purchased_seat", None) == seat or getattr(g, "purchased_player", None) == seat:
            role_display = f"{role} / مافیا"
            marker = "◾️"  # خریداری شده → مافیا
        elif getattr(g, "gm_smeagol_turned", False) and _R_SMEAGOL in _nz(role):
            # 🌀 اسمیگلِ خیانت‌کرده: تنها جایی که مافیا بودنش دیده می‌شود همین لیست است
            role_display = f"{role} / مافیا"
            marker = "◾️"
        elif _nz(role) in mafia_roles:
            marker = "◾️"  # مافیا
            role_display = role
        elif (getattr(g, "seat_sides", {}) or {}).get(seat) == "مافیا":
            # 👑 نقش‌هایی که وسطِ بازی مافیا شده‌اند (مثل «رئیس مافیا»ی هانیبال)
            marker = "◾️"
            role_display = role
        elif _nz(role) in indep_for_this:
            marker = "♦️"  # مستقل
            role_display = role
                
        else:
            marker = "◽️"  # شهروند
            role_display = role

        # ⚱️ وارث در لیستِ نهایی با نامِ خودش نمایش داده می‌شود (نه نقشِ ارث‌برده)
        if _is_kapu_scenario(g) and getattr(g, "heir_seat", None) == seat:
            role_display = "وارث"

        # 🕵️ کاوربازپرس: «نقشِ قبلی / نقشِ فعلی» — هم برای مجهول، هم برای کسی که
        #    دعوت را پذیرفت و گادفادر شد (مارکر از روی نقشِ فعلی حساب شده است)
        _cvb_old = (getattr(g, "cvb_orig_roles", None) or {}).get(seat)
        if _cvb_old:
            role_display = f"{_cvb_old} / {role}"

        chaos_mark = " 🔸" if getattr(g, "chaos_selected", set()) and seat in g.chaos_selected else ""

        lines.append(
            f"░⚜️{marker}{seat}- <a href='tg://user?id={uid}'>{name}</a>"
            f"{medal_tag(uid)} ⇦ {role_display}{chaos_mark}"
        )

    lines.append("")
    result_line = f"🏆 نتیجه بازی: برد {g.winner_side}"
    if getattr(g, "clean_win", False):
        result_line += " (کلین‌شیت)"
    if getattr(g, "chaos_mode", False):
        result_line += " (کی‌آس)"
    lines.append(result_line)
    lines.append("")
    lines.append(CHANNEL_AD)

    # ✅ افزایش شماره ایونت (کش + Gist)
    nums[key] = event_num + 1
    ok = save_event_numbers(nums)
    if not ok:
        print(f"⚠️ save_event_numbers failed for chat {key}")

    # 🏅 محاسبه‌ی امتیازِ این بازی (بعد از تعیینِ برنده، قبل از ثبتِ آمار)
    #    ⛔ لیستِ زیرِ ۱۰ نفر اصلاً امتیاز ندارد — بازی/برد ثبت می‌شود ولی امتیاز صفر
    if len(g.seats or {}) < MIN_SCORED_SEATS:
        game_scores = {}
        # 🧾 در آمار «صفر» ثبت می‌شود، نه «ثبت‌نشده» — وگرنه بازیِ قدیمی حساب
        #    می‌شد و پایهٔ ۱۵+۲۵ امتیاز می‌گرفت
        stats_scores = {s: {"total": 0.0} for s in (g.seats or {})}
        try:
            await ctx.bot.send_message(
                chat.id,
                f"ℹ️ این لیست زیرِ {MIN_SCORED_SEATS} نفر بود — برای این بازی امتیازی ثبت نشد "
                f"(بازی و برد ثبت شد).")
        except Exception:
            pass
    else:
        try:
            game_scores = _score_compute(g)
        except Exception as e:
            print("⚠️ score compute error:", e)
            game_scores = {}
        stats_scores = game_scores

    # 📊 ثبت آمار برد/باخت بازیکنان در Gist (+ امتیاز کل + چکِ پایانِ فصل)
    season_msg = update_player_stats(g, mafia_roles, indep_for_this, scores=stats_scores,
                                     group_title=group_title, date_str=date_str,
                                     chat_id=chat.id, event_num=event_num)

    # ⚠️ اگر ثبتِ آمار شکست خورد، بی‌صدا رد نشو — به گاد و سازندهٔ بات خبر بده
    _serr = getattr(g, "stats_save_error", None)
    if _serr:
        _warn = ("⚠️ <b>آمارِ این بازی ثبت نشد!</b>\n"
                 f"{escape(str(_serr), quote=False)}\n"
                 f"گروه: {escape(group_title or '—', quote=False)} | تاریخ: {date_str or '—'}")
        for _to in {g.god_id, ADMIN_ID}:
            if not _to:
                continue
            try:
                await ctx.bot.send_message(_to, _warn, parse_mode="HTML")
            except Exception:
                pass

    g.phase = "ended"
    store.save()
    await voice_god.leave(chat.id)     # 🎙 پایانِ بازی → خروج از وویس‌چت

    msg = await ctx.bot.send_message(chat.id, "\n".join(lines), parse_mode="HTML")
    try:
        await ctx.bot.pin_chat_message(chat_id=chat.id, message_id=msg.message_id)
    except Exception as e:
        print("⚠️ خطا در پین کردن پیام:", e)

    # 🏁 اعلانِ پایانِ فصل و مدال‌ها در «همهٔ گروه‌ها» + پین
    if season_msg:
        await _broadcast_season_end(ctx.bot, season_msg, first_chat_id=chat.id)

    # 🌙 گزارش شب‌به‌شبِ اکت‌ها (به‌صورت متن جداگانه زیر لیست پایانی)
    night_log = getattr(g, "night_log", None)
    report = ("📜 <b>گزارش شب‌به‌شب</b>\n" + "\n".join(night_log)) if night_log else None
    if report:
        await _send_chunked(ctx.bot, chat.id, report)

    # 🏅 کارنامه‌ی امتیاز — زیرِ گزارشِ اکت‌ها
    score_text = "\n".join(_score_card_lines(g, game_scores)) if game_scores else None
    if score_text:
        try:
            await ctx.bot.send_message(chat.id, score_text, parse_mode="HTML")
        except Exception as e:
            print("⚠️ score card send error:", e)

    # 🎩 نظرسنجیِ امتیازِ گاد در پیویِ بازیکنان
    try:
        _n_rate = await _send_god_rating_prompts(ctx, g, group_title)
        _others = len([1 for s in g.seats if g.seats[s][0] != g.god_id])
        if _n_rate:
            _msg = (f"🎩 نظرسنجیِ امتیازِ گاد برای <b>{_n_rate}</b> نفر ارسال شد "
                    f"(مهلت: ۱ ساعت).")
        elif _others == 0:
            _msg = ("🎩 نظرسنجیِ امتیاز ارسال نشد: خودت تنها بازیکنِ لیست بودی و "
                    "گاد به خودش رأی نمی‌دهد.")
        else:
            _msg = (f"🎩 نظرسنجیِ امتیاز به هیچ‌کس نرسید — پیویِ هر {_others} نفر بسته است "
                    f"یا بات را استارت نکرده‌اند.")
        try:
            await ctx.bot.send_message(g.god_id, _msg, parse_mode="HTML")
        except Exception:
            pass
    except Exception as e:
        print("⚠️ god rating prompts:", e)

    # 📢 آرشیوِ همین بازی در چنل (اگر چنل تنظیم شده باشد)
    try:
        _hdr = (f"📢 <b>بازیِ تمام‌شده</b>\n"
                f"🎮 گروه: {escape(group_title or '—', quote=False)}\n"
                f"📅 {date_str} | 🎯 رویداد {event_num}\n"
                f"━━━━━━━━━━━━")
        await archive_game_to_channel(ctx.bot, _hdr, "\n".join(lines), report, score_text)
    except Exception as e:
        print("⚠️ archive to channel:", e)

    # 🎥 پایانِ ضبط: بسته می‌شود، اکانت از مایک پایین می‌آید و همهٔ پارت‌ها
    #    (بعد از اینکه تلگرام فایلِ آخر را ساخت) زیرِ همین لیست به چنل می‌روند
    try:
        voice_god.record_finish(chat.id, get_archive_channel())
    except Exception as e:
        print("⚠️ record_finish:", e)

    # 🔗 پایان بازی: پاک‌سازی اتاق مافیا (حذف همه + باطل‌کردن لینک)
    await _room_cleanup(ctx, g)




def _apply_size_and_scenario(g: GameState, new_size: int, new_scenario: Scenario):
    # اگر کم می‌کنیم: صندلی‌های بالای ظرفیت جدید حذف شوند
    if new_size < g.max_seats:
        for seat in sorted(list(g.seats.keys())):
            if seat > new_size:
                g.seats.pop(seat, None)
        # خط‌خورده‌ها و دفاع و… هم تمیز شوند
        g.striked = {s for s in g.striked if s <= new_size}
        g.defense_seats = [s for s in g.defense_seats if s <= new_size]
    # اگر زیاد می‌کنیم: فقط ظرفیت بالا برود؛ نفرات قبلی سر جایشان
    g.max_seats = new_size
    g.scenario = new_scenario
    g.last_roles_scenario_name = None  # تا لیست نقش‌ها دوباره چاپ شود
    # هرچیزی که مربوط به نقش‌های قبلی بوده پاک؛ چون هنوز بازی شروع نشده
    g.assigned_roles = {}
    g.phase = "idle"
    g.awaiting_scenario = False
    # فلگ‌های مربوط به تغییر سناریو
    g.awaiting_scenario_change = False
    g.pending_size = None

def _scenario_sizes_available() -> list[int]:
    sizes = sorted({sum(s.roles.values()) for s in store.scenarios})
    return sizes

def kb_choose_sizes() -> InlineKeyboardMarkup:
    sizes = _scenario_sizes_available()
    rows, row = [], []
    for i, n in enumerate(sizes, 1):
        row.append(InlineKeyboardButton(str(n), callback_data=f"scsize_{n}"))
        if i % 4 == 0:
            rows.append(row); row = []
    if row:
        rows.append(row)
    rows.append([InlineKeyboardButton("↩️ بازگشت", callback_data="scchange_back")])
    return InlineKeyboardMarkup(rows)

def kb_choose_scenarios_for(size: int) -> InlineKeyboardMarkup:
    options = [s for s in store.scenarios if sum(s.roles.values()) == size]
    # هر سناریو یک دکمه
    rows = [[InlineKeyboardButton(s.name, callback_data=f"scpick_{size}_{i}")]
            for i, s in enumerate(options)]
    rows.append([InlineKeyboardButton("⬅️ انتخاب ظرفیت دیگر", callback_data="scchange_again")])
    return InlineKeyboardMarkup(rows)



async def cleanup_after(ctx, chat_id: int, from_message_id: int, stop_message_id: int | None = None,
                        keep: set | None = None):
    """🧹 پاک‌کردنِ پیام‌های بینِ دو آی‌دی — به‌جز آن‌هایی که در keep آمده‌اند
    (مثلِ پیامِ «📜 لیست نقش‌های سناریو» که باید سرِ جایش بماند)."""
    keep = {int(k) for k in (keep or set()) if k}
    try:

        if stop_message_id:
            limit = stop_message_id
        else:

            limit = from_message_id + 5000

        batch = []
        for msg_id in range(from_message_id + 1, limit):
            if msg_id in keep:
                continue
            batch.append(msg_id)
            if len(batch) == 100:  # هر 100 تا
                for mid in batch:
                    try:
                        await ctx.bot.delete_message(chat_id, mid)
                    except Exception:
                        pass
                batch = []
                await asyncio.sleep(1)  # جلوگیری از FloodLimit

        # باقی‌مانده
        for mid in batch:
            try:
                await ctx.bot.delete_message(chat_id, mid)
            except Exception:
                pass

    except Exception as e:
        print(f"⚠️ cleanup_after error: {e}")




# ═════════════════════════════════════════════════════════════
#  موتور شبِ خودکار — سناریو «مذاکره»
#  گاد با /شب اکت‌گیری را شروع و با /روز تمام می‌کند.
#  بات فقط اکت‌ها را جمع و زنده به پیوی گاد گزارش می‌دهد؛
#  تصمیم نهایی مرگ‌ها با خود گاد است.
# ═════════════════════════════════════════════════════════════
NEG_SCENARIO_KEY = "مذاکر"   # تشخیص سناریو مذاکره (نرمالایز)

def _nz(s: str) -> str:
    """نرمالایز نام نقش/سناریو: یکسان‌سازی حروف عربی↔فارسی + حذف فاصله/نیم‌فاصله/کاراکترهای نامرئی."""
    s = s or ""
    # یکسان‌سازی حروف عربی به فارسی (با کدهای صریح یونیکد)
    s = (s.replace("ي", "ی")   # ي عربی → ی فارسی
           .replace("ى", "ی")  # ى الف مقصوره → ی
           .replace("ك", "ک")  # ك عربی → ک فارسی
           .replace("ة", "ه")  # ة → ه
           .replace("ۀ", "ه")) # ۀ → ه
    # حذف فاصله، نیم‌فاصله و کاراکترهای عرضِ صفر / جهت
    for ch in (" ", "‌", "​", "‍", "‎", "‏", "﻿", " "):
        s = s.replace(ch, "")
    return s.strip()

# نام نقش‌ها (نرمالایز شده)
_R_GODFATHER    = _nz("گادفادر")
_R_NEGOTIATOR   = _nz("مذاکره کننده")
_R_SIMPLE_MAFIA = _nz("مافیا ساده")
_R_ARMORED      = _nz("زره پوش")
_R_DETECTIVE    = _nz("کاراگاه")
_R_SNIPER       = _nz("تک تیرانداز")
_R_DOCTOR       = _nz("پزشک")
_R_REPORTER     = _nz("خبرنگار")
_R_CITIZEN      = {_nz("شهرساده"), _nz("شهر ساده"), _nz("شهروند ساده"), _nz("شهروند")}


def _is_neg_scenario(g) -> bool:
    return bool(getattr(g, "scenario", None)) and (_nz(NEG_SCENARIO_KEY) in _nz(g.scenario.name))

def _alive_seats(g):
    return [s for s in sorted(g.seats) if s not in (g.striked or set())]


def _game_chat_id(g):
    """آیدیِ گروهِ این بازی (برای جاهایی که فقط g در دست است، مثل اعلامِ صوتی)."""
    for cid, game in store.games.items():
        if game is g:
            return cid
    return None

def _seat_role_norm(g, seat):
    return _nz((g.assigned_roles or {}).get(seat, ""))

def _seat_of_uid(g, uid):
    for s, (u, _n) in g.seats.items():
        if u == uid:
            return s
    return None

def _role_of(g, role_norm):
    """🦷 در دنتیست، نقش‌های موتورِ تکاور نامِ دیگری دارند (گادفادر→رئیس‌مافیا و…).
    این تابع نامِ واقعیِ همان نقش را در سناریوی جاری برمی‌گرداند."""
    try:
        if _DN_ALIAS and _is_dentist_scenario(g):
            return _DN_ALIAS.get(role_norm, role_norm)
    except Exception:
        pass
    return role_norm


def _find_seat_by_role(g, role_norm, alive_only=True):
    role_norm = _role_of(g, role_norm)
    seats = _alive_seats(g) if alive_only else sorted(g.seats)
    for s in seats:
        if _seat_role_norm(g, s) == role_norm:
            return s
    return None

def _mafia_role_set(g):
    """نقش‌های تیم مافیا بسته به سناریو."""
    if _is_baazpors_scenario(g):
        return (_R_GODFATHER, _R_NATO, _R_SHIAD, _R_SIMPLE_MAFIA)
    if _is_nemayande_scenario(g):
        return (_R_DON, _R_HACKER, _R_YAGHI)
    if _is_dentist_scenario(g):
        return (_R_DN_BOSS, _R_DN_CHURCH, _R_DN_DEXTER)
    if _is_takavar_scenario(g):
        return (_R_GODFATHER, _R_HOSTAGE, _R_NATO)
    if _is_kapu_scenario(g):
        return (_R_DON, _R_EXECUTIONER, _R_WITCH)
    if _is_gamer_scenario(g):
        # 🔪 دکستر عضوِ واقعیِ تیمِ مافیاست (در ۱۲نفره). اسمیگل حتی بعدِ خیانت
        #    اینجا نمی‌آید — «مافیای خاموش» است و در شمارش شهروند حساب می‌شود.
        #    🎃 مترسک (۱۷نفره) عضوِ واقعیِ تیم است، فقط لینکِ اتاق نمی‌گیرد.
        return (_R_DONC, _R_TWOFACE, _R_MORIARTY, _R_DEXTER, _R_GM_SCARECROW)
    if _is_shahname_scenario(g):
        return _sh_dark_role_norms(g)
    if _is_mythic_scenario(g):
        return _MY_MAFIA
    if _is_hanibal_scenario(g):
        return _HB_MAFIA
    if _is_classic_scenario(g):
        return (_R_DON, _R_CL_TERROR, _R_SIMPLE_MAFIA)
    return (_R_GODFATHER, _R_NEGOTIATOR, _R_SIMPLE_MAFIA)

def _mafia_seats(g, alive_only=False):
    """صندلی‌های تیم مافیا (شامل جذب‌شده‌های مذاکره/یاکوزایی/خریداری)."""
    mafia_roles = _mafia_role_set(g)
    out = set()
    for s in g.seats:
        if _seat_role_norm(g, s) in mafia_roles:
            out.add(s)
    out |= set(g.negotiated_seats or set())
    for _bp in (getattr(g, "purchased_player", None), getattr(g, "purchased_seat", None)):
        if _bp and _bp in g.seats:
            out.add(_bp)
    if alive_only:
        out = {s for s in out if s not in (g.striked or set())}
    return out

def _dead_nonneg_mafia_exists(g) -> bool:
    """آیا یک مافیای غیرِ مذاکره‌کننده مرده است؟ (شرط فعال‌شدن مذاکره)
    🦷 دنتیست: رفتنِ رئیس‌مافیا یا دکستر → چرچیل حقِ مذاکره پیدا می‌کند."""
    if _is_dentist_scenario(g):
        for s in g.seats:
            if (s in (g.striked or set())
                    and _seat_role_norm(g, s) in (_R_DN_BOSS, _R_DN_DEXTER)):
                return True
        return False
    for s in g.seats:
        if s in (g.striked or set()) and _seat_role_norm(g, s) in (_R_GODFATHER, _R_SIMPLE_MAFIA):
            return True
    return False

def _doctor_targets(g, doc_seat):
    # 🎮 گیمر ۱۷: مثلِ بقیهٔ اکت‌های محدود، سیوِ خودی هم یکی بیشتر می‌شود
    _cap = _gm_lim(g, 2) if _is_gamer_scenario(g) else 2
    out = []
    for s in _alive_seats(g):
        if s == doc_seat and (g.doctor_self_saves or 0) >= _cap:
            continue  # سقف سیو خودی
        out.append(s)
    return out

def _detective_positive(g, seat) -> bool:
    rn = _seat_role_norm(g, seat)
    if rn in (_R_SIMPLE_MAFIA, _R_NEGOTIATOR):
        return True
    # فقط مذاکره‌ی «نشسته» (موفق) — هدفِ مذاکره‌ی ناموفق شهروند مانده و منفی است
    if seat in (g.negotiated_seats or set()):
        return True
    return False  # گادفادر برای کاراگاه منفی است

def _reporter_positive(g, seat) -> bool:
    # خبرنگار فقط روی فردِ مذاکره‌شده‌ی «موفق» مثبت می‌گیرد؛ بقیه (حتی مافیا) منفی
    return seat in (g.negotiated_seats or set())


def _kb_night_seats(seats, g, prefix, selected=None, confirm_cb=None):
    """کیبورد انتخاب صندلی برای اکت شب."""
    if selected is None:
        sel = set()
    elif isinstance(selected, (set, list, tuple)):
        sel = set(selected)
    else:
        sel = {selected}
    rows = []
    for s in seats:
        _u, name = g.seats[s]
        mark = "✅ " if s in sel else ""
        rows.append([InlineKeyboardButton(f"{mark}{s} {name}", callback_data=f"{prefix}{s}")])
    if confirm_cb:
        rows.append([InlineKeyboardButton("✅ تأیید", callback_data=confirm_cb)])
    return InlineKeyboardMarkup(rows)


def _kb_add_back(kb, back_cb):
    """↩️ افزودنِ دکمه‌ی بازگشت به انتهای یک کیبورد (تا قبل از تأیید)."""
    rows = list(kb.inline_keyboard) + [[InlineKeyboardButton("↩️ بازگشت", callback_data=back_cb)]]
    return InlineKeyboardMarkup(rows)


# ═══════════ 🎛 اکتِ دستیِ گاد — جانشینیِ پیویِ بازیکن ═══════════
_GOD_ONLY_CB = ("kpd_", "kpg_", "kpe_", "kpc_", "nemd_", "nemc_", "nrep_", "bzd_",
                "nkick_", "nburn_", "gact_", "tmr_", "buylink_", "tk_shield_", "kpv_",
                "endq_", "shd_", "mlk_")


def _kb_dump(kb):
    """کیبوردِ اینلاین → داده‌ی ساده (قابلِ ذخیره در state)."""
    if not kb:
        return None
    try:
        return [[(b.text, b.callback_data) for b in row if b.callback_data]
                for row in kb.inline_keyboard]
    except Exception:
        return None


def _kb_load(dump):
    """داده‌ی ساده → کیبوردِ اینلاین."""
    if not dump:
        return None
    try:
        rows = [[InlineKeyboardButton(t, callback_data=c) for t, c in row] for row in dump if row]
        return InlineKeyboardMarkup(rows) if rows else None
    except Exception:
        return None


def _god_impersonating(uid):
    """اگر این آیدی گادی است که در حالِ اکتِ دستی است → (بازی، صندلی، آیدیِ بازیکن)."""
    try:
        for _g in store.games.values():
            s = getattr(_g, "god_acting_as", None)
            if _g.god_id == uid and s and s in _g.seats:
                return _g, s, _g.seats[s][0]
    except Exception:
        pass
    return None, None, None


def _q_uid(q):
    """آیدیِ مؤثرِ کال‌بک — وقتی گاد «اکتِ دستی» می‌زند، به‌جای خودِ بازیکن حساب می‌شود.
    دکمه‌های مخصوصِ گاد از این قاعده مستثنا هستند."""
    u = q.from_user.id
    d = q.data or ""
    if d.startswith(_GOD_ONLY_CB):
        return u
    _g, _s, puid = _god_impersonating(u)
    return puid if puid else u


def _pm_target(uid):
    """اگر گاد دارد به‌جای این بازیکن اکت می‌زند، پیام‌هایش باید به پیویِ گاد برود."""
    try:
        for _g in store.games.values():
            s = getattr(_g, "god_acting_as", None)
            if s and s in _g.seats and _g.seats[s][0] == uid:
                return _g.god_id
    except Exception:
        pass
    return uid


async def _safe_pm(ctx, uid, text, kb=None):
    # 📥 پرامپت را همیشه کش کن — حتی اگر ارسال نشود (گوشی خاموش/پیوی بسته)،
    #    تا گاد بتواند با «اکتِ دستی» همین سؤال را جای بازیکن جواب بدهد
    try:
        for _g in store.games.values():
            if any(u == uid for u, _n in _g.seats.values()):
                _g.night_prompt_cache[uid] = (text, _kb_dump(kb))
                break
    except Exception:
        pass
    # 🔥 اکتِ سوخته: مثل بازیکنِ با پیویِ بسته رفتار می‌شود — هیچ پرامپتی نمی‌گیرد
    try:
        for _g in store.games.values():
            if uid in (getattr(_g, "night_burned_uids", set()) or set()):
                return None
    except Exception:
        pass
    try:
        return await ctx.bot.send_message(_pm_target(uid), text, reply_markup=kb)
    except Exception:
        return None


async def _report_unreachable(ctx, chat_id, g):
    """بازیکن‌هایی که بات را استارت نکرده‌اند (نمی‌شود دکمه فرستاد).
    📩 گزارش فقط به پیویِ گاد می‌رود، نه وسطِ گروه."""
    unreachable = []
    for s in _alive_seats(g):
        uid, name = g.seats[s]
        try:
            await ctx.bot.send_chat_action(uid, "typing")
        except Exception:
            unreachable.append(f"{s}. {name}")
    if unreachable:
        txt = ("⚠️ <b>این بازیکن‌ها بات را استارت نکرده‌اند</b> و دکمهٔ اکت دریافت نمی‌کنند:\n"
               + "\n".join(unreachable)
               + "\n\nاز آن‌ها بخواه بات را در پیوی باز کنند و /start بزنند؛ "
                 "به‌محضِ استارت، نقش (و لینکِ اتاق) خودکار برایشان می‌رود.")
        await _night_report(ctx, g, txt)
    return unreachable

async def _edit_pm(ctx, uid, msg_id, text, kb):
    try:
        for _g in store.games.values():
            if any(u == uid for u, _n in _g.seats.values()):
                _g.night_prompt_cache[uid] = (text, _kb_dump(kb))
                break
    except Exception:
        pass
    try:
        await ctx.bot.edit_message_text(chat_id=_pm_target(uid), message_id=msg_id,
                                        text=text, reply_markup=kb)
    except Exception:
        pass

# ═════════════════════════════════════════════════════════════
#  ⏪ «اکت مجدد» — مهلتِ اشتباه، در همهٔ اکت‌های شبِ همهٔ سناریوها
#  بعد از ثبتِ اکت، به‌جای متنِ نهایی یک پیامِ خنثی + دکمهٔ «🔄 اکت مجدد» می‌آید
#  و ۷ ثانیه صبر می‌شود:
#    • نزد → دکمه می‌رود، متنِ واقعی (حتی نتیجهٔ استعلام) نشان داده می‌شود و
#      تازه بعدش گزارشِ گاد و رساندنِ اثرِ اکت به بقیه انجام می‌شود.
#    • زد   → همان پرامپتِ قبلی با دکمه‌هایش برمی‌گردد تا دوباره انتخاب کند و
#      جریانِ این اکت (گزارش/اثر) اصلاً اجرا نمی‌شود.
# ═════════════════════════════════════════════════════════════
REDO_WINDOW_SEC = 7
import contextvars
_ACT_UID = contextvars.ContextVar("act_uid", default=None)   # صاحبِ اکتِ در دستِ پردازش
_REDO_WAIT: dict[int, dict] = {}                             # uid → {"evt", "token"}


_ACT_OUTBOX: dict[int, list] = {}    # uid → پیام‌هایی که تا پایانِ مهلت صبر می‌کنند
_ACT_SNAP: dict[int, tuple] = {}     # uid → (بازی، night_done، مقادیرِ سادهٔ قبل از اکت)

# 🚫 فیلدهایی که هرگز برنمی‌گردند — چون بازیکن‌های دیگر هم هم‌زمان دستشان می‌زنند
_SNAP_SKIP = {"night_pm_msgs", "night_prompt_cache", "night_sel", "night_doc_sel",
              "seats", "user_names", "last_snapshot", "score_events"}


def _act_snapshot(g):
    """📸 مقادیرِ سادهٔ وضعیت، درست قبل از اجرای اکت (برای برگرداندن در «اکت مجدد»)."""
    try:
        return {k: v for k, v in vars(g).items()
                if k not in _SNAP_SKIP and isinstance(v, (int, float, str, bool, type(None)))}
    except Exception:
        return {}


def _act_diff(g, snap_done, snap_vals):
    """🔍 دقیقاً چیزی که «همین اکت» عوض کرد — همان لحظهٔ ثبت حساب می‌شود، نه بعدتر،
    تا اکتِ بازیکنِ دیگری که وسطِ مهلت قطعی می‌شود قاطی نشود."""
    added = set(getattr(g, "night_done", set()) or set()) - set(snap_done or set())
    now = _act_snapshot(g)
    vals = {k: v for k, v in (snap_vals or {}).items()
            if k in now and now[k] != v}
    return added, vals


def _act_restore(g, own_added, own_vals):
    """⏪ پس‌گرفتنِ همان تغییرات — کارِ بقیه دست‌نخورده می‌ماند."""
    try:
        if own_added:
            g.night_done = (getattr(g, "night_done", set()) or set()) - own_added
        for k, old in (own_vals or {}).items():
            setattr(g, k, old)
        store.save()
    except Exception as e:
        print("⚠️ act restore:", e)


class _ActRedo(Exception):
    """بازیکن «اکت مجدد» زد — بقیهٔ جریانِ این اکت نباید اجرا شود."""


def _act_defer(fn, *a, **k) -> bool:
    """📦 اگر وسطِ اکتِ یک بازیکن هستیم، این پیام تا بسته‌شدنِ مهلتِ تصحیح صبر کند.
    (مثلاً اعلامِ شات در اتاقِ مافیا نباید قبل از قطعی‌شدنِ اکت برود)"""
    u = _ACT_UID.get()
    if u is None:
        return False
    _ACT_OUTBOX.setdefault(u, []).append((fn, a, k))
    return True


async def _act_flush(uid):
    """📤 فرستادنِ پیام‌های معوقِ این اکت (به همان ترتیبِ اصلی)."""
    for fn, a, k in _ACT_OUTBOX.pop(uid, []) or []:
        try:
            await fn(*a, **k)
        except Exception as e:
            print("⚠️ act flush:", e)


def _act_drop(uid):
    """🗑 اکت پس گرفته شد → پیام‌های معوقش اصلاً فرستاده نمی‌شوند."""
    _ACT_OUTBOX.pop(uid, None)


async def _redo_window(ctx, g, uid, msg_id, prompt) -> bool:
    """پنجرهٔ ۷ ثانیه‌ایِ تصحیح. True یعنی زد و اکت باید از نو گرفته شود."""
    token = f"{uid}-{msg_id}-{int(time.time() * 1000) % 1000000}"
    evt = asyncio.Event()
    _REDO_WAIT[uid] = {"evt": evt, "token": token}
    # 📸 عکسِ قبل از اکت را _run_night_act گرفته؛ اگر نبود، همین حالا
    _sg, snap_done, snap_vals = _ACT_SNAP.get(uid) or (None, None, None)
    if snap_done is None:
        snap_done = set(getattr(g, "night_done", set()) or set())
        snap_vals = _act_snapshot(g)
    own_added, own_vals = _act_diff(g, snap_done, snap_vals)   # 🔍 سهمِ همین اکت
    kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔄 اکت مجدد", callback_data=f"redo_{token}")]])
    try:
        await ctx.bot.edit_message_text(
            chat_id=_pm_target(uid), message_id=msg_id,
            text=f"✅ اکتت ثبت شد.\n⏳ اگر اشتباه زدی، تا {REDO_WINDOW_SEC} ثانیه «اکت مجدد» را بزن.",
            reply_markup=kb)
    except Exception:
        _REDO_WAIT.pop(uid, None)
        return False
    pressed = False
    try:
        await asyncio.wait_for(evt.wait(), timeout=REDO_WINDOW_SEC)
        pressed = True
    except asyncio.TimeoutError:
        pass
    except Exception:
        pass
    finally:
        if (_REDO_WAIT.get(uid) or {}).get("token") == token:
            _REDO_WAIT.pop(uid, None)
    if not pressed:
        return False
    # ⏪ برگرداندنِ وضعیت و نمایشِ دوبارهٔ همان پرامپت
    _act_restore(g, own_added, own_vals)
    await _edit_pm(ctx, uid, msg_id, prompt[0], _kb_load(prompt[1]))
    return True


async def handle_redo_callback(update, ctx):
    """🔄 دکمهٔ «اکت مجدد» — فقط پنجرهٔ باز را بیدار می‌کند (تطبیق با توکن،
    تا در «اکتِ دستیِ گاد» هم که پیام در پیویِ گاد است درست کار کند)."""
    q = update.callback_query
    await safe_q_answer(q)
    tok = (q.data or "")[len("redo_"):]
    for _u, st in list(_REDO_WAIT.items()):
        if st.get("token") == tok:
            try:
                st["evt"].set()
            except Exception:
                pass
            break


async def _close_pm(ctx, uid, msg_id, text):
    """ویرایش پیام به متن نهایی و حذف دکمه‌ها (تا نتوانند نظرشان را عوض کنند)."""
    target = _pm_target(uid)
    # ⏪ مهلتِ «اکت مجدد» — فقط برای صاحبِ همین اکت، و فقط وقتی پرامپتِ دکمه‌داری
    #    باز بوده (پس بستن‌های خودکار/پیام‌های بی‌دکمه دست‌نخورده می‌مانند)
    if msg_id and _ACT_UID.get() == uid:
        _gr, _prompt = None, None
        try:
            for _g in store.games.values():
                if any(u == uid for u, _n in _g.seats.values()):
                    _gr = _g
                    _prompt = (_g.night_prompt_cache or {}).get(uid)
                    break
        except Exception:
            _gr = None
        if (_gr is not None and _prompt and _kb_load(_prompt[1]) is not None
                and (getattr(_gr, "night_active", False)
                     or getattr(_gr, "maarefe_active", False))):
            _redone = await _redo_window(ctx, _gr, uid, msg_id, _prompt)
            _ACT_UID.set(None)      # مهلت تمام شد → از این به بعد همه‌چیز فوری
            if _redone:
                _act_drop(uid)
                raise _ActRedo()
            _pending_flush = uid    # بعد از نوشتنِ متنِ نهایی، معوق‌ها می‌روند
        else:
            _pending_flush = None
    else:
        _pending_flush = None
    try:
        for _g in store.games.values():
            if any(u == uid for u, _n in _g.seats.values()):
                _g.night_prompt_cache.pop(uid, None)   # اکت تمام شد → دیگر پرامپتی نمانده
                # 🎛 اکتِ دستی با تمام‌شدنِ همین اکت خودکار بسته می‌شود،
                #    وگرنه بقیه‌ی پیام‌های این بازیکن هم به پیویِ گاد می‌رفت
                s = getattr(_g, "god_acting_as", None)
                if s and s in _g.seats and _g.seats[s][0] == uid:
                    _g.god_acting_as = None
                break
    except Exception:
        pass
    try:
        await ctx.bot.edit_message_text(chat_id=target, message_id=msg_id,
                                        text=text, reply_markup=None)
    except Exception:
        pass
    # 📤 اکت قطعی شد → پیام‌هایی که منتظرِ پایانِ مهلت بودند (اتاقِ مافیا) می‌روند
    if _pending_flush is not None:
        await _act_flush(_pending_flush)

def _side_secret(g) -> bool:
    """🔒 سناریوهایی که «استعلام وضعیت» ندارند (میتیک، کلاسیک، کلاسیک‌دن):
    در این‌ها سایدِ کسی که کیک می‌شود هم در گروه خوانده نمی‌شود."""
    try:
        return bool(_is_mythic_scenario(g) or _is_classic_scenario(g))
    except Exception:
        return False


def _room_who(g, seat) -> str:
    """«۵. اسم» برای پیام‌های اتاقِ مافیا."""
    if seat is None or seat not in (getattr(g, "seats", {}) or {}):
        return "؟"
    return f"{seat}. {escape(g.seats[seat][1], quote=False)}"


def _room_outsider(g, seat) -> bool:
    """🚫 مافیایی که عضوِ اتاق نیست (گروگان‌گیر، تروریستِ میتیک، مترسکِ لینک‌نشده، …).
    اکتِ او هرگز نباید در اتاقِ مافیا اعلام شود."""
    if seat is None:
        return False
    try:
        return seat not in set(_mafia_room_seats(g))
    except Exception:
        return False


async def _room_note(ctx, g, text, actor=None):
    """📣 اعلامِ یک اکتِ مافیا در اتاقِ چتِ تیم — تا فقط خودِ اکت‌زن نداند.
    اگر اتاقی تعریف نشده باشد بی‌صدا رد می‌شود.
    🚫 اگر actor داده شود و او عضوِ اتاق نباشد، اصلاً اعلام نمی‌شود.
    ⏪ وسطِ یک اکت، تا پایانِ مهلتِ «اکت مجدد» صبر می‌کند (اگر تصحیح شد، اصلاً نمی‌رود)."""
    rid = getattr(g, "mafia_room_id", None)
    if not rid or _room_outsider(g, actor):
        return
    if _act_defer(_room_note_send, ctx, g, text):
        return
    await _room_note_send(ctx, g, text)


async def _room_note_send(ctx, g, text):
    rid = getattr(g, "mafia_room_id", None)
    if not rid:
        return
    try:
        await ctx.bot.send_message(rid, text, parse_mode="HTML")
    except Exception as e:
        print("⚠️ room note:", e)


async def _room_announce_shot(ctx, g, seat, extra="", actor=None):
    """🔫 اعلامِ هدفِ شات در اتاقِ چتِ مافیا — تا بقیهٔ تیم هم بدانند رئیس چه کسی را زد.
    (در همهٔ سناریوها؛ اگر اتاقی تعریف نشده باشد بی‌صدا رد می‌شود.)
    🚫 اگر شلیک‌کننده عضوِ اتاق نباشد، چیزی اعلام نمی‌شود."""
    rid = getattr(g, "mafia_room_id", None)
    if not rid or seat not in (getattr(g, "seats", {}) or {}) or _room_outsider(g, actor):
        return
    if _act_defer(_room_shot_send, ctx, g, seat, extra):
        return
    await _room_shot_send(ctx, g, seat, extra)


async def _room_shot_send(ctx, g, seat, extra=""):
    rid = getattr(g, "mafia_room_id", None)
    if not rid or seat not in (getattr(g, "seats", {}) or {}):
        return
    try:
        await ctx.bot.send_message(
            rid,
            f"🔫 شات: <b>{seat}. {escape(g.seats[seat][1], quote=False)}</b>{extra}",
            parse_mode="HTML")
    except Exception as e:
        print("⚠️ room shot announce:", e)


async def _night_report(ctx, g, text):
    """ثبت در لاگ پایان‌بازی + ارسال زندهٔ گزارش به پیوی گاد."""
    g.night_log.append(text)
    store.save()
    try:
        await ctx.bot.send_message(g.god_id, text, parse_mode="HTML")
    except Exception:
        pass


def _night_all_done(g) -> bool:
    """آیا همهٔ اکت‌های موردانتظارِ امشب انجام شده؟ (پویا بر اساس نقش‌های زنده و شرایط)"""
    d = g.night_done or set()
    def alive(r):
        return _find_seat_by_role(g, r) is not None

    if _is_takavar_scenario(g):
        if "gunman" not in d:
            return False
        if _is_dentist_scenario(g):
            # 🦷 اسنایپر و دنتیست هم باید اکتشان را داده باشند
            need = set()
            if _find_sniper(g) is not None and not g.sniper_used:
                need.add("sniper")
            if _find_seat_by_role(g, _R_DN_DENTIST) is not None:
                need.add("dentist")
            return need <= d
        return True

    if _is_classic_scenario(g):
        if "mafia" not in d:
            return False
        need = set()
        if alive(_R_DOCTOR):
            need.add("doctor")
        if alive(_R_DETECTIVE):
            need.add("detective")
        return need <= d

    if _is_neg_scenario(g):
        if "mafia" not in d:
            return False
        need = set()
        if alive(_R_DETECTIVE):
            need.add("detective")
        if not g.night_is_negotiation and alive(_R_DOCTOR):
            need.add("doctor")
        if not g.sniper_used and _find_sniper(g) is not None:
            need.add("sniper")
        if getattr(g, "negotiation_used", False) and alive(_R_REPORTER):
            need.add("reporter")
        return need <= d

    if _is_baazpors_scenario(g):
        if not ({"mafia", "shiad"} <= d):
            return False
        need = set()
        if alive(_R_DETECTIVE):
            need.add("detective")
        if not g.night_doctor_blocked and alive(_R_DOCTOR):
            need.add("doctor")
        if not g.baazpors_used and alive(_R_BAAZPORS):
            need.add("baazpors")
        if not g.sniper_used and _find_seat_by_role(g, _R_SNIPER_BZP) is not None:
            need.add("sniper")
        return need <= d

    if _is_nemayande_scenario(g):
        if getattr(g, "night_awaiting_sacrifice", False):
            return False   # مین فعال شده و منتظر فدای دن‌مافیا هستیم
        if not ({"mafia", "hacker"} <= d):
            return False
        need = set()
        if not g.lawyer_used and _find_seat_role_sub(g, _R_LAWYER) is not None:
            need.add("lawyer")
        if alive(_R_GUARD):
            need.add("guard")
        if not g.night_doctor_blocked and alive(_R_DOCTOR):
            need.add("doctor")
        if alive(_R_GUIDE):
            need.add("guide")
        # 🔎 شهروندی که راهنمایی گرفته باید استعلامش را بگیرد — تا آن موقع شب تمام نیست
        _rec = getattr(g, "night_guide_recipient_inv", None)
        if _rec and _rec in g.seats and _rec not in (g.striked or set()):
            need.add("ginv")
        return need <= d

    if _is_kapu_scenario(g):
        if getattr(g, "poison_phase", False):
            return False
        if not ({"mafia", "witch"} <= d):
            return False
        need = set()
        if alive(_R_DETECTIVE):
            need.add("detective")
        if not g.night_doctor_blocked and alive(_R_ARMORER):
            need.add("armorer")
        if not g.attar_poison_used and alive(_R_ATTAR):
            need.add("attar")
        return need <= d

    if _is_gamer_scenario(g):
        if getattr(g, "gm_gift_pending", False) or getattr(g, "gm_james_waiting_don", False):
            return False
        if "citizens_opened" not in d:
            return False
        need = set(getattr(g, "gm_expected", set()) or set())
        if _is_gamer17(g):
            # 💎🎃 تانوس و مترسک هم باید اکتشان را داده باشند
            if _gm_thanos_seat(g) is not None:
                need.add("thanos")
            if _find_seat_by_role(g, _R_GM_SCARECROW) is not None:
                need.add("scare")
        return need <= d

    if _is_shahname_scenario(g):
        return ({"kaveh", "shadow", "mafia", "afrasiab", "simorgh",
                 "feathers", "rostam", "jamasb", "arash"} <= d)

    if _is_mythic_scenario(g):
        if "citizens_opened" not in d:
            return False
        return (getattr(g, "my_expected", set()) or set()) <= d

    if _is_hanibal_scenario(g):
        if "citizens_opened" not in d or "avenger_opened" not in d:
            return False
        return ({"hero", "shadow", "bond", "mafia",
                 "detective", "doctor", "memar", "avenger"} <= d)

    return False


async def _maybe_notify_god_done(ctx, g):
    """اگر همهٔ اکت‌ها تمام شد، یک‌بار به پیوی گاد اطلاع بده تا بداند می‌تواند /روز بزند."""
    if not getattr(g, "night_active", False):
        return
    if getattr(g, "night_god_notified", False):
        return
    if not _night_all_done(g):
        return
    g.night_god_notified = True
    store.save()
    try:
        await ctx.bot.send_message(
            g.god_id, "✅ همهٔ اکت‌های امشب انجام شد. هر وقت خواستی «/روز» را بزن.")
    except Exception:
        pass


def _is_manual_scenario(g) -> bool:
    """✋ سناریویی که موتورِ اکتِ خودکار ندارد — همه‌چیزش دستِ گاد است."""
    return not (_is_neg_scenario(g) or _is_baazpors_scenario(g) or _is_nemayande_scenario(g)
                or _is_takavar_scenario(g) or _is_kapu_scenario(g) or _is_gamer_scenario(g)
                or _is_shahname_scenario(g) or _is_mythic_scenario(g)
                or _is_hanibal_scenario(g) or _is_classic_scenario(g))


async def start_night(ctx, chat_id, g):
    is_neg = _is_neg_scenario(g)
    is_bzp = _is_baazpors_scenario(g)
    is_nem = _is_nemayande_scenario(g)
    is_tk = _is_takavar_scenario(g)
    is_kp = _is_kapu_scenario(g)
    is_gm = _is_gamer_scenario(g)
    is_sh = _is_shahname_scenario(g)
    is_my = _is_mythic_scenario(g)
    is_hb = _is_hanibal_scenario(g)
    is_cl = _is_classic_scenario(g)
    # 🌙 سناریوهای بدونِ موتورِ خودکار: شب و روز مثل همیشه برقرار است،
    #    فقط اکت‌ها به‌جای دکمه‌های بات، در پیویِ گاد گرفته می‌شوند.
    is_manual = _is_manual_scenario(g)
    # فازهای رأی‌گیریِ روز هم قابل قبول‌اند؛ فقط قبل از شروع/بعد از پایان بازی رد می‌شود
    if g.phase in ("idle", "ended", "awaiting_winner") or not getattr(g, "assigned_roles", None):
        await ctx.bot.send_message(chat_id, "⛔ ابتدا باید بازی شروع شده باشد.")
        return
    if g.night_active:
        await ctx.bot.send_message(chat_id, "🌙 شب فعال است. برای پایان «/روز» را بنویسید.")
        return
    # 🎭 وسطِ معارفه «شب» معنا ندارد — معارفه خودش شب است؛ اکت‌گیری شروع نشود
    if getattr(g, "maarefe_active", False):
        await ctx.bot.send_message(
            chat_id, "🎭 الان شبِ معارفه است و اکت‌گیری ندارد — اول «☀️ روز» را بزن تا معارفه تمام شود.")
        return
    # 🪢 تا تکلیفِ هانتر روشن نشده، شب شروع نمی‌شود — یادآوری فقط در پیویِ گاد
    #    (در گروه چیزی نوشته نشود، وگرنه نقشِ خروجی لو می‌رود)
    if getattr(g, "bzp_hunter_pending", None):
        try:
            await ctx.bot.send_message(
                g.god_id, "⏸ اول تکلیفِ هانتر را همین‌جا مشخص کن (بله/خیر)، بعد شب.")
        except Exception:
            pass
        return

    _score_day_rollover(g)   # 🏅 ریستِ پرچم‌های روزِ امتیازی
    # 🧑‍⚖️ ریستِ تصمیم/دوئلِ بازپرسی برای روزِ بعد
    g.baz_day_choice = None
    g.baz_awaiting_decision = False
    g.baz_duel_active = False
    g.baz_duel_votes = {}
    g.baz_duel_unread = set()
    # 🎩 رأی/دفاع/تروریستِ کلاسیک — با آمدنِ شب بسته می‌شود
    g.cl_vote_active = None
    g.cl_votes = {}
    g.cl_vote_unread = set()
    g.cl_vote_kb_mid = None
    g.cl_runoff_cands = []
    g.cl_runoff_fixed = []
    g.cl_runoff_need = 0
    g.cl_defense = []
    g.cl_terror_wait = None
    # 🗳 شمارشِ دنگِ نیمه‌کاره با آمدنِ شب بسته می‌شود (نتیجه‌ی ثبت‌شده می‌ماند)
    g.nem_deng_active = False
    g.nem_deng_votes = {}
    g.nem_deng_unread = set()
    # 🔫 گانِ روزِ تکاور فقط تا پایانِ همان روز اعتبار دارد
    g.tk_day_guns = {}
    g.tk_gun_aiming = None
    # 🤝 شمارشِ نیمه‌کاره‌ی معتمدِ کاپو با شب بسته می‌شود (نتیجه/معتمد/گان‌ها می‌مانند)
    g.kp_deng_active = False
    g.kp_deng_votes = {}
