# ⏱ تایمرِ فعالِ هر گروه — تا با زدنِ تایمِ جدید، قبلی لغو شود (نه اینکه موازی بشمارند)
_TIMER_TASKS: dict[int, "asyncio.Task"] = {}
_TIMER_TOKEN: dict[int, int] = {}


def _start_timer(ctx, chat: int, seconds: int) -> bool:
    """⏱ شروعِ تایمرِ تازه برای یک گروه. اگر تایمرِ قبلی در جریان بود لغو می‌شود.
    برمی‌گرداند: آیا تایمرِ قبلی‌ای لغو شد یا نه."""
    old = _TIMER_TASKS.pop(chat, None)
    replaced = old is not None and not old.done()
    if replaced:
        old.cancel()
    # 🎫 نسل جدید — حتی اگر لغو به تأخیر بیفتد، تایمرِ کهنه حقِ اعلام ندارد
    tok = _TIMER_TOKEN.get(chat, 0) + 1
    _TIMER_TOKEN[chat] = tok
    _TIMER_TASKS[chat] = asyncio.create_task(run_timer(ctx, chat, seconds, tok))
    return replaced


async def dynamic_timer(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat.id
    uid = update.effective_user.id
    g = gs(chat)

    # جلوگیری از اجرای تایمر روی پیام‌های قدیمی
    if (datetime.now(timezone.utc) - update.message.date).total_seconds() > 10:
        return  

    if uid != g.god_id:
        await update.message.reply_text("⛔ فقط گاد می‌تونه تایمر بزنه.")
        return

    cmd = update.message.text.strip().lstrip("/")
    if not cmd.endswith("s") or not cmd[:-1].isdigit():
        await update.message.reply_text("❗ دستور درست نیست. مثال: /20s")
        return

    seconds = int(cmd[:-1])
    replaced = _start_timer(ctx, chat, seconds)
    await update.message.reply_text(
        f"⏳ تایمر {seconds} ثانیه‌ای شروع شد..."
        + (" (تایمر قبلی لغو شد)" if replaced else ""))


def _timer_kb():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("۱۰", callback_data="tmr_10"),
         InlineKeyboardButton("۳۰", callback_data="tmr_30"),
         InlineKeyboardButton("۴۵", callback_data="tmr_45")],
        [InlineKeyboardButton("۶۰", callback_data="tmr_60"),
         InlineKeyboardButton("۷۵", callback_data="tmr_75"),
         InlineKeyboardButton("۹۰", callback_data="tmr_90")],
        # 🔁 پخشِ دوبارهٔ «تایم تمام شد» در وویس‌چت (وقتی کسی سرِ تایم قطع نمی‌کند)
        [InlineKeyboardButton("🔁 تکرار صدا", callback_data="tmr_repeat")],
    ])


async def run_timer(ctx, chat: int, seconds: int, token: int | None = None):
    try:
        await asyncio.sleep(seconds)
        # ⏹ اگر وسطِ شمارش تایمِ تازه‌ای زده شده، این یکی دیگر حق اعلام ندارد
        if token is not None and _TIMER_TOKEN.get(chat) != token:
            return
        # ⏰ پایانِ تایم + دکمه‌های تایمرِ بعدی (گاد دیگر تایپ نمی‌کند)
        voice_god.say(chat, "time_up")          # 🎙 هم‌زمان با متن
        await ctx.bot.send_message(chat, "⏰ تایم تمام شد", reply_markup=_timer_kb())

    except asyncio.CancelledError:
        pass   # ⏹ با تایمرِ جدید لغو شد — بی‌صدا
    except Exception as e:
        print("⚠️ run_timer error:", e)
    finally:
        try:
            if _TIMER_TASKS.get(chat) is asyncio.current_task():
                _TIMER_TASKS.pop(chat, None)
        except Exception:
            pass


async def handle_timer_callback(update, ctx):
    """⏱ دکمه‌های ریزِ تایمر زیرِ «تایم تمام شد» — فقط گاد."""
    q = update.callback_query
    uid = q.from_user.id
    chat = q.message.chat.id if q.message else None
    if chat is None:
        return
    g = gs(chat)
    if uid != g.god_id:
        await safe_q_answer(q, "⛔ فقط گادِ بازی.", show_alert=True)
        return
    # 🔁 تکرار: جملهٔ مخصوصِ تکرار را می‌گوید (اگر نبود، همان «تایم تمام شد»)
    if q.data == "tmr_repeat":
        if voice_god.ready():
            voice_god.say(chat, "time_up_again")
            await safe_q_answer(q, "🔁 دوباره گفته شد.")
        else:
            await safe_q_answer(q, "🎙 گادِ صوتی الان وصل نیست.", show_alert=True)
        return
    try:
        seconds = int(q.data.rsplit("_", 1)[1])
    except Exception:
        return
    await safe_q_answer(q)
    # دکمه‌ها از پیامِ فعلی حذف شوند (بعدِ اتمامِ تایمرِ جدید دوباره می‌آیند)
    try:
        await ctx.bot.edit_message_reply_markup(chat_id=chat, message_id=q.message.message_id,
                                                reply_markup=None)
    except Exception:
        pass
    replaced = _start_timer(ctx, chat, seconds)
    await ctx.bot.send_message(
        chat, f"⏳ تایمر {seconds} ثانیه‌ای شروع شد..."
        + (" (تایمر قبلی لغو شد)" if replaced else ""))


async def transfer_god_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat.id

    # 1) فقط در گروه‌های فعال
    if chat not in store.active_groups:
        await update.message.reply_text("⛔ این گروه هنوز فعال نشده. اول /active را بزن.")
        return

    g = gs(chat)

    # 2) فقط بعد از ساخت بازی
    if not g.max_seats or g.max_seats <= 0:
        await update.message.reply_text("⚠️ اول با /newgame <seats> بازی بساز، بعد /god بزن.")
        return

    # ✅ فقط ادمین‌های گروه یا گادِ فعلی اجازه دارند (هم خود، هم ریپلای)
    admins = await ctx.bot.get_chat_administrators(chat)
    admin_ids = {a.user.id for a in admins}
    if update.effective_user.id not in admin_ids and update.effective_user.id != g.god_id:
        await update.message.reply_text("❌ فقط ادمین‌های گروه یا گاد فعلی می‌تونن گاد رو تعیین کنن.")
        return

    # هدف: با ریپلای → آن شخص؛ بدون ریپلای → خودِ فرستنده
    if update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
    else:
        target = update.effective_user

    if g.god_id == target.id:
        await update.message.reply_text("ℹ️ همین حالا هم گاد هست.")
        return

    # ⛔ محرومیتِ کاملِ بات
    if blocked_info(target.id):
        await update.message.reply_text("⛔ این نفر از بات محروم است و نمی‌تواند گاد شود.")
        return

    # 🚫 محرومیتِ گاد شدن (بر اساس آمارِ هفتهٔ گذشته)
    _ban = god_ban_info(target.id)
    if _ban:
        if _ban.get("reason") == "abandon":
            _why = (f"هفتهٔ گذشته {_ban.get('abandons', GOD_MAX_ABANDONS)} بار "
                    f"وسطِ بازی گاد را رها کرده")
        else:
            _why = (f"میانگینِ امتیازش هفتهٔ گذشته {_ban.get('avg', '—')} از ۵ بود "
                    f"(زیرِ {int(GOD_MIN_RATING)})")
        await update.message.reply_text(
            f"⛔ <b>{escape(_ban.get('name') or target.full_name, quote=False)}</b> "
            f"این هفته حقِ گاد شدن ندارد.\n📌 دلیل: {_why}.\n"
            f"<i>محرومیت با آمارِ هفتگیِ بعدی برداشته می‌شود.</i>",
            parse_mode="HTML")
        return

    # بازیکن زنده نمی‌تواند گاد شود — فقط وقتی نقش‌ها پخش شده‌اند
    # (قبل از پخش نقش‌ها هر کسی، حتی داخل لیست، می‌تواند گاد شود)
    if getattr(g, "assigned_roles", None):
        alive_uids = {g.seats[s][0] for s in g.seats if s not in (g.striked or set())}
        if target.id in alive_uids:
            await update.message.reply_text(
                "⛔ این بازیکن هنوز در بازی زنده است و نمی‌تواند گاد شود."
            )
            return

    # نام ترجیحی: از gist اگر موجود، وگرنه نام تلگرام
    new_name = g.user_names.get(target.id, target.full_name)

    old_god_id = g.god_id
    # 🚪 اگر بازی در جریان بود، گادِ قبلی «ترکِ بازی» ثبت می‌شود (هر بازی یک‌بار)
    if old_god_id and old_god_id != target.id and g.phase not in ("idle", "ended"):
        if not isinstance(getattr(g, "god_abandon_logged", None), set):
            g.god_abandon_logged = set()
        if old_god_id not in g.god_abandon_logged:
            g.god_abandon_logged.add(old_god_id)
            _old_name = g.user_names.get(old_god_id) or getattr(g, "god_name", None)
            if record_god_abandon(old_god_id, _old_name):
                print(f"🚪 god abandon logged for {old_god_id}")

    g.god_id = target.id
    g.god_name = new_name
    store.save()

    # 🔗 اتاق مافیا: گادِ قبلی حذف + چرخش لینک، لینکِ جدید به گادِ جدید
    if getattr(g, "mafia_room_id", None):
        if old_god_id and old_god_id in g.mafia_room_members and old_god_id != target.id:
            await _room_kick(ctx, g, old_god_id)
            g.mafia_room_members.discard(old_god_id)
            await _room_rotate_link(ctx, g)
        await _room_send_link(ctx, g, target.id)
        # ⏰ اگر گادِ جدید تا ۵ دقیقه جوین نشد، لینکِ جدید بساز و بفرست
        asyncio.create_task(_room_join_check_later(ctx, g))

    await update.message.reply_text(f"✅ حالا گاد جدید بازیه {new_name}.")

    # 🎛 تعویضِ گاد وسطِ شب: پنلِ دکمه‌های شب از پیویِ گادِ قدیم برداشته و
    #    برای گادِ جدید ساخته می‌شود (وگرنه کنترلِ شب دستِ گادِ رفته می‌ماند)
    if getattr(g, "night_active", False):
        _oldmid = getattr(g, "night_god_panel_mid", None)
        if _oldmid and old_god_id:
            try:
                await ctx.bot.edit_message_text(
                    chat_id=old_god_id, message_id=_oldmid,
                    text="👑 گادِ بازی عوض شد — دکمه‌های شب به گادِ جدید منتقل شد.")
            except Exception:
                try:
                    await ctx.bot.edit_message_reply_markup(
                        chat_id=old_god_id, message_id=_oldmid, reply_markup=None)
                except Exception:
                    pass
        g.night_god_panel_mid = None
        g.god_acting_as = None      # 🎛 اکتِ دستیِ نیمه‌کارهٔ گادِ قبلی باطل می‌شود
        g.god_act_tmp = None
        try:
            _kb = InlineKeyboardMarkup([
                [InlineKeyboardButton("🔥 سوزاندن اکت", callback_data="nburn_open"),
                 InlineKeyboardButton("👢 کیک شب", callback_data="nkick_open")],
                [InlineKeyboardButton("🎛 اکت دستی", callback_data="gact_open")],
            ])
            _pm = await ctx.bot.send_message(
                target.id, f"🌙 شب {g.night_number} — پنلِ گاد", reply_markup=_kb)
            g.night_god_panel_mid = _pm.message_id
        except Exception:
            await update.message.reply_text("⚠️ پنلِ شب به پیویِ گادِ جدید نرفت (پیوی بسته است).")
        store.save()

    mode = CTRL if g.phase != "idle" else REG
    await publish_seating(ctx, chat, g, mode=mode)

    if g.phase != "idle":
        log = []
        for seat in sorted(g.assigned_roles):
            role = g.assigned_roles.get(seat, "—")
            name = g.seats[seat][1]
            log.append(f"{name} ⇦ {role}")
        try:
            await ctx.bot.send_message(
                target.id,
                "👑 شما به عنوان گاد جدید انتخاب شدید.\n\n🧾 لیست نقش‌ها:\n" + "\n".join(log)
            )
            # 🌙 گزارش اکت‌های شب‌های گذشته برای گاد جدید
            night_log = getattr(g, "night_log", None)
            if night_log:
                report = "📜 <b>گزارش اکت‌های شب‌های گذشته</b>\n" + "\n".join(night_log)
                chunk = ""
                for line in report.split("\n"):
                    if len(chunk) + len(line) + 1 > 3500:
                        try:
                            await ctx.bot.send_message(target.id, chunk, parse_mode="HTML")
                        except Exception:
                            pass
                        chunk = ""
                    chunk += (line + "\n")
                if chunk.strip():
                    try:
                        await ctx.bot.send_message(target.id, chunk, parse_mode="HTML")
                    except Exception:
                        pass
        except telegram.error.Forbidden:
            await update.message.reply_text("⚠️ نتونستم نقش‌ها رو به پیوی گاد جدید بفرستم.")


def _pm_keyboard(uid=None):
    """کیبوردِ پیوی — برای سازندهٔ بات یک دکمهٔ اضافه‌ی «پنل مدیریت» هم دارد.
    ⚠️ is_persistent عمداً False است: با True تلگرام دکمهٔ جمع‌کردنِ کیبورد (⌨️) را
    برمی‌دارد و کاربر گیر می‌کند — نه می‌تواند ببنددش نه تایپ کند. با False
    همان دکمه‌ها هستند ولی هر وقت خواست با آیکنِ کیبورد جمع/باز می‌شوند."""
    rows = [["📊 آمار من", "👑 آمار کل"], ["🏆 آمار هفتگی", "🎮 بازی من"]]
    if uid == ADMIN_ID:
        rows.append(["🛠 پنل مدیریت"])
    return ReplyKeyboardMarkup(rows, resize_keyboard=True, is_persistent=False,
                               input_field_placeholder="پیام بنویس یا از دکمه‌ها استفاده کن")


async def start_welcome(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """پیام خوش‌آمد برای کسانی که بات را استارت می‌کنند (پیوی)."""
    try:
        await update.message.reply_text(
            "سلام! 🎭 به بات مافیا خوش آمدید.\n\n"
            "این بات برای اجرای بازی مافیا در گروه‌ها ساخته شده و اکت‌های شبانهٔ نقش شما "
            "در همین پیوی انجام می‌شود.\n\n"
            "از دکمه‌های پایین استفاده کنید 👇\n\n"
            "موفق باشید! 🌙",
            reply_markup=_pm_keyboard(update.effective_user.id)
        )
    except Exception:
        pass
    # 📬 اگر وسطِ بازی تازه استارت کرده، هرچه از دستش رفته همین حالا برایش می‌رود
    try:
        await _deliver_pending_on_start(ctx, update.effective_user.id)
    except Exception as e:
        print("⚠️ start catch-up:", e)


async def _deliver_pending_on_start(ctx, uid):
    """📬 بازیکنی که بات را دیر استارت کرده: نقش (+استیکر) و لینکِ اتاقِ مافیا
    به‌محضِ استارت برایش فرستاده می‌شود — چیزی که قبلاً به‌خاطر بستهبودنِ پیوی نرسیده بود."""
    for cid, g in list(store.games.items()):
        if getattr(g, "phase", "idle") in ("idle", "ended"):
            continue
        if not getattr(g, "assigned_roles", None):
            continue
        seat = _seat_of_uid(g, uid)
        if seat is None or seat in (g.striked or set()):
            continue
        role = (g.assigned_roles or {}).get(seat)
        if not role:
            continue
        try:
            stickers = load_stickers()
            if role in stickers:
                await ctx.bot.send_sticker(uid, stickers[role])
        except Exception:
            pass
        try:
            await ctx.bot.send_message(uid, f"🎭 نقش شما: {role}")
        except Exception:
            continue      # پیوی هنوز باز نیست — بی‌خیالِ همین بازی
        # 🔗 اگر عضوِ تیمِ مافیاست، لینکِ اتاق هم برود
        try:
            if getattr(g, "mafia_room_id", None) and seat in _mafia_room_seats(g):
                await _room_send_link(ctx, g, uid)
        except Exception as e:
            print("⚠️ start catch-up room link:", e)
        await _night_report(ctx, g, f"📬 {seat}. {escape(g.seats[seat][1], quote=False)} "
                                    f"بات را استارت کرد — نقشش (و لینکِ اتاق) خودکار ارسال شد.")
        # 🌙 اگر وسطِ شب پرامپتِ بی‌جواب داشته، همان را هم دوباره بفرست
        try:
            _pc = (getattr(g, "night_prompt_cache", {}) or {}).get(uid)
            if _pc and getattr(g, "night_active", False):
                _m = await _safe_pm(ctx, uid, _pc[0], _kb_load(_pc[1]))
                if _m:
                    g.night_pm_msgs[uid] = _m.message_id
                    store.save()
        except Exception as e:
            print("⚠️ start catch-up prompt:", e)


