async def _adm_send(ctx, uid, text):
    try:
        await ctx.bot.send_message(uid, text, parse_mode="HTML",
                                   disable_web_page_preview=True)
    except Exception as e:
        print("⚠️ adm send:", e)


async def open_admin_panel(ctx, uid):
    await ctx.bot.send_message(
        uid, "🛠 <b>پنلِ مدیریت</b>\nهر دکمه کارش را زیرش نوشته — کارهای اجرایی تأیید می‌خواهند.",
        parse_mode="HTML", reply_markup=_adm_panel_kb())


async def handle_admin_panel_callback(update, ctx):
    q = update.callback_query
    uid = q.from_user.id
    if uid != ADMIN_ID:
        await safe_q_answer(q, "⛔ فقط سازندهٔ بات.", show_alert=True)
        return
    await safe_q_answer(q)
    data = q.data
    bot = ctx.bot

    # ── تأییدِ کارهای اجرایی ──
    if data in _ADM_CONFIRM:
        txt, go = _ADM_CONFIRM[data]
        await bot.send_message(
            uid, f"⚠️ {txt}\n\nمطمئنی؟", parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("✅ بله، انجام بده", callback_data=go),
                InlineKeyboardButton("🚫 انصراف", callback_data="adm_cancel"),
            ]]))
        return

    if data == "adm_cancel":
        try:
            await bot.edit_message_text(chat_id=uid, message_id=q.message.message_id,
                                        text="🚫 انصراف داده شد.")
        except Exception:
            pass
        return

    if data == "adm_do_weekly":
        res = await broadcast_weekly_stats(bot, force=True) or {}
        n = res.get("sent", 0)
        await _adm_send(ctx, uid, f"📢 آمارِ هفتگی به <b>{n}</b> گروه فرستاده شد."
                                  + (f"\nدلیلِ نفرستادن: <code>{res.get('reason')}</code>"
                                     if not n and res.get("reason") else ""))
        return

    if data == "adm_do_invite":
        res = await launch_selected_round(bot) or {}
        sent = res.get("sent", []) if isinstance(res, dict) else []
        failed = res.get("failed", []) if isinstance(res, dict) else []
        await _adm_send(ctx, uid,
                        f"📨 دعوت‌نامه فرستاده شد.\n✅ موفق: <b>{len(sent)}</b>"
                        + (f"\n⚠️ ناموفق: <b>{len(failed)}</b>" if failed else ""))
        return

    if data == "adm_do_season":
        await season_cmd(_AdmUpdate(bot, uid), _AdmCtx(bot))
        return

    # ── گزارش‌های فقط‌خواندنی ──
    if data == "adm_rooms":
        await rooms_status_cmd(_AdmUpdate(bot, uid), _AdmCtx(bot))
        return

    if data == "adm_sel":
        await selected_report_cmd(_AdmUpdate(bot, uid), _AdmCtx(bot))
        return

    if data == "adm_scen":
        await list_scenarios(_AdmUpdate(bot, uid), _AdmCtx(bot))
        return

    if data == "adm_chan":
        ch = get_archive_channel()
        await _adm_send(ctx, uid,
                        f"📡 چنلِ آرشیو: <code>{escape(str(ch), quote=False)}</code>" if ch
                        else "📡 چنلِ آرشیو ثبت نشده.\nبا <code>/channel @name</code> ثبتش کن.")
        return

    if data == "adm_groups":
        gs_ = sorted(store.active_groups or [])
        if not gs_:
            await _adm_send(ctx, uid, "🌍 هیچ گروهِ فعالی ثبت نشده.")
            return
        lines = [f"🌍 <b>گروه‌های فعال ({len(gs_)})</b>:"]
        for cid in gs_:
            try:
                ch = await bot.get_chat(cid)
                nm = escape(ch.title or str(cid), quote=False)
            except Exception:
                nm = "—"
            lines.append(f"• <code>{cid}</code> — {nm}")
        await _adm_send(ctx, uid, "\n".join(lines))
        return

    if data == "adm_mafia":
        roles = sorted(load_mafia_roles() or [])
        await _adm_send(ctx, uid,
                        ("😈 <b>نقش‌های مافیا</b>:\n" + "\n".join(f"• {escape(r, quote=False)}"
                                                                  for r in roles))
                        if roles else "😈 فهرستِ نقش‌های مافیا خالی است.")
        return

    if data == "adm_indep":
        d = load_indep_roles() or {}
        if not d:
            await _adm_send(ctx, uid, "🕵️ هیچ نقشِ مستقلی ثبت نشده.")
            return
        lines = ["🕵️ <b>نقش‌های مستقل</b>:"]
        for scn, rs in d.items():
            lines.append(f"• <b>{escape(str(scn), quote=False)}</b>: "
                         + "، ".join(escape(str(r), quote=False) for r in (rs or [])))
        await _adm_send(ctx, uid, "\n".join(lines))
        return

    if data == "adm_cards":
        d = load_cards() or {}
        if not d:
            await _adm_send(ctx, uid, "🃏 هیچ کارتی ثبت نشده.")
            return
        lines = ["🃏 <b>کارت‌ها</b> (متنی):"]
        for scn, cs in d.items():
            lines.append(f"• <b>{escape(str(scn), quote=False)}</b> — {len(cs or [])} کارت")
        await _adm_send(ctx, uid, "\n".join(lines))
        return

    if data == "adm_season":
        stats = load_player_stats()
        if stats is None:
            await _adm_send(ctx, uid, "⚠️ آمار خوانده نشد (خطای جیست) — دوباره بزن.")
            return
        rows = sorted(((_season_total(d), d.get("name", "بازیکن"))
                       for d in stats.values()), reverse=True)[:5]
        lines = [f"🏆 <b>وضعیتِ فصل</b> — سقف: <b>{int(SEASON_TARGET)}</b>", ""]
        for i, (pts, nm) in enumerate(rows, 1):
            lines.append(f"{i}. {escape(str(nm), quote=False)} — <b>{pts:.0f}</b>")
        if rows:
            lines.append("")
            lines.append("✅ کسی به سقف رسیده — با «🏁 بستنِ فصل» ببندش."
                         if rows[0][0] >= SEASON_TARGET
                         else f"⏳ تا سقف: <b>{SEASON_TARGET - rows[0][0]:.0f}</b> امتیاز")
        await _adm_send(ctx, uid, "\n".join(lines))
        return

    if data == "adm_bans":
        bans = load_god_bans()
        if bans is None:
            await _adm_send(ctx, uid, "⚠️ فهرستِ محرومیت‌ها خوانده نشد (خطای جیست) — دوباره بزن.")
            return
        stats = load_player_stats() or {}
        now = datetime.now(timezone.utc).timestamp()

        def _nm(k):
            return escape(str((stats.get(str(k)) or {}).get("name") or k), quote=False)

        gods = bans.get("banned") or {}
        seats = {k: v for k, v in (bans.get("seats") or {}).items()
                 if float((v or {}).get("until", 0) or 0) > now}
        lines = ["🚫 <b>محرومیت‌ها</b>", ""]
        lines.append(f"🎩 <b>محرومِ گاد شدن ({len(gods)})</b>:")
        for k, v in list(gods.items())[:30]:
            why = v.get("reason") if isinstance(v, dict) else v
            lines.append(f"• {_nm(k)} — {escape(str(why), quote=False)}")
        if not gods:
            lines.append("— کسی نیست")
        lines.append("")
        lines.append(f"👢 <b>محرومِ نشستن ({len(seats)})</b>:")
        for k, v in list(seats.items())[:30]:
            left = max(0, (float(v.get("until", 0) or 0) - now) / 86400)
            lines.append(f"• {_nm(k)} — {left:.1f} روزِ دیگر")
        if not seats:
            lines.append("— کسی نیست")
        lines.append("")
        blk = bans.get("blocked") or {}
        lines.append(f"⛔ <b>محرومِ کاملِ بات ({len(blk)})</b>:")
        for k in list(blk)[:30]:
            lines.append(f"• {_nm(k)}")
        if not blk:
            lines.append("— کسی نیست")
        lines.append("")
        lines.append("<i>برای رفعش، روی پیامِ طرف ریپلای کن و بنویس «رفع محرومیت».</i>")
        await _adm_send(ctx, uid, "\n".join(lines))
        return

    if data == "adm_help":
        await _adm_send(ctx, uid, _ADM_HELP)
        return


async def handle_stats_pm(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """«آمار من» و «آمار کل» در پیوی بات."""
    msg = update.message
    if not msg or not msg.text:
        return
    text = msg.text.strip()
    uid = msg.from_user.id
    # 🛠 پنلِ مدیریت (فقط سازندهٔ بات)
    if text.endswith("پنل مدیریت"):
        if uid == ADMIN_ID:
            await open_admin_panel(ctx, uid)
        return
    # 🔓 با هر بار زدنِ این دکمه‌ها، کیبوردِ تازه (قابلِ بستن) هم فرستاده می‌شود؛
    #    این کسانی را که پشتِ کیبوردِ چسبانِ قدیمی گیر کرده‌اند آزاد می‌کند.
    _kb = _pm_keyboard(uid)

    async def _rep(t, **kw):
        kw.setdefault("reply_markup", _kb)
        return await msg.reply_text(t, **kw)

    # دکمه‌های کیبورد ایموجی دارند («📊 آمار من») → تطبیقِ پسوندی
    if text.endswith("آمار من"):
        stats = load_player_stats() or {}
        p = stats.get(str(uid))
        if not p or (p.get("games", 0) == 0 and p.get("god_games", 0) == 0):
            await _rep("📭 هنوز آماری برای شما ثبت نشده است.")
        else:
            await _rep(format_player_stats(p), parse_mode="HTML")
    elif text.endswith("آمار کل"):
        board = build_alltime_leaderboard_text(load_player_stats() or {})
        if not board:
            await _rep("📭 هنوز آماری ثبت نشده است.")
        else:
            await _rep(board, parse_mode="HTML")
    elif text.endswith("بازی من"):
        rows = (load_game_history() or {}).get(str(uid), [])
        if not rows:
            await _rep("📭 از زمانِ فعال‌شدنِ تاریخچه، بازی‌ای برای شما ثبت نشده است.")
        else:
            await _rep(format_game_history(rows), parse_mode="HTML")
    elif text.endswith("آمار هفتگی"):
        meta = load_weekly_meta()
        snapshot = meta.get("snapshot", {}) if isinstance(meta, dict) else {}
        board = build_weekly_leaderboard_text(load_player_stats() or {}, snapshot, require_weekly=False)
        if not board:
            await _rep("📭 هنوز آماری برای این هفته ثبت نشده است.")
        else:
            await _rep(board, parse_mode="HTML")


# ═════════════════════════════════════════════════════════════
#  اتاق چت مافیا (گروه‌های جداگانه)
# ═════════════════════════════════════════════════════════════
ROOMS_FILENAME = "mafia_rooms.json"


def load_mafia_rooms() -> list:
    try:
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        r = httpx.get(url, headers=headers)
        if r.status_code == 200:
            content = r.json()["files"].get(ROOMS_FILENAME, {}).get("content", "[]")
            return json.loads(content) or []
    except Exception as e:
        print("❌ load_mafia_rooms error:", e)
    return []


def save_mafia_rooms(rooms: list):
    try:
        url = f"https://api.github.com/gists/{GIST_ID}"
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        data = {"files": {ROOMS_FILENAME: {"content": json.dumps(rooms, ensure_ascii=False, indent=2)}}}
        httpx.patch(url, headers=headers, json=data)
    except Exception as e:
        print("❌ save_mafia_rooms error:", e)


def _mafia_room_seats(g):
    """صندلی‌های مافیایی که باید لینک اتاق بگیرند (در تکاور گروگانگیر مستثنی است)."""
    sides = getattr(g, "seat_sides", {}) or {}
    seats = [s for s in g.seats if s in (g.negotiated_seats or set()) or sides.get(s) == "مافیا"]
    if _is_takavar_scenario(g):
        seats = [s for s in seats if _seat_role_norm(g, s) != _R_HOSTAGE]
    if _is_mythic_scenario(g):
        # 💣 تروریست نه لینک می‌گیرد نه یارانش را می‌شناسد
        seats = [s for s in seats if not _my_role_is(g, s, _R_MY_TERROR)]
    if _is_gamer_scenario(g) and not getattr(g, "gm_scare_linked", False):
        # 🎃 مترسک تا وقتی لینک نشده، نه لینک می‌گیرد نه یارانش را می‌شناسد
        seats = [s for s in seats if _seat_role_norm(g, s) != _R_GM_SCARECROW]
    return seats


async def _room_send_link(ctx, g, uid):
    if not g.mafia_room_id or not g.mafia_room_link or uid in g.mafia_room_members:
        return
    # 🔓 اگر از بازی‌های قبلی در این اتاق بن مانده، اول رفعِ بن کن
    # (کاربرِ بن‌شده هنگام کلیک روی لینک، «لینک منقضی شده» می‌بیند)
    try:
        await ctx.bot.unban_chat_member(g.mafia_room_id, uid, only_if_banned=True)
    except Exception:
        pass
    g.mafia_room_members.add(uid)
    store.save()
    try:
        await ctx.bot.send_message(uid, f"🔗 لینک گروه مافیا:\n{g.mafia_room_link}")
    except Exception:
        pass


async def _room_kick(ctx, g, uid, allow_return=True):
    """حذف از اتاق بدونِ بنِ دائمی (بن + رفعِ بنِ فوری = فقط ریموو).
    جلوگیری از برگشت با عوض‌کردنِ لینک انجام می‌شود، نه بن."""
    if not g.mafia_room_id:
        return
    try:
        await ctx.bot.ban_chat_member(g.mafia_room_id, uid)
        await ctx.bot.unban_chat_member(g.mafia_room_id, uid, only_if_banned=True)
    except Exception:
        pass


async def _room_rotate_link(ctx, g):
    """باطل‌کردنِ لینکِ فعلی و ساختِ لینکِ جدید (تا حذف‌شده‌ها نتوانند برگردند).
    لینکِ جدید برای اعضایی که هنوز واردِ اتاق نشده‌اند دوباره ارسال می‌شود."""
    if not g.mafia_room_id:
        return
    if g.mafia_room_link:
        try:
            await ctx.bot.revoke_chat_invite_link(g.mafia_room_id, g.mafia_room_link)
        except Exception:
            pass
    try:
        link = await ctx.bot.create_chat_invite_link(g.mafia_room_id, name=f"game-{g.god_id}")
        g.mafia_room_link = link.invite_link
        store.save()
    except Exception:
        return
    # 🔁 لینکِ قبلیِ کسانی که هنوز جوین نشده‌اند باطل شد — لینکِ جدید را برایشان بفرست
    for uid in list(g.mafia_room_members):
        try:
            cm = await ctx.bot.get_chat_member(g.mafia_room_id, uid)
            inside = cm.status in ("member", "administrator", "creator")
        except Exception:
            inside = False
        if not inside:
            try:
                await ctx.bot.unban_chat_member(g.mafia_room_id, uid, only_if_banned=True)
            except Exception:
                pass
            try:
                await ctx.bot.send_message(uid, f"🔗 لینکِ جدید گروه مافیا (لینک قبلی باطل شد):\n{g.mafia_room_link}")
            except Exception:
                pass


async def _room_set_locked(ctx, g, locked: bool):
    if not g.mafia_room_id:
        return
    try:
        if locked:
            perms = ChatPermissions(can_send_messages=False)
        else:
            perms = ChatPermissions(
                can_send_messages=True, can_send_polls=True,
                can_send_other_messages=True, can_add_web_page_previews=True)
        await ctx.bot.set_chat_permissions(g.mafia_room_id, perms)
        g.mafia_room_locked = locked
        store.save()
    except Exception:
        pass


async def _room_allocate(ctx, g):
    """یک اتاقِ آزاد به این بازی اختصاص می‌دهد و لینک می‌سازد."""
    if g.mafia_room_id:
        return True
    rooms = load_mafia_rooms()
    if not rooms:
        return False

    # نگاشتِ اتاق → بازی‌هایی که آن را نگه داشته‌اند
    holders = {}
    for game in store.games.values():
        rid = getattr(game, "mafia_room_id", None)
        if rid:
            holders.setdefault(rid, []).append(game)

    _now = datetime.now().timestamp()

    def _holder_stale(game):
        # بازیِ تمام‌شده/ریست‌شده → اتاقش آزاد
        if getattr(game, "phase", "idle") in ("idle", "ended"):
            return True
        # اتاقی که بیش از ۲۴ ساعت پیش گرفته شده → بازیِ رهاشده حساب می‌شود
        taken = getattr(game, "mafia_room_taken_at", None)
        if taken and (_now - taken) > 24 * 3600:
            return True
        return False

    used = {rid for rid, hs in holders.items() if any(not _holder_stale(x) for x in hs)}
    free_rooms = [r for r in rooms if r not in used]
    def _oldest_ts(rid):
        return min((getattr(x, "mafia_room_taken_at", None) or 0)
                   for x in holders.get(rid, []))
    held_rooms = sorted([r for r in rooms if r in holders and r not in free_rooms],
                        key=_oldest_ts)
    # اول آزادها، بعد (در صورت نیاز) مشغول‌ها از قدیمی‌ترین — تا اولین اتاقِ «سالم» پیدا شود
    candidates = free_rooms + held_rooms
    if not candidates:
        candidates = list(rooms)

    for room in candidates:
        # 🧪 اول تست کن اتاق سالم است (لینک ساخته می‌شود)؛ اگر مرده بود برو سراغ بعدی
        try:
            link = await ctx.bot.create_chat_invite_link(room, name=f"game-{g.god_id}")
        except Exception as e:
            print(f"❌ اتاق {room} خراب است:", e)
            emsg = str(e).lower()
            if any(k in emsg for k in ("not found", "kicked", "upgraded", "migrated", "deactivated")):
                # اتاقِ مرده (مثلاً تبدیل به سوپرگروه و تغییر آیدی) → از فهرست حذف
                try:
                    rooms.remove(room)
                    save_mafia_rooms(rooms)
                    print(f"🗑 اتاق مرده {room} از فهرست حذف شد.")
                except Exception:
                    pass
            continue

        # 🧹 پاک‌سازیِ نگه‌دارنده‌های قبلیِ این اتاق (اعضای کهنه + همه‌ی بازیکنانِ آن بازی)
        for game in holders.get(room, []):
            olds = set(getattr(game, "mafia_room_members", set()) or set())
            for _s, (u, _n) in (getattr(game, "seats", {}) or {}).items():
                olds.add(u)
            for old_uid in olds:
                try:
                    await ctx.bot.ban_chat_member(room, old_uid)
                    await ctx.bot.unban_chat_member(room, old_uid, only_if_banned=True)
                except Exception:
                    pass
            if getattr(game, "mafia_room_link", None):
                try:
                    await ctx.bot.revoke_chat_invite_link(room, game.mafia_room_link)
                except Exception:
                    pass
            game.mafia_room_id = None
            game.mafia_room_link = None
            game.mafia_room_members = set()
            game.mafia_room_pending_link = []

        g.mafia_room_id = room
        g.mafia_room_link = link.invite_link
        g.mafia_room_members = set()
        g.mafia_room_pending_link = []
        g.mafia_room_kicked = set()
        g.mafia_room_taken_at = datetime.now().timestamp()
        store.save()
        # 🔁 چرخش اتاق‌ها: اتاقِ استفاده‌شده به تهِ فهرست می‌رود
        try:
            rooms.remove(room)
            rooms.append(room)
            save_mafia_rooms(rooms)
        except Exception:
            pass
        await _room_set_locked(ctx, g, False)   # شبِ معارفه باز باشد
        return True

    return False   # هیچ اتاقِ سالمی پیدا نشد


async def _room_membership(ctx, g):
    """وضعیت عضویتِ اعضای موردانتظار اتاق: (داخل‌ها، بیرون‌مانده‌ها) — بدون نیاز به پیام از کسی."""
    inside, outside = [], []
    for uid in list(g.mafia_room_members):
        try:
            cm = await ctx.bot.get_chat_member(g.mafia_room_id, uid)
            ok = cm.status in ("member", "administrator", "creator")
        except Exception:
            ok = False
        (inside if ok else outside).append(uid)
    return inside, outside


async def _room_join_check_later(ctx, g, delay=300):
    """⏰ بعد از ۵ دقیقه: هر عضو موردانتظار (مافیا/گاد) که هنوز جوین نشده →
    لینکِ جدید ساخته و برایش ارسال می‌شود + گزارش به گاد."""
    await asyncio.sleep(delay)
    if not getattr(g, "mafia_room_id", None):
        return   # بازی تمام/ریست شده
    _in, _out = await _room_membership(ctx, g)
    if not _out:
        return
    await _room_rotate_link(ctx, g)   # لینک نو + رفعِ بن + ارسال به جوین‌نشده‌ها
    names = []
    for uid in _out:
        seat = _seat_of_uid(g, uid)
        names.append(f"{seat}. {g.seats[seat][1]}" if seat
                     else ("گاد" if uid == g.god_id else str(uid)))
    await _night_report(ctx, g, "⏰ بعد از ۵ دقیقه هنوز واردِ اتاق مافیا نشده بودند: "
                        + "، ".join(names) + "\n(لینکِ جدید ساخته و برایشان ارسال شد)")


async def _room_sync_on_night(ctx, g):
    """در /شب: باز کردن چت + حذف مافیای مرده + چرخشِ لینک + ارسال لینکِ معوق + چکِ جوین‌نشده‌ها."""
    if not g.mafia_room_id:
        return
    # 🩸 هانیبال: اتاق تا اکتِ سایه بسته می‌ماند (در _hb_open_mafia باز می‌شود)
    # 🦷 دنتیست: تا دنتیست و محافظ اکت ندهند، اتاق بسته است (در _tk_check_open_mafia باز می‌شود)
    if not (_is_hanibal_scenario(g) or _is_dentist_scenario(g)):
        await _room_set_locked(ctx, g, False)
    removed_any = False
    for uid in list(g.mafia_room_members):
        if uid == g.god_id:
            continue   # ⚠️ گاد صندلی ندارد ولی هیچ‌وقت نباید حذف شود!
        seat = _seat_of_uid(g, uid)
        if seat is None or seat in (g.striked or set()):
            await _room_kick(ctx, g, uid)
            g.mafia_room_members.discard(uid)
            removed_any = True
    # 🔗 اگر کسی حذف شد، لینک عوض می‌شود تا با لینکِ قدیمی برنگردد
    if removed_any:
        await _room_rotate_link(ctx, g)
    for uid in list(g.mafia_room_pending_link or []):
        await _room_send_link(ctx, g, uid)
    g.mafia_room_pending_link = []
    store.save()
    # 👀 هر کس هنوز جوین نشده: رفعِ بن + ارسالِ دوباره‌ی لینک + گزارش به گاد
    _in, _out = await _room_membership(ctx, g)
    if _out:
        names = []
        for uid in _out:
            seat = _seat_of_uid(g, uid)
            names.append(f"{seat}. {g.seats[seat][1]}" if seat else str(uid))
            try:
                await ctx.bot.unban_chat_member(g.mafia_room_id, uid, only_if_banned=True)
            except Exception:
                pass
            try:
                await ctx.bot.send_message(uid, f"🔗 هنوز واردِ گروه مافیا نشده‌ای — لینک:\n{g.mafia_room_link}")
            except Exception:
                pass
        await _night_report(ctx, g, "⚠️ هنوز واردِ اتاق مافیا نشده‌اند: " + "، ".join(names)
                            + "\n(لینک دوباره برایشان ارسال شد)")


async def _room_drop_dead(ctx, g):
    """🚪 هر عضوِ اتاقِ مافیا که خط خورده، همان لحظه بیرون می‌رود.
    (وگرنه تا شبِ بعد — که _room_sync_on_night اجرا شود — داخل می‌ماند؛ و اگر
    خط‌خوردنش بعد از شروعِ شب باشد، اصلاً بیرون نمی‌رفت.)"""
    if not getattr(g, "mafia_room_id", None):
        return
    removed = False
    for uid in list(g.mafia_room_members or set()):
        if uid == g.god_id:
            continue
        seat = _seat_of_uid(g, uid)
        if seat is None or seat in (g.striked or set()):
            try:
                await _room_kick(ctx, g, uid)
            except Exception:
                pass
            g.mafia_room_members.discard(uid)
            removed = True
    if removed:
        try:
            await _room_rotate_link(ctx, g)   # 🔗 با لینکِ قدیمی برنگردد
        except Exception:
            pass
        store.save()


async def _room_cleanup(ctx, g):
    """پایان بازی: حذف همه + رفعِ بنِ همه + باطل‌کردن لینک + آزادسازی اتاق."""
    if not g.mafia_room_id:
        return
    # 🧹 جاروی کامل: ردیابی‌شده‌ها + همه‌ی بازیکنانِ بازی
    # (یاکوزایی/مذاکره/خریداری‌شده یا هرکسی که با لینکِ فورواردی داخل مانده)
    targets = set(g.mafia_room_members or set())
    for _s, (u, _n) in (g.seats or {}).items():
        targets.add(u)
    for uid in list(targets):
        await _room_kick(ctx, g, uid, allow_return=True)
    # 🔓 رفعِ بنِ کسانی که وسط بازی حذف شده بودند (تا در بازی‌های بعدیِ این اتاق «لینک منقضی» نگیرند)
    for uid in list(getattr(g, "mafia_room_kicked", set()) or set()):
        try:
            await ctx.bot.unban_chat_member(g.mafia_room_id, uid, only_if_banned=True)
        except Exception:
            pass
    if g.mafia_room_link:
        try:
            await ctx.bot.revoke_chat_invite_link(g.mafia_room_id, g.mafia_room_link)
        except Exception:
            pass
    g.mafia_room_id = None
    g.mafia_room_link = None
    g.mafia_room_members = set()
    g.mafia_room_pending_link = []
    g.mafia_room_kicked = set()
    g.mafia_room_taken_at = None
    store.save()


async def addroom_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """ثبتِ گروهِ فعلی به‌عنوان اتاق چت مافیا (ادمین)."""
    chat = update.effective_chat
    if chat.type not in ("group", "supergroup"):
        await update.message.reply_text("این دستور فقط در گروه‌ها کار می‌کند.")
        return
    try:
        admins = await ctx.bot.get_chat_administrators(chat.id)
        if update.effective_user.id not in {a.user.id for a in admins}:
            await update.message.reply_text("❌ فقط ادمین‌ها می‌توانند این گروه را ثبت کنند.")
            return
    except Exception:
        pass
    rooms = load_mafia_rooms()
    if chat.id in rooms:
        await update.message.reply_text("ℹ️ این گروه از قبل به‌عنوان اتاق مافیا ثبت شده است.")
        return
    rooms.append(chat.id)
    save_mafia_rooms(rooms)
    await update.message.reply_text(
        "✅ این گروه به‌عنوان «اتاق چت مافیا» ثبت شد.\n"
        "این گروه را «/active» نکنید. بات باید ادمین با دسترسیِ «دعوت» و «حذف اعضا» باشد.")


async def rooms_status_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """🏠 وضعیت اتاق‌های مافیا (فقط سازنده‌ی بات، در پیوی): تعداد اعضا + لینک سرکشی."""
    if update.effective_user.id != ADMIN_ID:
        return
    # 🙈 اگر خودم بازیکنِ زنده‌ی یک بازیِ در جریانم، لیست اتاق‌ها نباید لو برود
    for _cid, _game in store.games.items():
        if getattr(_game, "phase", "idle") in ("idle", "ended"):
            continue
        _seat = _seat_of_uid(_game, update.effective_user.id)
        if _seat is not None and _seat not in (_game.striked or set()):
            await update.message.reply_text("🙈 الان خودت بازیکنِ یک بازیِ در جریانی — بعد از بازی دوباره بزن.")
            return
    rooms = load_mafia_rooms()
    if not rooms:
        await update.message.reply_text("ℹ️ هیچ اتاقی ثبت نشده.")
        return
    # کدام بازی الان کدام اتاق را نگه داشته؟
    holder_of = {}
    for cid, game in store.games.items():
        rid = getattr(game, "mafia_room_id", None)
        if rid:
            holder_of[rid] = (cid, getattr(game, "phase", "؟"))
    lines = [f"🏠 <b>وضعیت اتاق‌های مافیا</b> ({len(rooms)} اتاق ثبت‌شده در Gist):"]
    for rid in rooms:
        try:
            chat_obj = await ctx.bot.get_chat(rid)
            cnt = await ctx.bot.get_chat_member_count(rid)
            others = max(0, cnt - 1)   # منهای خودِ بات
            try:
                link = await ctx.bot.create_chat_invite_link(rid, name="inspect")
                link_txt = link.invite_link
            except Exception:
                link_txt = "—"
            hold = holder_of.get(rid)
            hold_txt = f" | 🎮 در دستِ بازیِ {hold[0]} (فاز: {hold[1]})" if hold else " | آزاد"
            lines.append(f"\n• <b>{escape(chat_obj.title or str(rid), quote=False)}</b>"
                         f" — 👥 {others} عضو (غیر از بات){hold_txt}\n"
                         f"  🔗 سرکشی: {link_txt}")
        except Exception as e:
            lines.append(f"\n• <code>{rid}</code> → ❌ در دسترس نیست ({type(e).__name__}) — آیدیِ مرده، با /delroom یا /addroom مجدد درستش کن")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML",
                                    disable_web_page_preview=True)


async def delroom_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    rooms = load_mafia_rooms()
    if chat.id in rooms:
        rooms.remove(chat.id)
        save_mafia_rooms(rooms)
        await update.message.reply_text("🗑 این گروه از فهرست اتاق‌های مافیا حذف شد.")
    else:
        await update.message.reply_text("ℹ️ این گروه در فهرست اتاق‌ها نبود.")


def _mlink_seats(g):
    """👥 صندلی‌هایی که سایدشان مافیاست (برای انتخابِ گیرندگانِ لینکِ اتاق)."""
    sides = getattr(g, "seat_sides", {}) or {}
    return [s for s in sorted(g.seats) if sides.get(s) == "مافیا"]


async def _mlink_panel(ctx, g, mid=None):
    """🔗 پنلِ پیویِ گاد: لینکِ اتاقِ مافیا برای چه کسانی فرستاده شود؟
    (فقط سناریوهای بدونِ موتور — بات خودش برای هیچ‌کس نمی‌فرستد.)"""
    seats = _mlink_seats(g)
    if not seats:
        return
    sel = set(getattr(g, "mlink_sel", set()) or set())
    rows = []
    for s in seats:
        role = (g.assigned_roles or {}).get(s, "—")
        mark = "✅ " if s in sel else "▫️ "
        rows.append([InlineKeyboardButton(f"{mark}{s}. {g.seats[s][1]} — {role}",
                                          callback_data=f"mlk_t_{s}")])
    rows.append([InlineKeyboardButton("👥 همه", callback_data="mlk_all"),
                 InlineKeyboardButton("🧹 هیچ‌کس", callback_data="mlk_none")])
    rows.append([InlineKeyboardButton("✅ تأیید و ارسالِ لینک", callback_data="mlk_ok")])
    kb = InlineKeyboardMarkup(rows)
    text = ("🔗 <b>لینکِ اتاقِ مافیا برای چه کسانی فرستاده شود؟</b>\n"
            "<i>هرکدام را می‌خواهی بزن (یا «همه») و بعد «تأیید» — لینک فقط برای همان‌ها می‌رود.</i>")
    if mid:
        try:
            await ctx.bot.edit_message_text(chat_id=g.god_id, message_id=mid, text=text,
                                            parse_mode="HTML", reply_markup=kb)
            return
        except Exception:
            pass
    try:
        m = await ctx.bot.send_message(g.god_id, text, parse_mode="HTML", reply_markup=kb)
        g.mlink_mid = m.message_id
        store.save()
    except Exception as e:
        print("⚠️ mlink panel:", e)


async def handle_mlink_callback(update, ctx):
    """🔗 انتخابِ گیرندگانِ لینکِ اتاقِ مافیا توسطِ گاد (سناریوهای بدونِ موتور)."""
    q = update.callback_query
    data = q.data or ""
    uid = q.from_user.id
    mid = q.message.message_id if q.message else None

    g = None
    for _cid, game in store.games.items():
        if game.god_id == uid and getattr(game, "mlink_mid", None) == mid:
            g = game
            break
    if g is None:
        for _cid, game in store.games.items():
            if game.god_id == uid and getattr(game, "assigned_roles", None) \
                    and game.phase not in ("idle", "ended"):
                g = game
                break
    if g is None:
        await safe_q_answer(q, "بازی‌ای برای این پنل پیدا نشد.", show_alert=True)
        return

    seats = _mlink_seats(g)
    sel = set(getattr(g, "mlink_sel", set()) or set())

    if data == "mlk_ok":
        sel = {s for s in sel if s in g.seats}
        if not sel:
            await safe_q_answer(q, "اول حداقل یک نفر را انتخاب کن.", show_alert=True)
            return
        await safe_q_answer(q)
        names = []
        for s in sorted(sel):
            await _room_send_link(ctx, g, g.seats[s][0])
            names.append(f"• {s}. {g.seats[s][1]} — {(g.assigned_roles or {}).get(s, '—')}")
        g.mlink_sel = sel
        g.mlink_done = True
        store.save()
        try:
            await ctx.bot.edit_message_text(
                chat_id=g.god_id, message_id=mid,
                text="🔗 <b>لینکِ اتاقِ مافیا فرستاده شد برای:</b>\n" + "\n".join(names),
                parse_mode="HTML")
        except Exception:
            pass
        return

    if data == "mlk_all":
        sel = set(seats)
    elif data == "mlk_none":
        sel = set()
    elif data.startswith("mlk_t_"):
        try:
            s = int(data.rsplit("_", 1)[1])
        except Exception:
            return
        if s in sel:
            sel.discard(s)
        else:
            sel.add(s)
    else:
        await safe_q_answer(q)
        return

    await safe_q_answer(q)
    g.mlink_sel = sel
    store.save()
    await _mlink_panel(ctx, g, mid=mid)


async def do_maarefe(ctx, chat_id, g):
    """شب معارفه: اعلام در گروه + ارسال اسم یاران به مافیاها (بدون اکت برای شهروندان)."""
    if not getattr(g, "assigned_roles", None):
        await ctx.bot.send_message(chat_id, "⛔ ابتدا باید نقش‌ها پخش شوند.")
        return
    manual = _is_manual_scenario(g)
    g.maarefe_active = True   # شبِ معارفه (بدون اکت) — با /روز بسته می‌شود
    store.save()
    voice_god.say(chat_id, "maarefe")          # 🎙
    await ctx.bot.send_message(chat_id, "🎭 <b>شب معارفه</b>", parse_mode="HTML")
    sides = getattr(g, "seat_sides", {}) or {}
    mafia_seats = [s for s in sorted(g.seats) if sides.get(s) == "مافیا"]
    if _is_mythic_scenario(g):
        # 💣 تروریست نه یارانش را می‌شناسد نه یارانش او را
        mafia_seats = [s for s in mafia_seats if not _my_role_is(g, s, _R_MY_TERROR)]
    # ✋ سناریوی بدونِ موتور: بات هیچ نقشی برای تیمِ مافیا نمی‌فرستد — همه‌چیز دستِ گاد است
    if not manual:
        for s in mafia_seats:
            uid = g.seats[s][0]
            mates = [f"{m}. {g.seats[m][1]} — {g.assigned_roles.get(m, '—')}"
                     for m in mafia_seats if m != s]
            text = "🎭 شب معارفه\n\n😈 یاران مافیای شما:\n" + ("\n".join(mates) if mates else "—")
            try:
                await ctx.bot.send_message(uid, text)
            except Exception:
                pass

    # 🔗 اتاق چت مافیا: تخصیص + ارسال لینک به گاد و مافیاها (در تکاور گروگانگیر مستثنی)
    if await _room_allocate(ctx, g):
        await _room_send_link(ctx, g, g.god_id)
        if manual:
            # ✋ لینک فقط برای کسانی می‌رود که خودِ گاد در پیویش انتخاب و تأیید کند
            g.mlink_sel = set()
            g.mlink_done = False
            store.save()
            await _mlink_panel(ctx, g)
            await ctx.bot.send_message(chat_id, "🔗 لینک گروه مافیا به پیوی گاد ارسال شد.")
        else:
            for s in _mafia_room_seats(g):
                await _room_send_link(ctx, g, g.seats[s][0])
            await ctx.bot.send_message(chat_id, "🔗 لینک گروه مافیا به پیوی گاد و مافیاها ارسال شد.")
        g.maarefe_done = True   # ✅ موفق → دکمه‌ی معارفه از پنل حذف می‌شود
        store.save()
        # ⏰ بعد از ۵ دقیقه اگر کسی جوین نشده بود، لینکِ جدید بساز و بفرست
        asyncio.create_task(_room_join_check_later(ctx, g))
    else:
        if load_mafia_rooms():
            await ctx.bot.send_message(
                chat_id,
                "⚠️ هیچ اتاقِ مافیای سالمی در دسترس نیست.\n"
                "احتمالاً آیدیِ اتاق‌ها عوض شده (تبدیل به سوپرگروه). "
                "در هر اتاق دوباره /addroom بزن.")
            # ❗ ناموفق → دکمه‌ی معارفه می‌ماند تا دوباره امتحان شود
        else:
            g.maarefe_done = True   # اتاقی تعریف نشده → معارفه بدون اتاق انجام شد
            store.save()

    # 🕵️ کاوربازپرس: ناتو یک نفر را به تیم دعوت می‌کند (بعد از ساختِ لینکِ اتاق،
    #    چون گادفادرِ تازه باید همان لینک را بگیرد)
    if _is_cover_scenario(g) and not getattr(g, "cvb_done", False):
        await _cvb_start(ctx, chat_id, g)

    # 🩸 هانیبال: خریدِ رئیس — لینک بعد از تعیینِ رئیس برای هر سه می‌رود
    if _is_hanibal_scenario(g) and not getattr(g, "hb_done", False):
        await _hb_start(ctx, chat_id, g)

    # سناریو گیمر: دن‌کارلئونه باید یک جمله بنویسد (به مسترهلمز می‌رسد)
    if _is_gamer_scenario(g):
        don = _find_seat_by_role(g, _R_DONC)
        if don and not g.gm_don_sentence:
            g.gm_awaiting_don_sentence = True
            store.save()
            try:
                await ctx.bot.send_message(
                    g.seats[don][0],
                    "✍️ شب معارفه — یک جمله بنویس و همین‌جا بفرست؛ "
                    "این جمله به مسترهلمز می‌رسد (اجباری).")
            except Exception:
                pass
        # ✍️ هم‌زمان: جمله از مسترهلمز → برای موریارتی
        _hs = _find_seat_by_role(g, _R_HOLMES)
        if _hs and not getattr(g, "gm_holmes_sentence", None):
            g.gm_awaiting_holmes_sentence = True
            store.save()
            try:
                await ctx.bot.send_message(
                    g.seats[_hs][0],
                    "✍️ شب معارفه — یک جمله بنویس و همین‌جا بفرست؛ "
                    "این جمله به موریارتی می‌رسد (اجباری).")
            except Exception:
                pass

    # سناریو کاپو: اکت اجباری وارث در شب معارفه
    if _is_kapu_scenario(g) and g.heir_target is None:
        heir = _find_seat_by_role(g, _R_HEIR)
        if heir:
            huid = g.seats[heir][0]
            targets = [s for s in _alive_seats(g) if s != heir]
            try:
                m = await ctx.bot.send_message(
                    huid, "⚱️ شب معارفه — چه کسی را انتخاب می‌کنی؟ (اجباری، یک‌بار)",
                    reply_markup=_kb_night_seats(targets, g, "kp_heir_", confirm_cb="kp_heir_confirm"))
                g.night_pm_msgs[huid] = m.message_id   # maarefe_active قبلاً ست شده تا کال‌بک پیدا شود
                store.save()
            except Exception:
                pass


def _diag_scenario_report(g) -> str:
    sc = getattr(g, "scenario", None)
    sc_name = sc.name if sc else "—"
    detected = []
    if _is_neg_scenario(g): detected.append("مذاکره")
    if _is_baazpors_scenario(g): detected.append("بازپرس")
    if _is_cover_scenario(g): detected.append("کاوربازپرس")
    if _is_hanibal_scenario(g): detected.append("هانیبال")
    if _is_nemayande_scenario(g): detected.append("نماینده")
    if _is_takavar_scenario(g): detected.append("تکاور")
    if _is_kapu_scenario(g): detected.append("کاپو")
    if _is_gamer_scenario(g): detected.append("گیمر")
    if _is_shahname_scenario(g): detected.append("شاهنامه")
    if _is_mythic_scenario(g): detected.append("میتیک")
    lines = [
        "🔍 <b>تشخیص سناریو و نقش‌ها</b>",
        f"نام سناریو: «{escape(sc_name, quote=False)}»",
        "تشخیص خودکار: " + (", ".join(detected) if detected else "❌ هیچ‌کدام — اکت خودکار فعال نمی‌شود!"),
        "",
        "صندلی → نقش → تشخیص:",
    ]
    mafia = _mafia_seats(g)
    for s in sorted(g.seats):
        role = (g.assigned_roles or {}).get(s, "—")
        tag = "😈 مافیا" if s in mafia else "🏙 شهر"
        lines.append(f"{s}. {escape(role, quote=False)} → {tag}")
    if detected and not mafia:
        lines.append("\n⚠️ هیچ نقشِ مافیایی شناسایی نشد! احتمالاً املای نقش‌ها با سناریو نمی‌خواند.")
    return "\n".join(lines)


async def handle_direct_name_input(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    if not msg or not msg.text:
        return

    chat_id = msg.chat.id
    uid = msg.from_user.id
    g = gs(chat_id)
    text = msg.text.strip()

    # ⛔🔓 «محروم / رفع محرومیت» با @یوزرنیم یا آیدی — بدونِ ریپلای هم کار کند
    #    (مسیرِ ریپلایش در name_reply است؛ اینجا حالتِ بدونِ‌ریپلا‌ی را می‌گیریم)
    if _is_super_admin(uid):
        _barg = _cmd_arg(text, _BLOCK_PHRASES)
        if _barg is not None:
            await _block_from_reply(ctx, msg, arg=_barg)
            return
    _uarg = _cmd_arg(text, _UNBAN_PHRASES)
    if _uarg is not None:
        if await _can_unban(ctx, chat_id, uid):
            await _god_unban_from_reply(ctx, msg, by_uid=uid, arg=_uarg)
        return

    # 🗳 ثبت رأی — فقط «دولایک با هر رنگ» یا «..»؛ ملاک زمان = ساعت تلگرام
    # (قبل از هر شرط دیگری، تا هیچ هندلری پیامِ رأی را ندزدد)
    if _try_capture_vote(g, msg, uid, text):
        return

    # 🧑‍⚖️ دوئلِ بازپرسی: شمارشِ شماره‌صندلی + اعلامِ رأیِ ناخوانا (فقط یک تذکر به هر نفر)
    if getattr(g, "baz_duel_active", False):
        _vs = _seat_of_uid(g, uid)
        if _vs in (getattr(g, "baz_duel_pair", []) or []):
            return   # 🧑‍⚖️ دو طرفِ بازپرسی حقِ رأی ندارند
        if _vs is not None and _vs not in (g.striked or set()) and uid != g.god_id:
            _bv = _deng_parse_strict(text, tuple(getattr(g, "baz_duel_pair", []) or []))
            if _bv is not None:
                g.baz_duel_votes[uid] = _bv
                g.baz_duel_unread.discard(uid)
                store.save()
                # ✅ همه‌ی زنده‌ها (به‌جز دو طرف) رأی دادند → شمارشِ خودکار، بدونِ نیاز به دکمه
                _dp = getattr(g, "baz_duel_pair", []) or []
                _need = [x for x in _alive_seats(g) if x not in _dp]
                if _need and all(g.seats[x][0] in g.baz_duel_votes for x in _need):
                    await _baz_duel_count(ctx, msg.chat.id, g)
                return
            if uid not in (g.baz_duel_votes or {}):
                _first = uid not in (g.baz_duel_unread or set())
                g.baz_duel_unread.add(uid)
                store.save()
                if _first:
                    _p = list(getattr(g, "baz_duel_pair", []) or [])
                    try:
                        await msg.reply_text(
                            f"⚠️ {_vs}. {g.seats[_vs][1]} رأیت خوانده نشد — "
                            f"دوباره فقط عدد بنویس ({_p[0]} یا {_p[1]}).")
                    except Exception:
                        pass
                return
        # گاد، تماشاچی‌ها و رأی‌داده‌ها → عبور به هندلرهای عادی

    # 🗳 شمارشِ دنگِ نمایندگی
    if getattr(g, "nem_deng_active", False):
        if await _nem_deng_capture(ctx, g, msg, uid, text):
            return

    # 🔫 گانِ روزِ تکاور: «گان» یا 🔫 → نشانه‌گیری؛ بعد یک عدد (به هر شکل) → شلیک
    if (_is_takavar_scenario(g) and not getattr(g, "night_active", False)
            and (getattr(g, "tk_day_guns", {}) or {})):
        _gseat = _seat_of_uid(g, uid)
        if (_gseat is not None and _gseat in g.tk_day_guns
                and _gseat not in (g.striked or set())):
            if _nz(text) == _nz("گان") or "🔫" in text:
                g.tk_gun_aiming = _gseat
                store.save()
                try:
                    await msg.reply_text(f"🔫 {_gseat}. {g.seats[_gseat][1]} — "
                                         f"چه شخصی را شلیک می‌کنی؟ (شماره‌ی صندلی)")
                except Exception:
                    pass
                return
            if getattr(g, "tk_gun_aiming", None) == _gseat:
                _tv = _deng_parse_strict(
                    text, tuple(x for x in _alive_seats(g) if x != _gseat))
                if _tv is not None:
                    await _tk_day_gun_fire(ctx, msg.chat.id, g, _gseat, _tv)
                    return

    # 🤝 شمارشِ دنگِ معتمدِ کاپو
    if getattr(g, "kp_deng_active", False):
        if await _kp_deng_capture(ctx, g, msg, uid, text):
            return

    # 🎩 شمارشِ رأیِ کلاسیک (اولیه/دوباره/نهایی)
    if getattr(g, "cl_vote_active", None):
        if await _cl_vote_capture(ctx, g, msg, uid, text):
            return

    # 💣 تروریستِ کلاسیک: بعد از خروج با رأیِ نهایی، شماره می‌نویسد و طرف را با خود می‌برد
    if (_is_classic_scenario(g) and getattr(g, "cl_terror_wait", None) is not None
            and not getattr(g, "night_active", False)):
        _cts = g.cl_terror_wait
        if _cts in g.seats and uid == g.seats[_cts][0]:
            _ctv = _deng_parse_strict(text, tuple(_alive_seats(g)))
            if _ctv is not None:
                await _cl_terror_fire(ctx, msg.chat.id, g, _cts, _ctv)
                return

    # ⚔️ شمارشِ رأی‌گیریِ شاهنامه (روز ۱)
    if getattr(g, "sh_vote_active", False):
        if await _sh_vote_capture(ctx, g, msg, uid, text):
            return

    # 🏹 کمانِ آرش: «کمان» یا 🏹 → نشانه‌گیری؛ بعد یک عدد → شلیک
    if (_is_shahname_scenario(g) and not getattr(g, "night_active", False)
            and getattr(g, "sh_bow_holder", None)):
        _bseat = _seat_of_uid(g, uid)
        if (_bseat is not None and _bseat == _sh_bow_shooter(g)
                and _bseat not in (g.striked or set())):
            # ⏸ منتظرِ دفاع و دکمه‌های تصمیم — هیچ متنی اینجا کاری نمی‌کند
            if getattr(g, "sh_bow_pending", None) is None:
                if _nz(text) == _nz("کمان") or "🏹" in text:
                    g.sh_bow_aiming = _bseat
                    store.save()
                    try:
                        await msg.reply_text(f"🏹 {_bseat}. {g.seats[_bseat][1]} — "
                                             f"به چه شخصی شلیک می‌کنی؟ (شماره‌ی صندلی)")
                    except Exception:
                        pass
                    return
                if getattr(g, "sh_bow_aiming", None) == _bseat:
                    _bv = _deng_parse_strict(text, _sh_bow_targets(g))
                    if _bv is not None:
                        # 🏹 دفاع+تصمیم فقط برای اولین کمان‌دار و فقط یک‌بار؛
                        #    سپردارهای بعدی و تیرِ بعد از «عوض می‌کنم» فوری‌اند
                        if (getattr(g, "sh_bow_chain", []) or []) \
                                or getattr(g, "sh_bow_changed", False):
                            await _sh_arrow_fire(ctx, msg.chat.id, g, _bseat, _bv)
                        else:
                            await _sh_arrow_aim(ctx, msg.chat.id, g, _bseat, _bv)
                        return

    # 🏛 انتخابِ حریفِ دوئلِ معمار (هانیبال) — فقط دارندهٔ کارت، فقط بعد از دکمهٔ گاد
    if (_is_hanibal_scenario(g) and getattr(g, "hb_duel_pick_wait", False)
            and not getattr(g, "night_active", False)):
        _card = getattr(g, "hb_card_seat", None)
        if (_card is not None and _card in g.seats and uid == g.seats[_card][0]):
            _opp = _deng_parse_strict(text, [s for s in _alive_seats(g) if s != _card])
            if _opp is not None:
                await _hb_duel_begin(ctx, msg.chat.id, g, _opp)
                return

    # 💣 عددِ ترور (میتیک) — شروعش با دکمهٔ گاد است، نه نوشتنِ کفِ گروه.
    #    ⚠️ کلمهٔ راه‌انداز عمداً برداشته شده: هرکس می‌توانست «ترور» بنویسد و با
    #    بی‌اثر ماندنش ثابت کند تروریست نیست.
    if (_is_mythic_scenario(g) and getattr(g, "my_terror_asking", False)
            and not getattr(g, "night_active", False)):
        _tseat = _seat_of_uid(g, uid)
        if (_tseat is not None and _tseat not in (g.striked or set())
                and _my_role_is(g, _tseat, _R_MY_TERROR)):
            _tv = _deng_parse_strict(text, [s for s in _alive_seats(g) if s != _tseat])
            if _tv is not None:
                await _my_terror_apply(ctx, msg.chat.id, g, _tseat, _tv)
                return

    # 💣 عددِ یاغی (نماینده) — همان‌طور، شروعش فقط با دکمهٔ گاد است
    if (_is_nemayande_scenario(g) and getattr(g, "nem_yaghi_asking", False)
            and not getattr(g, "night_active", False)):
        _yseat = _seat_of_uid(g, uid)
        if (_yseat is not None and _yseat not in (g.striked or set())
                and _seat_role_norm(g, _yseat) == _R_YAGHI):
            _yv = _deng_parse_strict(text, [s for s in _alive_seats(g) if s != _yseat])
            if _yv is not None:
                await _nem_yaghi_apply(ctx, msg.chat.id, g, _yseat, _yv)
                return

    # 🔍 تشخیص سناریو/نقش‌ها (به پیوی گاد) — برای عیب‌یابی
    if text in ("/چک", "/تشخیص"):
        if await _is_god_or_admin(ctx, chat_id, uid, g):
            rep = _diag_scenario_report(g)
            try:
                await ctx.bot.send_message(g.god_id, rep, parse_mode="HTML")
                await msg.reply_text("🔍 گزارش تشخیص به پیوی گاد ارسال شد.")
            except Exception:
                await msg.reply_text("⚠️ نتوانستم به پیوی گاد بفرستم؛ گاد باید بات را استارت کند.")
        return

    # 🎭 شب معارفه (فقط گادِ فعلی)
    if text == "/معارفه":
        if uid == g.god_id:
            await do_maarefe(ctx, chat_id, g)
            try:
                await publish_seating(ctx, chat_id, g, mode=CTRL)  # 🔄 حذفِ دکمه‌ی معارفه از پنل
            except Exception:
                pass
        return

    # 🌙 شروع/پایان اکت‌گیریِ شب (فقط گادِ فعلی)
    if text == "/شب":
        if uid == g.god_id:
            if not await _night_blocked_for_open(ctx, chat_id, g):
                await start_night(ctx, chat_id, g)
        return

    if text == "/روز":
        if uid == g.god_id:
            await _do_day(ctx, chat_id, g)
        return

    # 🔓 باز کردن دستیِ چت اتاق مافیا وسط روز (+ سؤالِ بمبِ الیوت در گیمر) — فقط گاد
    if text == "/باز":
        if uid == g.god_id:
            await _do_room_open(ctx, chat_id, g)
        return

    # 🔒 بستن دستیِ چت اتاق مافیا — فقط گاد
    if text == "/بسته":
        if uid == g.god_id:
            await _do_room_close(ctx, chat_id, g)
        return


    # تغییر موضوع رویداد (گاد/ادمین) — بدون ریپلای
    if await _try_set_event_title(ctx, chat_id, uid, g, text):
        return

    # 📊 آمار من — هر بازیکنی در گروه فعال می‌تواند آمار خودش را ببیند
    if text == "آمار من":
        stats = load_player_stats() or {}
        p = stats.get(str(uid))
        if not p or (p.get("games", 0) == 0 and p.get("god_games", 0) == 0):
            await msg.reply_text("📭 هنوز آماری برای شما ثبت نشده است.")
        else:
            await msg.reply_text(format_player_stats(p), parse_mode="HTML")
        return

    # 🎮 بازی من — تاریخچه‌ی بازی‌های خودِ شخص (در گروه هم فعال)
    if text == "بازی من":
        rows = (load_game_history() or {}).get(str(uid), [])
        if not rows:
            await msg.reply_text("📭 از زمانِ فعال‌شدنِ تاریخچه، بازی‌ای برای شما ثبت نشده است.")
        else:
            await msg.reply_text(format_game_history(rows), parse_mode="HTML")
        return

    # 📊 آمار کل — لیدربرد بهترین‌های کل دوران (برای همه در هر گروه فعال)
    if text == "آمار کل":
        current = load_player_stats() or {}
        board = build_alltime_leaderboard_text(current)
        if not board:
            await msg.reply_text("📭 هنوز آماری ثبت نشده است.")
        else:
            await msg.reply_text(board, parse_mode="HTML")
        return

    if g.vote_type == "awaiting_time" and uid == g.god_id and _await_input_alive(g):
        g.event_time = text
        g.vote_type = None
        g.await_input_ts = None
        store.save()
        await publish_seating(ctx, chat_id, g, mode=_ui_mode(g))
        await ctx.bot.send_message(chat_id, f"✅ ساعت رویداد روی {text} تنظیم شد.")
        return


    # ثبت نام برای صندلی
    if uid in g.awaiting_name_input:
        seat_no = g.awaiting_name_input.pop(uid)

        import re
        if not re.match(r'^[\u0600-\u06FF\s]+$', text):
            await ctx.bot.send_message(chat_id, "❗ لطفاً نام را فقط با حروف فارسی وارد کنید.")
            return

        g.seats[seat_no] = (uid, text)
        g.user_names[uid] = text
        save_usernames_to_gist(g.user_names)
        store.save()

        if uid in g.last_name_prompt_msg_id:
            try:
                await ctx.bot.delete_message(
                    chat_id=chat_id,
                    message_id=g.last_name_prompt_msg_id[uid]
                )
            except:
                pass
            del g.last_name_prompt_msg_id[uid]

        await publish_seating(ctx, chat_id, g, mode=_ui_mode(g))
        return



    # -------------- defense seats by God ------------------
    # if g.vote_type == "awaiting_defense" and uid == g.god_id:
     #    nums = [int(n) for n in text.split() if n.isdigit() and int(n) in g.seats]

        # اگر ورودی معتبر نبود، پیام خطا بده و برگرد
       #  if not nums:
       #      await ctx.bot.send_message(chat_id, "❌ شماره صندلی معتبر وارد نشد. دوباره تلاش کنید (مثال: 1 3 5).")
           #  return

       #  g.defense_seats = nums
       #  g.vote_type = None  # ✅ غیرفعال کردن حالت وارد کردن صندلی دفاع

        # 🧹 حذف پیام درخواست صندلی‌های دفاع
       #  if g.defense_prompt_msg_id:
          #   try:
          #       await ctx.bot.delete_message(chat_id=chat_id, message_id=g.defense_prompt_msg_id)
          #   except:
          #       pass
          #   g.defense_prompt_msg_id = None

        # store.save()
         #await ctx.bot.send_message(chat_id, f"✅ صندلی‌های دفاع: {', '.join(map(str, nums))}")
        # await start_vote(ctx, chat_id, g, "final")
        # return

    if g.phase == "idle" and (not getattr(g, "awaiting_shuffle_decision", False)) and text.strip() == "کنسل":
        for seat, (player_uid, _) in list(g.seats.items()):
            if player_uid == uid:
                del g.seats[seat]
                store.save()
                await ctx.bot.send_message(chat_id, "❎ ثبت‌نام شما با موفقیت لغو شد.")
                await publish_seating(ctx, chat_id, g, mode=_ui_mode(g))
                break
        else:
            await ctx.bot.send_message(chat_id, "❗ شما در لیست نیستید.")
        return

    if hasattr(g, "adding_scenario_step") and g.adding_scenario_step:

        if uid != g.god_id:
            return


        if (datetime.now() - g.adding_scenario_last).total_seconds() > 300:
            g.adding_scenario_step = None
            g.adding_scenario_data = {}
            store.save()
            await ctx.bot.send_message(chat_id, "⏱ زمان شما تمام شد. اضافه کردن سناریو لغو شد.")
            return

        text = msg.text.strip()

        # مرحله ۱: نام سناریو
        if g.adding_scenario_step == "name":
            g.adding_scenario_data["name"] = text
            g.adding_scenario_step = "mafia"
            g.adding_scenario_last = datetime.now()
            store.save()
            await ctx.bot.send_message(chat_id, " ♠️ آیا نقش مافیا دارد؟ اگر بله، لیست را بفرستید (نقش ها را با / از هم جدا کنید). اگر نه، «خیر».")
            return

        # مرحله ۲: نقش مافیا
        if g.adding_scenario_step == "mafia":
            if text != "خیر":
                g.adding_scenario_data["mafia"] = [r.strip() for r in text.split("/") if r.strip()]
            else:
                g.adding_scenario_data["mafia"] = []
            g.adding_scenario_step = "citizen"
            g.adding_scenario_last = datetime.now()
            store.save()
            await ctx.bot.send_message(chat_id, "♥️ آیا نقش شهروند دارد؟ اگر بله، لیست را بفرستید (نقش ها را با / از هم جدا کنید). اگر نه، «خیر».")
            return

        # مرحله ۳: نقش شهروند
        if g.adding_scenario_step == "citizen":
            if text != "خیر":
                g.adding_scenario_data["citizen"] = [r.strip() for r in text.split("/") if r.strip()]
            else:
                g.adding_scenario_data["citizen"] = []
            g.adding_scenario_step = "indep"
            g.adding_scenario_last = datetime.now()
            store.save()
            await ctx.bot.send_message(chat_id, "♦️ آیا نقش مستقل دارد؟ اگر بله، لیست را بفرستید. اگر نه، «خیر».")
            return

        # مرحله ۴: نقش مستقل
        if g.adding_scenario_step == "indep":
            if text != "خیر":
                g.adding_scenario_data["indep"] = [r.strip() for r in text.split("/") if r.strip()]
            else:
                g.adding_scenario_data["indep"] = []
            g.adding_scenario_step = "cards"
            g.adding_scenario_last = datetime.now()
            store.save()
            await ctx.bot.send_message(chat_id, "♥️ آیا کارت دارد؟ اگر بله، لیست را بفرستید (نقش ها را با / از هم جدا کنید). اگر نه، «خیر».")
            return

        # مرحله ۵: کارت‌ها
        if g.adding_scenario_step == "cards":
            if text != "خیر":
                g.adding_scenario_data["cards"] = [r.strip() for r in text.split("/") if r.strip()]
            else:
                g.adding_scenario_data["cards"] = []

            # ✅ ذخیره در Gist
            name = g.adding_scenario_data["name"]
            mafia_roles   = g.adding_scenario_data["mafia"]
            citizen_roles = g.adding_scenario_data["citizen"]
            indep_roles   = g.adding_scenario_data["indep"]
            cards         = g.adding_scenario_data["cards"]

            # --- مافیا ---
            mafia_set = load_mafia_roles() or set()
            mafia_set |= set(mafia_roles)
            save_mafia_roles(mafia_set)

            # --- مستقل ---
            indep_map = load_indep_roles() or {}
            cur_indep = set(indep_map.get(name, []))
            cur_indep |= set(indep_roles)
            if cur_indep:
                indep_map[name] = sorted(cur_indep)
            save_indep_roles(indep_map)

            # --- کارت‌ها ---
            cards_map = load_cards() or {}
            cur_cards = set(cards_map.get(name, []))
            cur_cards |= set(cards)
            if cur_cards:
                cards_map[name] = sorted(cur_cards)
            save_cards(cards_map)

            # --- سناریو ---
            def list_to_counts(role_list):
                counts = {}
                for r in role_list:
                    counts[r] = counts.get(r, 0) + 1
                return counts

            mafia_counts   = list_to_counts(mafia_roles)
            citizen_counts = list_to_counts(citizen_roles)
            indep_counts   = list_to_counts(indep_roles)

            roles = {}
            roles.update(mafia_counts)
            roles.update(citizen_counts)
            roles.update(indep_counts)

            new_scenario = Scenario(name, roles)
            store.scenarios.append(new_scenario)
            store.save()
            save_scenarios_to_gist(store.scenarios)

            # پاکسازی وضعیت
            g.adding_scenario_step = None
            g.adding_scenario_data = {}
            store.save()

            await ctx.bot.send_message(chat_id, f"✅ سناریوی «{name}» با موفقیت ذخیره شد.")
            return

    # 🪑 ثبت‌نام با نوشتنِ «فقط عدد» وسطِ گروه — بدونِ ریپلای، بدونِ اسلش.
    #    ⚠️ عمداً آخرینِ همه‌ی شرط‌هاست: هر عددی که مالِ رأی/اکت/سناریوسازی باشد
    #    بالاتر گرفته و return شده؛ اینجا فقط عددهای «بی‌صاحبِ» زمانِ ثبت‌نام می‌رسند.
    if (g.phase == "idle"
            and not getattr(g, "awaiting_shuffle_decision", False)
            and not getattr(g, "awaiting_event_title", False)
            and getattr(g, "vote_type", None) != "awaiting_time"
            and uid not in (getattr(g, "awaiting_name_input", {}) or {})
            and uid not in (getattr(g, "waiting_name", {}) or {})):
        _bs = _parse_bare_seat(text)
        if _bs is not None and await _seat_take_by_number(ctx, chat_id, g, uid, _bs):
            return



async def handle_stats_request(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    now = datetime.now(timezone.utc).timestamp()
    day_ago = now - 86400  # 24 ساعت گذشته

    msg_lines = []
    running_groups = []
    recruiting_groups = []

    for gid, g in store.games.items():
        g: GameState
        stats = store.group_stats.get(gid, {})
        started = sum(1 for t in stats.get("started", []) if t > day_ago)
        ended = sum(1 for t in stats.get("ended", []) if t > day_ago)

        try:
            chat = await ctx.bot.get_chat(gid)
            if chat.username:
                name = f"<a href='https://t.me/{chat.username}'>{chat.title or chat.username}</a> (<code>{gid}</code>)"
                is_private = False
            else:
                name = f"{chat.title or 'گروه خصوصی'}  <code>{gid}</code>"
                is_private = True
        except:
            name = f"(گروه ناشناس) <code>{gid}</code>"
            is_private = True


        # وضعیت فعلی
        if g.phase == "playing":
            running_groups.append(name)
        elif (
            g.scenario and
            g.god_id and
            len(g.seats) < g.max_seats and
            g.phase != "playing"
        ):
            recruiting_groups.append(name)

        msg_lines.append(f"👥 {name}:\n⏺ {started} شروع\n⏹ {ended} پایان\n")

    final_msg = "\n".join(msg_lines)
    final_msg += "\n\n🎮 <b>گروه‌هایی که بازی فعال دارن:</b>\n" + ", ".join(running_groups or ["—"])
    final_msg += "\n\n🪑 <b>گروه‌هایی که در حال عضوگیری هستن:</b>\n" + ", ".join(recruiting_groups or ["—"])

    await ctx.bot.send_message(
        update.effective_chat.id,
        final_msg,
        parse_mode="HTML",
        disable_web_page_preview=True
    )

async def weekly_now_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """ارسال فوری آمار هفتگی به همهٔ گروه‌های فعال (فقط مدیر اصلی)."""
    if update.effective_user.id != 99347107:
        return
    result = await broadcast_weekly_stats(ctx.bot, force=True) or {}
    sent = result.get("sent", 0)
    reason = result.get("reason")

    if sent > 0:
        await update.message.reply_text(f"✅ آمار هفتگی به {sent} گروه فعال ارسال شد.")
    elif reason == "no_data":
        await update.message.reply_text(
            "📭 هنوز هیچ بازی تمام‌شده‌ای ثبت نشده، پس آماری برای ارسال وجود ندارد.\n"
            "ابتدا یک بازی کامل تا اعلام برنده انجام بده."
        )
    elif reason == "no_activity":
        await update.message.reply_text("ℹ️ آماری برای نمایش وجود دارد ولی ارسال نشد.")
    elif not store.active_groups:
        await update.message.reply_text("⚠️ هیچ گروه فعالی وجود ندارد (active_groups خالی است).")
    else:
        await update.message.reply_text("⚠️ ارسال انجام نشد — به لاگ‌ها نگاه کن.")


async def sendtoall_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """ریپلای روی یک پیام در پی‌وی + /sendtoall → ارسال همان پیام به همهٔ گروه‌های فعال."""
    if update.effective_user.id != 99347107:
        return
    if update.effective_chat.type != "private":
        await update.message.reply_text("⚠️ این دستور را فقط در پی‌وی بات بزن.")
        return

    replied = update.message.reply_to_message
    if not replied:
        await update.message.reply_text(
            "❗ روی پیامی که می‌خواهی به همهٔ گروه‌ها بفرستی ریپلای کن و بعد /sendtoall را بزن."
        )
        return

    if not store.active_groups:
        await update.message.reply_text("⚠️ هیچ گروه فعالی وجود ندارد.")
        return

    sent = 0
    failed = 0
    pin = True   # 📌 همیشه پین شود
    for chat_id in list(store.active_groups):
        try:
            msg = await ctx.bot.copy_message(
                chat_id=chat_id,
                from_chat_id=update.effective_chat.id,
                message_id=replied.message_id,
            )
            if pin:
                try:
                    await ctx.bot.pin_chat_message(
                        chat_id, msg.message_id, disable_notification=True
                    )
                except Exception:
                    pass
            sent += 1
        except Exception as e:
            failed += 1
            print(f"⚠️ sendtoall failed for {chat_id}:", e)

    report = f"✅ پیام به {sent} گروه ارسال شد."
    if pin:
        report += " (سنجاق شد)"
    if failed:
        report += f"\n⚠️ {failed} گروه ناموفق بود."
    await update.message.reply_text(report)


async def channel_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/channel — تنظیمِ چنلِ آرشیوِ بازی‌ها (فقط مدیر اصلی، در پی‌وی).
    /channel @name یا -100…  → ثبت | /channel off → حذف | /channel → نمایش"""
    if update.effective_user.id != ADMIN_ID:
        return
    if update.effective_chat.type != "private":
        await update.message.reply_text("⚠️ این دستور را فقط در پی‌وی بات بزن.")
        return

    arg = " ".join(ctx.args).strip() if ctx.args else ""
    st = dict(load_bot_settings(force=True) or {})

    if not arg:
        cur = st.get("archive_channel")
        if cur:
            await update.message.reply_text(
                f"📢 چنلِ آرشیو: <code>{escape(str(cur), quote=False)}</code>\n\n"
                "برای تغییر: <code>/channel @نام‌چنل</code>\nبرای حذف: <code>/channel off</code>",
                parse_mode="HTML")
        else:
            await update.message.reply_text(
                "📢 هنوز چنلی تنظیم نشده.\n\n"
                "۱) بات را در چنل <b>ادمین</b> کن (دسترسیِ ارسال پیام)\n"
                "۲) بعد اینجا بزن: <code>/channel @نام‌چنل</code>\n"
                "   (چنلِ خصوصی؟ آیدیِ عددی‌اش را بده، مثل <code>-1001234567890</code>)",
                parse_mode="HTML")
        return

    if arg in ("off", "حذف", "خاموش", "-"):
        st.pop("archive_channel", None)
        save_bot_settings(st)
        await update.message.reply_text("🚫 آرشیو در چنل خاموش شد.")
        return

    target = arg if arg.startswith("@") else arg
    try:
        target = int(arg)          # آیدیِ عددی
    except ValueError:
        if not target.startswith("@"):
            target = "@" + target

    # تستِ واقعی: یک پیام بفرست تا مطمئن شویم بات ادمین است
    try:
        await ctx.bot.send_message(target, "✅ این چنل به‌عنوان آرشیوِ بازی‌های مافیا ثبت شد.")
    except Exception as e:
        await update.message.reply_text(
            f"❌ نشد پیام بفرستم:\n<code>{escape(str(e), quote=False)}</code>\n\n"
            "مطمئن شو بات در چنل <b>ادمین</b> است و اسم/آیدی درست است.",
            parse_mode="HTML")
        return

    st["archive_channel"] = target
    save_bot_settings(st)
    await update.message.reply_text(
        f"✅ ثبت شد. از این به بعد بعد از هر بازی، لیستِ پایانی + گزارشِ شب‌به‌شب + "
        f"کارنامه‌ی امتیاز به <code>{escape(str(target), quote=False)}</code> می‌رود.",
        parse_mode="HTML")


async def season_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """/season → گزارشِ صدرِ جدول و چکِ دستیِ پایانِ فصل (فقط مدیر اصلی، در پی‌وی).
    اگر کسی به سقف رسیده باشد: مدال + ریست + اعلان در همهٔ گروه‌ها."""
    if update.effective_user.id != ADMIN_ID:
        return
    if update.effective_chat.type != "private":
        await update.message.reply_text("⚠️ این دستور را فقط در پی‌وی بات بزن.")
        return

    stats = load_player_stats()
    if not stats:
        await update.message.reply_text("⚠️ آماری برای بررسی نیست (یا خواندن از گیست ناموفق بود).")
        return

    def _fl(v):
        f = float(v)
        return str(int(f)) if f.is_integer() else f"{f:.1f}"

    # همان کلیدِ رتبه‌بندیِ «آمار کل» و مدال‌ها: فقط مجموعِ امتیاز (برد برای تساوی)
    rows = sorted(((u, d, _season_total(d)) for u, d in stats.items()),
                  key=lambda it: (it[2], it[1].get("wins", 0)), reverse=True)[:5]
    head = [f"🏁 <b>وضعیت فصل</b> — سقف: <b>{int(SEASON_TARGET)}</b>", ""]
    for i, (_u, d, t) in enumerate(rows, 1):
        mb = _medal_badges(d)
        head.append(f"{i}. {escape(d.get('name', 'بازیکن'), quote=False)}"
                    f"{(' ' + mb) if mb else ''} — {_fl(t)}")
    await update.message.reply_text("\n".join(head), parse_mode="HTML")

    date_str = jdatetime.date.today().strftime("%Y/%m/%d")
    try:
        msg = _season_check_and_reset(stats, date_str=date_str)
    except Exception as e:
        await update.message.reply_text(f"❌ خطا در چکِ فصل: {e}")
        return

    if not msg:
        gap = SEASON_TARGET - (rows[0][2] if rows else 0)
        await update.message.reply_text(
            f"✅ هنوز کسی به سقف نرسیده — تا پایانِ فصل <b>{_fl(max(0, gap))}</b> امتیاز مانده.",
            parse_mode="HTML")
        return

    save_player_stats(stats)
    await _broadcast_season_end(ctx.bot, msg)
    await update.message.reply_text("🏁 فصل بسته شد؛ مدال‌ها ثبت و اعلان در همهٔ گروه‌ها فرستاده شد.")


async def start_selected_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """شروع دستی دور لیست منتخب (برای تست) — فقط مدیر اصلی."""
    if update.effective_user.id != ADMIN_ID:
        return
    result = await launch_selected_round(ctx.bot)
    sent_names = result.get("sent", [])
    failed = result.get("failed", [])

    if not sent_names and not failed:
        await update.message.reply_text("⚠️ کاندیدایی پیدا نشد.")
        return

    lines = [f"✅ دعوت لیست منتخب به {len(sent_names)} نفر ارسال شد:"]
    for i, nm in enumerate(sent_names, 1):
        lines.append(f"{i}. {escape(nm, quote=False)}")
    if failed:
        lines.append("")
        lines.append(f"⚠️ به {len(failed)} نفر نرسید (بات را استارت نکرده‌اند):")
        for nm in failed:
            lines.append(f"• {escape(nm, quote=False)}")

    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


async def selected_report_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """گزارش وضعیت لیست منتخب — فقط مدیر اصلی."""
    if update.effective_user.id != ADMIN_ID:
        return
    sl = load_selected_list()
    if not sl.get("candidates"):
        await update.message.reply_text("هنوز دور لیست منتخبی شروع نشده است.")
        return
    await update.message.reply_text(build_selected_report(sl), parse_mode="HTML")


async def leave_group(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    if user_id != 99347107:
        await update.message.reply_text("⛔ فقط مدیر اصلی بات اجازه دارد این دستور را اجرا کند.")
        return

    if not ctx.args:
        await update.message.reply_text("لطفاً Chat ID گروه را وارد کنید.")
        return

    try:
        chat_id = int(ctx.args[0])
        await ctx.bot.leave_chat(chat_id)
        await update.message.reply_text(f"✅ بات از گروه {chat_id} خارج شد.")
    except Exception as e:
        await update.message.reply_text(f"❌ خطا در خروج از گروه: {e}")

# همان مدیرانِ اصلی — برای فعال/غیرفعال کردنِ گروه (لیست بالا تعریف شده)
OWNER_IDS = SUPER_ADMINS


async def activate_group(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    if chat.type not in {"group", "supergroup"}:
        await update.message.reply_text("این دستور فقط در گروه‌ها قابل استفاده است.")
        return

    user_id = update.effective_user.id
    if user_id not in OWNER_IDS:
        await update.message.reply_text("⛔ فقط ادمین‌های اصلی می‌تونن گروه رو فعال کنن.")
        return

    store.active_groups.add(chat.id)
    store.save()
    ok = save_active_groups(store.active_groups)
    if not ok:
        await update.message.reply_text("⚠️ گروه فعال شد، اما ذخیره در Gist ناموفق بود.")
        return

    await update.message.reply_text("✅ این گروه با موفقیت فعال شد.")


async def deactivate_group(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    if chat.type not in {"group", "supergroup"}:
        await update.message.reply_text("این دستور فقط در گروه‌ها قابل استفاده است.")
        return

    user_id = update.effective_user.id
    if user_id not in OWNER_IDS:
        await update.message.reply_text("⛔ فقط ادمین‌های اصلی می‌تونن گروه رو غیرفعال کنن.")
        return

    if chat.id in store.active_groups:
        store.active_groups.remove(chat.id)
        store.save()
        ok = save_active_groups(store.active_groups)
        if not ok:
            await update.message.reply_text("⚠️ گروه از لیست محلی حذف شد، ولی ذخیره در Gist ناموفق بود.")
            return
        await update.message.reply_text("🛑 این گروه غیرفعال شد و از Gist هم پاک شد.")
    else:
        await update.message.reply_text("ℹ️ این گروه از قبل فعال نبود.")


async def set_event_cmd(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat_id_int = update.effective_chat.id
    chat_id = str(chat_id_int)
    g = gs(chat_id_int)

    if update.effective_user.id != g.god_id:
        await update.message.reply_text("❌ فقط راوی می‌تواند شماره ایونت را تغییر دهد.")
        return

    if not ctx.args or not ctx.args[0].isdigit():
        await update.message.reply_text("⚠️ استفاده صحیح: /setevent <شماره>")
        return

    num = int(ctx.args[0])

    # ✅ به جای load/save خام، از کش استفاده کن و همون رو به‌روز کن
    nums = get_event_numbers()             # ← از کش می‌خوانیم
    nums[chat_id] = num                    # ← کش را بلافاصله به‌روز می‌کنیم
    save_event_numbers(nums)               # ← سپس یک PATCH به Gist

    # حالا لیست را ادیت کن؛ چون کش به‌روز شده، متن جدید می‌شود
    try:
        mode = CTRL if g.phase != "idle" else REG
        await publish_seating(ctx, chat_id_int, g, mode=mode)
    except Exception:
        pass

    await update.message.reply_text(f"✅ شماره ایونت برای این گروه روی {num} تنظیم شد.")


