async def sub_command(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat_id = update.effective_chat.id
    g = gs(chat_id)


    if update.effective_user.id != g.god_id:
        await update.message.reply_text("⚠️ فقط راوی می‌تواند جایگزین کند.")
        return


    if not update.message.reply_to_message or not update.message.reply_to_message.from_user:
        await update.message.reply_text("⚠️ لطفاً روی پیام بازیکن جدید ریپلای کنید.")
        return

    new_uid = update.message.reply_to_message.from_user.id
    if blocked_info(new_uid):
        await update.message.reply_text("⛔ این بازیکن از بات محروم است و نمی‌تواند جایگزین شود.")
        return
    _sb = seat_ban_info(new_uid)
    if _sb:
        await update.message.reply_text(
            f"⛔ این بازیکن به‌خاطر {KICK_BAN_LIMIT} بار کیک، "
            f"{seat_ban_days_left(_sb)} روز دیگر حقِ نشستن در لیست ندارد.\n"
            f"(برای رفعش، روی پیامش «رفع محرومیت» بنویس.)")
        return
    new_name = g.user_names.get(new_uid, "ناشناس")


    parts = update.message.text.strip().split()
    if len(parts) < 2 or not parts[1].isdigit():
        await update.message.reply_text("⚠️ فرمت درست: /sub <شماره صندلی>")
        return

    seat_no = int(parts[1])
    if seat_no not in g.seats:
        await update.message.reply_text(f"⚠️ صندلی {seat_no} وجود ندارد.")
        return


    role = g.assigned_roles.get(seat_no)
    old_uid, _old_name = g.seats[seat_no]

    g.seats[seat_no] = (new_uid, new_name)
    store.save()
    await publish_seating(ctx, chat_id, g, mode=CTRL)

    # 🔗 اتاق مافیا: اگر صندلیِ جایگزین‌شده مافیاست → قدیمی بیرون + لینکِ نو برای جدید
    if getattr(g, "mafia_room_id", None) and seat_no in _mafia_room_seats(g):
        if old_uid in (g.mafia_room_members or set()):
            await _room_kick(ctx, g, old_uid)
            g.mafia_room_members.discard(old_uid)
            await _room_rotate_link(ctx, g)   # لینکِ قبلی باطل تا قدیمی برنگردد
        await _room_send_link(ctx, g, new_uid)


    stickers = load_stickers()
    if role in stickers:
        try:
            await ctx.bot.send_sticker(new_uid, stickers[role])
        except:
            pass
    try:
        await ctx.bot.send_message(new_uid, f"🎭 نقش شما: {role}")
    except telegram.error.Forbidden:
        await update.message.reply_text("⚠️ نتونستم نقش رو به پیوی بفرستم (پی‌وی بسته است).")


    if new_name == "ناشناس":
        prompt = await ctx.bot.send_message(
            chat_id,
            f"✏️ این پیام را ریپلای کنید و نام جدید خود را برای صندلی {seat_no} به فارسی وارد کنید:"
        )
        _start_name_wait(ctx, chat_id, g, new_uid, seat_no, prompt)

    await update.message.reply_text(f"✅ بازیکن جدید جایگزین صندلی {seat_no} شد.")

async def cmd_lists(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    uid = update.effective_user.id
    g = gs(chat.id)

    # فقط ادمین‌های گروه اجازه داشته باشن
    try:
        member = await ctx.bot.get_chat_member(chat.id, uid)
        if member.status not in ("administrator", "creator"):
            await ctx.bot.send_message(chat.id, "⚠️ فقط ادمین‌ها می‌توانند این دستور را بزنند.")
            return
    except Exception:
        pass

    if not hasattr(g, "last_snapshot"):
        await ctx.bot.send_message(chat.id, "❌ لیست قبلی ذخیره نشده است.")
        return

    try:
        kb = InlineKeyboardMarkup.de_json(g.last_snapshot["kb"], ctx.bot)
    except Exception:
        kb = None

    # 🧹 اگر لیستِ قبلی هنوز در گروه هست، پاکش کن تا گروه شلوغ نشود
    _old = getattr(g, "last_seating_msg_id", None)
    if _old:
        try:
            await ctx.bot.delete_message(chat_id=chat.id, message_id=_old)
        except Exception:
            pass   # قبلاً پاک شده یا قابلِ حذف نیست → عادی ادامه بده
        g.last_seating_msg_id = None

    # 📜 ارسال لیست بازیابی‌شده
    msg = await ctx.bot.send_message(
        chat.id,
        g.last_snapshot["text"],
        parse_mode="HTML",
        reply_markup=kb
    )

    # ✅ به‌روزرسانی آیدی پیام فعال
    g.last_seating_msg_id = msg.message_id
    store.save()

    # 📜 لیست نقش‌های سناریو، درست زیرِ لیستِ بازیکنان
    try:
        _rt = scenario_roles_text(g)
        if _rt:
            # 🧹 نسخهٔ قبلیِ لیستِ نقش‌ها را بردار تا دوتایی نماند
            _oldr = getattr(g, "last_roles_msg_id", None)
            if _oldr:
                try:
                    await ctx.bot.delete_message(chat_id=chat.id, message_id=_oldr)
                except Exception:
                    pass
            _rmsg = await ctx.bot.send_message(chat.id, _rt, parse_mode="HTML")
            g.last_roles_msg_id = _rmsg.message_id
            g.last_roles_scenario_name = g.scenario.name
            store.save()
    except Exception as e:
        print(f"⚠️ ارسال لیست نقش‌ها در /list: {e}")

    # 📌 پین کردن پیام (اختیاری ولی پیشنهاد می‌شود)
    try:
        await ctx.bot.pin_chat_message(
            chat_id=chat.id,
            message_id=msg.message_id,
            disable_notification=True
        )
    except Exception as e:
        print(f"⚠️ خطا در پین کردن لیست بازیابی‌شده: {e}")



# ═══════════ 🎙 صدای سفارشیِ گادِ صوتی (آپلود در پیویِ سازنده) ═══════════
# سازنده در پیوی یک وویس می‌فرستد → می‌پرسیم برای کدام جمله → دانلود، تبدیل به PCM،
# ذخیره‌ی محلی + ثبتِ file_id در گیست. چون دیسکِ رندر پاک‌شدنی است، بعد از هر
# بالا آمدن صداها از روی file_id دوباره دانلود می‌شوند.
VOICE_CUSTOM_FILENAME = "voice_custom.json"
VOICE_PHRASE_LABELS = {
    "time_up":        "تایم تمام شد",
    "time_up_again":  "تکرار تایم",
    "day":            "روز شد",
    "night":          "شب شد",
    "temp_night":     "شب موقت",
    "temp_night_end": "پایان شب موقت",
    "yakuza":         "یاکوزایی",
    "nato":           "ناتویی",
    "jalad":          "جلادی",
    "maarefe":        "معارفه",
    "mine_on":        "مین فعال شد",
}
_VOICE_PENDING: dict[int, str] = {}        # uid → file_id منتظرِ انتخابِ جمله
_VOICE_PENDING_VOTE: dict[int, str] = {}   # uid → file_id منتظرِ شمارهٔ صندلی (رأی‌گیری)
VOTE_SEAT_MAX = 20
_FA_DIGITS = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")


def _voice_key_label(key: str):
    """برچسبِ فارسیِ یک کلیدِ صدا — None اگر کلید معتبر نباشد."""
    if key in VOICE_PHRASE_LABELS:
        return VOICE_PHRASE_LABELS[key]
    if key == "vote_prefix":
        return "رأی‌گیری برای (پیشوند)"
    m = re.match(r"^vote_(\d{1,2})$", key or "")
    if m and 1 <= int(m.group(1)) <= VOTE_SEAT_MAX:
        return f"رأی‌گیری صندلی {m.group(1)}"
    return None


def load_voice_custom() -> dict | None:
    try:
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        r = httpx.get(GIST_API_URL, headers=headers, timeout=15.0)
        if r.status_code != 200:
            return None
        f = (r.json().get("files", {}) or {}).get(VOICE_CUSTOM_FILENAME)
        if not f:
            return {}
        return json.loads(f.get("content") or "{}") or {}
    except Exception as e:
        print("❌ load_voice_custom:", e)
        return None


def save_voice_custom(data: dict) -> bool:
    try:
        headers = {"Authorization": f"token {GH_TOKEN}", "Accept": "application/vnd.github+json"}
        r = httpx.patch(GIST_API_URL, headers=headers, timeout=20.0,
                        json={"files": {VOICE_CUSTOM_FILENAME: {
                            "content": json.dumps(data, ensure_ascii=False, indent=2)}}})
        return r.status_code in (200, 201)
    except Exception as e:
        print("❌ save_voice_custom:", e)
        return False


def _voice_label_key(text: str):
    """متنِ فارسی → کلید. «رأی‌گیری برای» → vote_prefix | «رأی‌گیری صندلی ۳» → vote_3"""
    t = _nz(text or "")
    for k, lbl in VOICE_PHRASE_LABELS.items():
        if _nz(lbl) == t:
            return k
    tt = t.replace("أ", "ا")          # رأی / رای
    if tt in (_nz("رای‌گیری برای"), _nz("رای‌گیری برای (پیشوند)"), _nz("پیشوند رای‌گیری")):
        return "vote_prefix"
    m = re.match(r"^رایگیری(?:برای)?(?:صندلی|سیت)?([0-9۰-۹٠-٩]{1,2})$", tt)
    if m:
        n = int(m.group(1).translate(_FA_DIGITS))
        if 1 <= n <= VOTE_SEAT_MAX:
            return f"vote_{n}"
    return None


async def _voice_install_from_file_id(bot, key: str, file_id: str) -> tuple[bool, str]:
    """دانلود از تلگرام + تبدیل + ذخیره‌ی محلی. (موفق؟, مسیر یا پیامِ خطا)"""
    try:
        f = await bot.get_file(file_id)
        data = bytes(await f.download_as_bytearray())
    except Exception as e:
        return False, f"دانلود از تلگرام ناموفق: {e}"
    raw = await voice_god.convert_to_raw(data)
    if not raw:
        return False, "تبدیلِ صدا ناموفق بود (ffmpeg در دسترس نیست یا فایل خراب است)."
    return True, voice_god.save_custom(key, raw)


async def _voice_custom_restore(bot):
    """🔄 بعد از هر بالا آمدن: صداهای سفارشی از روی file_id دوباره نصب می‌شوند."""
    try:
        data = await asyncio.to_thread(load_voice_custom)
        if not data:
            return
        n = 0
        for key, rec in data.items():
            fid = (rec or {}).get("file_id")
            if _voice_key_label(key) and fid:
                ok, res = await _voice_install_from_file_id(bot, key, fid)
                if ok:
                    n += 1
                else:
                    print(f"⚠️ صدای سفارشیِ «{key}» بازیابی نشد: {res}")
        print(f"🎙 صداهای سفارشی بازیابی شد: {n}/{len(data)}")
    except Exception as e:
        print("⚠️ voice custom restore:", e)


def _voice_pick_kb():
    rows = [[InlineKeyboardButton(lbl, callback_data=f"vset_{k}")]
            for k, lbl in VOICE_PHRASE_LABELS.items()]
    rows.append([InlineKeyboardButton("🗳 رأی‌گیری برای صندلیِ …", callback_data="vset_vote")])
    rows.append([InlineKeyboardButton("🗳 رأی‌گیری برای (فقط پیشوند)", callback_data="vset_vote_prefix")])
    rows.append([InlineKeyboardButton("🚫 انصراف", callback_data="vset_cancel")])
    return InlineKeyboardMarkup(rows)


async def _voice_install_and_record(ctx, uid: int, key: str, fid: str):
    """نصبِ صدا برای یک کلید + ثبتِ file_id در گیست + گزارش به سازنده."""
    lbl = _voice_key_label(key) or key
    ok, res = await _voice_install_from_file_id(ctx.bot, key, fid)
    if not ok:
        await ctx.bot.send_message(uid, f"⛔ {res}")
        return
    cur = await asyncio.to_thread(load_voice_custom)
    if cur is None:
        await ctx.bot.send_message(
            uid, f"⚠️ صدای «{lbl}» نصب شد ولی فهرستِ گیست خوانده نشد — بعد از ری‌استارت می‌پرد؛ دوباره بفرست.")
        return
    cur[key] = {"file_id": fid, "label": lbl,
                "at": datetime.now(timezone.utc).timestamp()}
    saved = await asyncio.to_thread(save_voice_custom, cur)
    note = "" if saved else "\n⚠️ ذخیره در گیست ناموفق — بعد از ری‌استارت می‌پرد؛ دوباره بفرست."
    await ctx.bot.send_message(
        uid, f"✅ صدای «{lbl}» ثبت شد — از همین الان به‌جای صدای پیش‌فرض پخش می‌شود.{note}")


async def handle_voice_upload_pm(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """🎙 سازنده در پیوی یک وویس/فایلِ صوتی می‌فرستد → می‌پرسیم برای کدام جمله."""
    msg = update.message
    if not msg or not msg.from_user or msg.from_user.id != ADMIN_ID:
        return
    media = msg.voice or msg.audio
    if not media:
        return
    _VOICE_PENDING[msg.from_user.id] = media.file_id
    await msg.reply_text("🎙 این صدا برای کدام جمله است؟", reply_markup=_voice_pick_kb())


async def handle_voice_set_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    uid = q.from_user.id
    data = q.data or ""
    if uid != ADMIN_ID:
        await safe_q_answer(q)
        return
    mid = q.message.message_id if q.message else None
    if data == "vset_cancel":
        _VOICE_PENDING.pop(uid, None)
        await safe_q_answer(q)
        try:
            await ctx.bot.edit_message_text(chat_id=uid, message_id=mid, text="🚫 لغو شد.")
        except Exception:
            pass
        return
    key = data[len("vset_"):]
    # 🗳 رأی‌گیری برای صندلیِ … → شمارهٔ صندلی را با متن می‌پرسیم
    if key == "vote":
        fid = _VOICE_PENDING.pop(uid, None)
        if not fid:
            await safe_q_answer(q, "اول وویس را بفرست، بعد جمله را انتخاب کن.", show_alert=True)
            return
        _VOICE_PENDING_VOTE[uid] = fid
        await safe_q_answer(q)
        try:
            await ctx.bot.edit_message_text(
                chat_id=uid, message_id=mid,
                text=f"🗳 این صدا برای رأی‌گیریِ کدام صندلی است؟ فقط شماره را بنویس (۱ تا {VOTE_SEAT_MAX}).")
        except Exception:
            pass
        return
    lbl = _voice_key_label(key)
    if lbl is None:
        await safe_q_answer(q)
        return
    fid = _VOICE_PENDING.pop(uid, None)
    if not fid:
        await safe_q_answer(q, "اول وویس را بفرست، بعد جمله را انتخاب کن.", show_alert=True)
        return
    await safe_q_answer(q)
    try:
        await ctx.bot.edit_message_text(chat_id=uid, message_id=mid, text=f"⏳ «{lbl}» در حالِ تبدیل…")
    except Exception:
        pass
    await _voice_install_and_record(ctx, uid, key, fid)


async def handle_voice_seat_number_pm(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """🗳 شمارهٔ صندلی بعد از «رأی‌گیری برای صندلیِ …» — فقط وقتی وویسی معلق باشد."""
    msg = update.message
    if not msg or not msg.from_user or msg.from_user.id != ADMIN_ID:
        return
    uid = msg.from_user.id
    if uid not in _VOICE_PENDING_VOTE:
        return
    try:
        n = int((msg.text or "").strip().translate(_FA_DIGITS))
    except ValueError:
        return
    if not (1 <= n <= VOTE_SEAT_MAX):
        await msg.reply_text(f"⚠️ شماره باید بین ۱ تا {VOTE_SEAT_MAX} باشد.")
        return
    fid = _VOICE_PENDING_VOTE.pop(uid)
    await msg.reply_text(f"⏳ «رأی‌گیری صندلی {n}» در حالِ تبدیل…")
    await _voice_install_and_record(ctx, uid, f"vote_{n}", fid)


async def handle_voice_text_pm(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """«صداها» → فهرست | «حذف صدا <جمله>» → برگشت به صدای پیش‌فرض"""
    msg = update.message
    if not msg or not msg.from_user or msg.from_user.id != ADMIN_ID:
        return
    text = (msg.text or "").strip()
    if _nz(text) == _nz("صداها"):
        cur = await asyncio.to_thread(load_voice_custom)
        lines = ["🎙 <b>صداهای گادِ صوتی</b>", ""]
        for k, lbl in VOICE_PHRASE_LABELS.items():
            if (cur or {}).get(k):
                st = "سفارشی ✅" if voice_god.has_custom(k) else "سفارشی ⏳ (هنوز دانلود نشده)"
            else:
                st = "پیش‌فرض"
            lines.append(f"• {escape(lbl, quote=False)} — {st}")
        # 🗳 رأی‌گیری
        pref = "سفارشی ✅" if (cur or {}).get("vote_prefix") else "پیش‌فرض"
        seats = sorted(int(k[5:]) for k in (cur or {}) if re.match(r"^vote_\d+$", k))
        lines.append(f"• رأی‌گیری برای (پیشوند) — {pref}")
        lines.append("• رأی‌گیری صندلی‌ها — سفارشیِ کامل: "
                     + ("، ".join(map(str, seats)) if seats else "هیچ")
                     + " (بقیه: پیشوند + شمارهٔ پیش‌فرض)")
        lines += ["", "<i>عوض کردن: یک وویس بفرست و جمله را انتخاب کن.",
                  "برگشت به پیش‌فرض: «حذف صدا تایم تمام شد» یا «حذف صدا رأی‌گیری صندلی ۳»</i>"]
        await msg.reply_text("\n".join(lines), parse_mode="HTML")
        return
    m = re.match(r"^\s*حذف\s*صدا\s*(.*)$", text)
    if not m:
        return
    key = _voice_label_key(m.group(1))
    if key is None:
        await msg.reply_text("⚠️ کدام جمله؟ یکی از این‌ها:\n• " + "\n• ".join(VOICE_PHRASE_LABELS.values())
                             + "\n• رأی‌گیری برای (پیشوند)\n• رأی‌گیری صندلی ۳")
        return
    lbl = _voice_key_label(key) or key
    cur = await asyncio.to_thread(load_voice_custom)
    if cur is None:
        await msg.reply_text("⚠️ فهرستِ گیست خوانده نشد — کمی بعد دوباره امتحان کن.")
        return
    had = cur.pop(key, None) is not None
    voice_god.remove_custom(key)
    if had and not await asyncio.to_thread(save_voice_custom, cur):
        await msg.reply_text("⚠️ فایلِ محلی پاک شد ولی ذخیره در گیست ناموفق بود — بعد از ری‌استارت برمی‌گردد.")
        return
    await msg.reply_text(f"↩️ «{lbl}» به صدای پیش‌فرض برگشت." if had else f"ℹ️ «{lbl}» صدای سفارشی نداشت.")


async def main():
    app = ApplicationBuilder().token(TOKEN).build()
    app.add_error_handler(on_error)
    # ⛔ دروازهٔ محرومیتِ کامل — گروهِ منفی یعنی قبل از همهٔ هندلرهای دیگر
    app.add_handler(TypeHandler(Update, blocked_gate), group=-1)
    # 🎙 صدای سفارشیِ گادِ صوتی — فقط پیویِ سازنده؛ قبل از هندلرهای عمومیِ پیوی
    app.add_handler(MessageHandler(
        filters.ChatType.PRIVATE & (filters.VOICE | filters.AUDIO) & filters.User(ADMIN_ID),
        handle_voice_upload_pm))
    app.add_handler(MessageHandler(
        filters.ChatType.PRIVATE & filters.TEXT & filters.User(ADMIN_ID)
        & filters.Regex(r"^\s*(صداها|حذف\s*صدا\b.*)\s*$"),
        handle_voice_text_pm))
    # 🗳 شمارهٔ صندلی بعد از «رأی‌گیری برای صندلیِ …» — گروهِ جدا تا با بقیهٔ پیوی تداخل نکند
    app.add_handler(MessageHandler(
        filters.ChatType.PRIVATE & filters.TEXT & filters.User(ADMIN_ID)
        & filters.Regex(r"^\s*[0-9۰-۹٠-٩]{1,2}\s*$"),
        handle_voice_seat_number_pm), group=2)
    app.add_handler(CommandHandler("start", start_welcome, filters=filters.ChatType.PRIVATE))
    app.add_handler(
        MessageHandler(
            filters.ChatType.PRIVATE & filters.TEXT
            & filters.Regex(
                r"^\s*(?:\S+\s+)?(آمار من|آمار کل|آمار هفتگی|بازی من|پنل مدیریت)\s*$"),
            handle_stats_pm
        )
    )
    # ✍️ جمله‌ی معارفه‌ی دن‌کارلئونه (سناریو گیمر) — هر متن پیوی که پرچمش فعال باشد
    app.add_handler(
        MessageHandler(
            filters.ChatType.PRIVATE & filters.TEXT & ~filters.COMMAND,
            handle_don_sentence_pm
        )
    )
    app.add_handler(CommandHandler("addroom", addroom_cmd, filters=group_filter))
    app.add_handler(CommandHandler("delroom", delroom_cmd, filters=group_filter))
    app.add_handler(CommandHandler("rooms", rooms_status_cmd,
                                   filters=filters.ChatType.PRIVATE & filters.User(ADMIN_ID)))
    app.add_handler(CommandHandler("active", activate_group))
    app.add_handler(CommandHandler("deactivate", deactivate_group))
    app.add_handler(CommandHandler("weekly", weekly_now_cmd))
    app.add_handler(CommandHandler("sendtoall", sendtoall_cmd, filters=filters.ChatType.PRIVATE))
    app.add_handler(CommandHandler("season", season_cmd, filters=filters.ChatType.PRIVATE))
    app.add_handler(CommandHandler("channel", channel_cmd, filters=filters.ChatType.PRIVATE))
    app.add_handler(CommandHandler("startselected", start_selected_cmd, filters=filters.ChatType.PRIVATE))
    app.add_handler(CommandHandler("selected", selected_report_cmd, filters=filters.ChatType.PRIVATE))
    # 👉 اضافه کردن هندلرها
    app.add_handler(CommandHandler("newgame", newgame, filters=group_filter))
    app.add_handler(CommandHandler("leave", leave_group, filters=filters.ChatType.PRIVATE & filters.User(99347107)))

    # 🪑 انتخاب صندلی با دستور مثل /3
    app.add_handler(
        MessageHandler(
            filters.Regex(r"^/\d+(@PouriaMafiaBot)?$") & filters.ChatType.GROUPS,
            handle_simple_seat_command
        )
    )
    app.add_handler(CommandHandler("resetgame", resetgame_cmd, filters=group_filter))
    # 🔒 مدیریتِ سناریو/نقش/کارت — فقط ادمینِ اصلیِ بات
    _owner = filters.User(ADMIN_ID)
    app.add_handler(CommandHandler("addscenario", addscenario, filters=_owner))
    app.add_handler(CommandHandler("listscenarios", list_scenarios, filters=_owner))
    app.add_handler(CommandHandler("removescenario", remove_scenario, filters=_owner))
    app.add_handler(CommandHandler("moveuser", cmd_moveuser, filters=_owner))
    app.add_handler(CommandHandler("addmafia", cmd_addmafia, filters=_owner))
    app.add_handler(CommandHandler("listmafia", cmd_listmafia, filters=_owner))
    app.add_handler(CommandHandler("list", cmd_lists, filters=group_filter))
    app.add_handler(CommandHandler("addcard", add_card, filters=_owner))
    app.add_handler(CommandHandler("listcard", list_cards, filters=_owner))
    app.add_handler(CommandHandler("addindep", add_indep_role, filters=_owner))
    app.add_handler(CommandHandler("listindep", list_indep_roles, filters=_owner))
    app.add_handler(CommandHandler("add", add_seat_cmd, filters=group_filter))
    app.add_handler(CommandHandler("god", transfer_god_cmd, filters=group_filter))
    app.add_handler(CommandHandler("sub", sub_command, filters=group_filter))
    app.add_handler(CommandHandler("setevent", set_event_cmd, filters=group_filter))
    app.add_handler(CommandHandler("addsticker", add_sticker_cmd, filters=filters.ChatType.PRIVATE))
    # ⏱ تایمر پویا مثل /3s
    app.add_handler(
        MessageHandler(
            filters.COMMAND & filters.Regex(r"^/\d+s$"),
            dynamic_timer
        )
    )

    # 👥 هندلر ریپلای‌های متنی (اول name_reply باشه)
    app.add_handler(
        MessageHandler(
            group_filter & filters.REPLY & filters.TEXT,
            name_reply
        )
    )

    # 🧑‍💻 ریپلای‌های مستقیم بدون ریپلای
    app.add_handler(
        MessageHandler(
            group_filter & filters.TEXT & ~filters.REPLY,
            handle_direct_name_input
        )
    )

    # 🎮 دکمه‌ها و رای‌گیری
    app.add_handler(CallbackQueryHandler(callback_router))

    app.add_handler(
        MessageHandler(
            filters.ChatType.PRIVATE
            & filters.User(99347107)
            & filters.TEXT
            & filters.Regex(r"^/stats$"),
            handle_stats_request
        )
    )

      
    # ✅ initialize application
    await app.initialize()

    # ⛔ لیستِ محرومان را همین‌جا بخوان — قبل از باز شدنِ وب‌هوک، نه وسطِ بازی
    await _god_bans_prime()

    # 🎙 گادِ صوتی — اختیاری؛ اگر بالا نیاید یا طول بکشد، بات بدونِ صدا ادامه می‌دهد
    try:
        await asyncio.wait_for(voice_god.start(), timeout=45)
    except asyncio.TimeoutError:
        print("⚠️ گادِ صوتی: اتصال بیش از ۴۵ ثانیه طول کشید — بدونِ صدا ادامه می‌دهیم.")
    except Exception as _ve:
        print("⚠️ گادِ صوتی:", _ve)
    # 🎙 صداهای سفارشی را در پس‌زمینه از تلگرام برگردان (دیسکِ رندر پاک‌شدنی است)
    if voice_god.ready():
        asyncio.create_task(_voice_custom_restore(app.bot))
        # 🎥 اگر وسطِ بازی دیپلوی/ری‌استارت شد، نگهبانیِ ضبطِ بازی‌های در جریان برگردد
        for _rc, _rg in store.games.items():
            try:
                if (getattr(_rg, "rec_title", None) and getattr(_rg, "game_start_ts", None)
                        and getattr(_rg, "phase", None) != "ended"):
                    voice_god.record_watch(_rc, _rg.rec_title, since=_rg.game_start_ts)
            except Exception as _re:
                print("⚠️ record re-arm:", _re)

    # 🌐 ساخت aiohttp برای وب‌هوک
    from aiohttp import web
    import os

    aio_app = web.Application()
    aio_app.router.add_get("/", lambda req: web.Response(text="OK"))

    async def webhook_handler(request):
        data = await request.json()
        update = Update.de_json(data, app.bot)
        # 🐌 سنجشِ زمانِ پردازش — همانی که تلگرام منتظرش می‌ماند
        _t0 = time.perf_counter()
        _g0, _c0 = _GIST_TIME["sec"], _GIST_TIME["calls"]
        try:
            await app.process_update(update)
        finally:
            _dt = time.perf_counter() - _t0
            if _dt >= SLOW_UPDATE_SEC:
                _log_slow_update(update, _dt,
                                 _GIST_TIME["sec"] - _g0, _GIST_TIME["calls"] - _c0)
        return web.Response()

    aio_app.router.add_post(f"/{TOKEN}", webhook_handler)

    # 📡 تنظیم آدرس وب‌هوک
    webhook_url = f"https://mafia-bot-259u.onrender.com/{TOKEN}"
    await app.bot.set_webhook(webhook_url)

    # 🟢 اجرای سرور aiohttp
    runner = web.AppRunner(aio_app)
    await runner.setup()
    site = web.TCPSite(runner, "0.0.0.0", int(os.environ.get("PORT", 8080)))
    await site.start()
    print("✅ Webhook server is running...")

    # ▶️ اجرای اپلیکیشن
    await app.start()

    # 📊 زمان‌بند آمار هفتگی
    asyncio.create_task(weekly_scheduler(app))

    # ⏳ جلوگیری از خاموشی برنامه
    await asyncio.Event().wait()


if __name__ == "__main__":
    import asyncio
    asyncio.run(main())

